// @ts-nocheck
/* eslint-disable @typescript-eslint/no-unused-vars, @typescript-eslint/no-explicit-any, react-hooks/exhaustive-deps, react-hooks/rules-of-hooks, @typescript-eslint/ban-ts-comment */

import React, { useEffect, Suspense, useMemo, startTransition, useRef, useCallback } from 'react';
import { registerAppQueryClient } from './utils/queryClientHolder';
import Dashboard from './components/Dashboard';
import BottomNav from './components/BottomNav';
import LeftDrawer from './components/singlepage/LeftDrawer';
import MealPlan from './components/MealPlan';
import AIChatScreen from './components/AIChatScreen';
// DetailScreen组件已由AppModals组件统一管理，不再需要单独导入
import ProfileScreen from './components/ProfileScreen';
import DateSelectionPage from './components/DateSelectionPage';
import MealPlanConfirmationModal from './components/MealPlanConfirmationModal';
import { DeliveryPlanConfirmationModal, type DeliveryPlanConfirmationData } from './components/delivery/DeliveryPlanConfirmationModal';
import OnboardingFlow from './components/onboarding/OnboardingFlow';
// DeliveryPlanPage 直接导入，避免 "Failed to fetch dynamically imported module" 报错
import DeliveryPlanPage from './components/DeliveryPlanPage';
import { NutritionSolutionPageFallback } from './components/onboarding/NutritionSolutionPageFallback';
import {
  LazyAddDeliveryAddressPage,
  LazyHealthReportView,
  LazyNutritionSolutionPage,
  LazyCustomReportScreen,
  LazyMyReportsScreen,
  LazyMyOrdersScreen,
  LazyMyDevicesScreen,
  LazyProfileSettingsScreen,
} from './components/lazy/LazyComponents';
import { OnboardingProvider } from './contexts/OnboardingContext';
import LoginPage from './components/LoginPage';
import DevToolsPanel from './components/DevToolsPanel';
import { DayData } from './utils/mockData';
import { calculateStepsData } from './services/calorieCalculations';
import { useUserProfile } from './contexts/UserProfileContext';
import { useAuth } from './contexts/AuthContext';
import { supabase } from './config/supabase';
import { saveMealPlanConfig, getMealPlanConfig } from './services/mealPlanConfigService';
import { StorageMonitor } from './services/StorageMonitor';
import { toLocalDateString } from './utils/dateUtils';
import { getUserStorageItem, setUserStorageItem, removeUserStorageItem, getCurrentUserId } from './utils/userStorage';
import { useExerciseRecordsQuery } from './hooks/useExerciseRecordsQuery';
import { useDashboardData } from './hooks/useDashboardData';
import { useCalendarLogic } from './hooks/useCalendarLogic';
import { AppModals } from './components/AppModals';
import { AppHeader } from './components/AppHeader';
import { APP_HEADER_HEIGHT_CSS } from './constants/appLayout';
import { AlertDialog } from './components/common/AlertDialog';
import { AppRouter } from './components/AppRouter';
import type { RealtimeMetricKind } from './components/singlepage/TopSummaryRowContext';
import { useAppOnboarding } from './hooks/useAppOnboarding';
import { useAppNavigation } from './hooks/useAppNavigation';
import { useAppMealPlan } from './hooks/useAppMealPlan';
import { useAppPreferences } from './hooks/useAppPreferences';
import { useAppModals } from './hooks/useAppModals';
import { useAppFoodDetail } from './hooks/useAppFoodDetail';
import { useExecutionProgram } from './hooks/useExecutionProgram';
import { useDailyTasks } from './hooks/useDailyTasks';
import { useAutoConfirmPendingEntries } from './hooks/useAutoConfirmPendingEntries';
import { deliveryScheduleService } from './services/deliveryScheduleService';
import { nutritionSyncService } from './services/nutritionSyncService';
import { executionProgramService } from './services/executionProgramService';
import { orderService } from './services/orderService';
import { useQueryClient } from '@tanstack/react-query';
import { TODAY_CONSUMED_MEALS_KEY } from './hooks/useTodayConsumedMeals';
import { getMealKey } from './utils/deliveryPlanUtils';
import {
  fetchLatestPaidOrderProductMeta,
  fetchMealSlotsEnForOrderId,
  fetchContractMealSlotsEnForUser,
} from './services/orderMealPlanSlots';
import { intersectMealTypesEn, includedMealTypesZhToEn } from './utils/mealSlotMapping';

function App() {
  const { isAuthenticated, loading: authLoading, hasActiveSession } = useAuth();
  const { profile, isLoading, refreshProfile, userPackage, mealPlanConfigured, mealPlanConfig, refreshMealPlanConfig, userId, refreshHealthAssessment, isLoadingPackage, isLoadingAssessment } = useUserProfile();
  const userWeight = profile?.current_weight || 70;

  // 🔥 关键修复：使用 ref 存储最新的 profile，避免闭包问题
  const profileRef = useRef(profile);
  useEffect(() => {
    profileRef.current = profile;
  }, [profile]);

  // 使用 React Query Hook 替代 healthAPI
  const { addRecord: addExerciseRecord } = useExerciseRecordsQuery();

  // ✅ 执行引擎Hooks
  const { program: executionProgram, hasOrder, isLoadingOrder, isLoading: isLoadingExecutionProgram } =
    useExecutionProgram();
  const { completeTask: completeExecutionTask } = useDailyTasks(executionProgram?.id || null);
  const queryClient = useQueryClient();

  /** 开通阶段：模拟支付或未回写 paid 时，仍以执行计划、user_packages 或已保存配送配置为准，避免误判为散客模拟态 */
  const effectiveHasOrder = useMemo(
    () =>
      Boolean(
        hasOrder ||
        executionProgram ||
        (mealPlanConfigured && mealPlanConfig?.selectedDates && mealPlanConfig.selectedDates.length > 0) ||
        (userPackage != null && 'id' in userPackage)
      ),
    [hasOrder, executionProgram, mealPlanConfigured, mealPlanConfig?.selectedDates, userPackage]
  );

  /** 订单/执行计划仍在拉取时勿误判为无服务，避免餐食/补剂误进模拟态 */
  const orderGateLoading = Boolean(isLoadingOrder || isLoadingExecutionProgram);

  useEffect(() => {
    registerAppQueryClient(queryClient);
    return () => registerAppQueryClient(null);
  }, [queryClient]);

  // 待办自动确认：登录后检查过期待办，并在每天 23:59 自动确认当日未处理项
  useAutoConfirmPendingEntries();

  // ✅ 使用提取的Hooks管理状态
  const onboarding = useAppOnboarding();
  const navigation = useAppNavigation();
  const mealPlan = useAppMealPlan();
  const preferences = useAppPreferences(userId, isAuthenticated, authLoading);
  const modals = useAppModals();

  const foodDetail = useAppFoodDetail();

  // 解构以保持向后兼容
  const {
    showOnboarding, setShowOnboarding,
    isReassessment, setIsReassessment,
    checkingOnboarding, setCheckingOnboarding,
    checkingOnboardingAfterLogin, setCheckingOnboardingAfterLogin,
    onboardingJustCompleted, setOnboardingJustCompleted,
    initialAppReady, setInitialAppReady,
    showOnboardingNutritionSolution, setShowOnboardingNutritionSolution,
    onboardingCheckLockRef,
  } = onboarding;

  // P0-3: 引导判定诊断（仅开发态 + 开关开启）
  // 开启方式：
  // 1) .env: VITE_ONBOARDING_DIAG=true
  // 2) 控制台: localStorage.setItem('debug:onboarding', '1')
  const onboardingDiagEnabled = useMemo(() => {
    if (!import.meta.env.DEV) return false;
    const envFlag = String(import.meta.env.VITE_ONBOARDING_DIAG || '').toLowerCase();
    if (envFlag === '1' || envFlag === 'true' || envFlag === 'on') return true;
    try {
      const lsFlag = String(localStorage.getItem('debug:onboarding') || '').toLowerCase();
      return lsFlag === '1' || lsFlag === 'true' || lsFlag === 'on';
    } catch {
      return false;
    }
  }, []);

  const onboardingDiag = React.useCallback((stage: string, extra: Record<string, unknown> = {}) => {
    if (!onboardingDiagEnabled) return;
    console.log(`[OnboardingDiag] ${stage}`, {
      ...extra,
      snapshot: {
        isAuthenticated,
        authLoading,
        hasActiveSession,
        profileLoading: isLoading,
        profileHasSeen: profile?.has_seen_onboarding ?? null,
        showOnboarding,
        checkingOnboarding,
        checkingOnboardingAfterLogin,
        onboardingJustCompleted,
      },
      at: new Date().toISOString(),
    });
  }, [
    onboardingDiagEnabled,
    isAuthenticated,
    authLoading,
    hasActiveSession,
    isLoading,
    profile?.has_seen_onboarding,
    showOnboarding,
    checkingOnboarding,
    checkingOnboardingAfterLogin,
    onboardingJustCompleted,
  ]);

  const {
    currentScreen, setCurrentScreen,
    showCalendar, setShowCalendar,
    selectedDate, setSelectedDate,
    displayedWeekStart, setDisplayedWeekStart,
    chatSelectedDate, setChatSelectedDate,
  } = navigation;

  const currentScreenRef = useRef(currentScreen);
  currentScreenRef.current = currentScreen;

  const [showLeftDrawer, setShowLeftDrawer] = React.useState(false);
  const [showNoOrderAlert, setShowNoOrderAlert] = React.useState(false);
  const [deliveryPlanToast, setDeliveryPlanToast] = React.useState<{ show: boolean; message: string }>({
    show: false,
    message: '',
  });
  const [openDeliveryPlanAsGenerated, setOpenDeliveryPlanAsGenerated] = React.useState(false);
  const [activeOrderDurationDays, setActiveOrderDurationDays] = React.useState<number | null>(null);
  /** 当前订单商品关联餐食疗程的餐次（英文 key），与日期选择/地址/配送计划一致 */
  const [activeOrderIncludedMealsEn, setActiveOrderIncludedMealsEn] = React.useState<string[] | null>(null);
  const [activeServiceOrderId, setActiveServiceOrderId] = React.useState<string | null>(null);
  const [deliveryPlanEntrySource, setDeliveryPlanEntrySource] = React.useState<'mealplan' | 'profile' | null>(null);

  // 使用useDashboardData Hook替代原有的数据获取逻辑
  const {
    realTimeData,
    loadingDayData,
    userDayDataOverrides,
    setUserDayDataOverrides,
    loadDayData,
    updateDayData,
    getCurrentDateData,
    formatDateKey,
  } = useDashboardData({
    userId,
    selectedDate,
    profile,
    showOnboarding,
  });

  // 使用Hook返回的getCurrentDateData函数获取当前日期数据（使用 useMemo 缓存，避免不必要的重新创建）
  // 必须在所有条件返回之前调用，遵守 Hooks 规则
  const currentDateData = useMemo(() => {
    return getCurrentDateData();
  }, [getCurrentDateData]); // getCurrentDateData 是 useCallback，依赖项已包含 selectedDate, realTimeData, userDayDataOverrides
  // ✅ Modal状态已迁移到useAppModals Hook
  const {
    modals: modalStates,
    openWeightDetail, closeWeightDetail,
    openWaterDetail, closeWaterDetail,
    openStepsDetail, closeStepsDetail,
    openMeasurementsDetail, closeMeasurementsDetail,
    openBodyCompositionDetail, closeBodyCompositionDetail,
    openExerciseDetail, closeExerciseDetail,
    openExerciseStatsDetail, closeExerciseStatsDetail,
    openHealthRingsDetail, closeHealthRingsDetail,
    openFoodDetail, closeFoodDetail,
    openAISettings, closeAISettings,
    openEmotionJar, closeEmotionJar,
    openSleepDetail, closeSleepDetail,
    openBloodGlucoseDetail, closeBloodGlucoseDetail,
    openEditDashboard, closeEditDashboard,
    openNutritionDetail, closeNutritionDetail,
    openProfileSettings, closeProfileSettings,
    openMyHealthProfile, closeMyHealthProfile,
    openReports, closeReports,
    openHealthReport, closeHealthReport,
    openNutritionSolution, closeNutritionSolution,
    openOrders, closeOrders,
    openDevices, closeDevices,
    openAddressManagement, closeAddressManagement,
    openCustomReport, closeCustomReport,
    openExclusivePlanHub, closeExclusivePlanHub,
  } = modals;

  /** 聊天区「实时数据」四宫格：先切健康档案，再延迟打开对应详情层 */
  const REALTIME_CARD_DETAIL_DELAY_MS = 1000;
  const realtimeCardOpenTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  /** 从聊天实时数据四宫格进入详情：关闭详情时应回到主界面(ai)，而非留在健康档案 */
  const realtimeDetailReturnToMainRef = useRef(false);
  const handleRealtimeCardClick = useCallback(
    (kind: RealtimeMetricKind) => {
      setCurrentScreen('dashboard');
      if (realtimeCardOpenTimerRef.current) {
        clearTimeout(realtimeCardOpenTimerRef.current);
        realtimeCardOpenTimerRef.current = null;
      }
      realtimeCardOpenTimerRef.current = setTimeout(() => {
        realtimeCardOpenTimerRef.current = null;
        if (currentScreenRef.current !== 'dashboard') return;
        realtimeDetailReturnToMainRef.current = true;
        switch (kind) {
          case 'weight':
            openWeightDetail();
            break;
          case 'blood_glucose':
            openBloodGlucoseDetail();
            break;
          case 'calorie_deficit':
            openHealthRingsDetail();
            break;
          case 'steps':
            openStepsDetail();
            break;
          default:
            break;
        }
      }, REALTIME_CARD_DETAIL_DELAY_MS);
    },
    [setCurrentScreen, openWeightDetail, openBloodGlucoseDetail, openHealthRingsDetail, openStepsDetail]
  );

  const handleCloseWeightDetail = useCallback(() => {
    closeWeightDetail();
    if (realtimeDetailReturnToMainRef.current) {
      realtimeDetailReturnToMainRef.current = false;
      setCurrentScreen('ai');
    }
  }, [closeWeightDetail, setCurrentScreen]);

  const handleCloseStepsDetail = useCallback(() => {
    closeStepsDetail();
    if (realtimeDetailReturnToMainRef.current) {
      realtimeDetailReturnToMainRef.current = false;
      setCurrentScreen('ai');
    }
  }, [closeStepsDetail, setCurrentScreen]);

  const handleCloseHealthRingsDetail = useCallback(() => {
    closeHealthRingsDetail();
    if (realtimeDetailReturnToMainRef.current) {
      realtimeDetailReturnToMainRef.current = false;
      setCurrentScreen('ai');
    }
  }, [closeHealthRingsDetail, setCurrentScreen]);

  const handleCloseBloodGlucoseDetail = useCallback(() => {
    closeBloodGlucoseDetail();
    if (realtimeDetailReturnToMainRef.current) {
      realtimeDetailReturnToMainRef.current = false;
      setCurrentScreen('ai');
    }
  }, [closeBloodGlucoseDetail, setCurrentScreen]);

  useEffect(() => {
    return () => {
      if (realtimeCardOpenTimerRef.current) {
        clearTimeout(realtimeCardOpenTimerRef.current);
        realtimeCardOpenTimerRef.current = null;
      }
    };
  }, []);

  // ✅ 餐食计划状态已迁移到useAppMealPlan Hook
  // 解构以保持向后兼容
  const {
    tempSelectedAddressId, setTempSelectedAddressId,
    tempSelectedDates, setTempSelectedDates,
    tempExcludedDates, setTempExcludedDates,
    tempSelectedMealTypes, setTempSelectedMealTypes,
    selectedOrderDates, setSelectedOrderDates,
    selectedMealTypes, setSelectedMealTypes,
    selectedDeliveryAddressId, setSelectedDeliveryAddressId,
    deliveryPlanStartDate, setDeliveryPlanStartDate,
    deliveryPlanEndDate, setDeliveryPlanEndDate,
    deliveryPlanDates, setDeliveryPlanDates,
    mealTypeToOpenFoodDetailWith, setMealTypeToOpenFoodDetailWith,
    isOpenedFromDeliveryPlan, setIsOpenedFromDeliveryPlan,
    isOpenedFromOrders, setIsOpenedFromOrders,
    mealAddresses, setMealAddresses,
    showMealPlanConfirmationModal, setShowMealPlanConfirmationModal,
    showDateSelectionPage, setShowDateSelectionPage,
    showAddDeliveryAddressPage, setShowAddDeliveryAddressPage,
    showDeliveryPlanPage, setShowDeliveryPlanPage,
    showDeliveryPlanConfirmationModal, setShowDeliveryPlanConfirmationModal,
    pendingDeliveryPlanConfirmation, setPendingDeliveryPlanConfirmation,
  } = mealPlan;

  // 🔥 修复：页面刷新后，从 mealPlanConfig 恢复配送计划日期，确保定制食谱等页面能正确显示
  useEffect(() => {
    if (mealPlanConfigured && mealPlanConfig?.startDate && mealPlanConfig?.endDate && mealPlanConfig?.selectedDates?.length) {
      setDeliveryPlanStartDate(mealPlanConfig.startDate);
      setDeliveryPlanEndDate(mealPlanConfig.endDate);
      setDeliveryPlanDates(mealPlanConfig.selectedDates);
    }
  }, [mealPlanConfigured, mealPlanConfig?.startDate, mealPlanConfig?.endDate, mealPlanConfig?.selectedDates, setDeliveryPlanStartDate, setDeliveryPlanEndDate, setDeliveryPlanDates]);

  // ✅ 用户偏好状态已迁移到useAppPreferences Hook
  // 解构以保持向后兼容
  const {
    dashboardCardOrder, setDashboardCardOrder,
    hiddenDashboardCards, setHiddenDashboardCards,
    updateCardOrder,
    updateHiddenCards,
  } = preferences;

  // ✅ 从modalStates解构所有show*变量以保持向后兼容
  const {
    showWeightDetailScreen,
    showWaterDetailScreen,
    showStepsDetailScreen,
    showMeasurementsDetailScreen,
    showBodyCompositionDetailScreen,
    showExerciseDetailScreen,
    showExerciseStatsDetailScreen,
    showHealthRingsDetailScreen,
    showFoodDetailScreen,
    showAISettingsScreen,
    showEmotionJarScreen,
    showSleepDetailScreen,
    showBloodGlucoseDetailScreen,
    showEditDashboardScreen,
    showNutritionDetailScreen,
    showProfileSettingsScreen,
    showMyHealthProfileScreen,
    showReportsScreen,
    showHealthReportPage,
    showNutritionSolutionPage,
    showOrdersScreen,
    showDevicesScreen,
    showAddressManagementScreen,
    showCustomReportScreen,
  } = modalStates;

  // ✅ 食物详情状态已迁移到useAppFoodDetail Hook
  const {
    foodDetailScreenDate, setFoodDetailScreenDate,
    nutritionRefreshKey,
    refreshNutrition,
  } = foodDetail;

  // Refs for tracking auth state change handling (must be at component top level)
  const hasHandledInitialSessionRef = React.useRef(false);
  const hasHandledSignedInRef = React.useRef(false);
  const onboardingStatusCacheRef = React.useRef<{ hasSeenOnboarding: boolean | null; timestamp: number } | null>(null);

  // P0：弱网下 DB 查询超时后，档案晚到且 has_seen_onboarding=false 时补开展示引导
  useEffect(() => {
    if (!isAuthenticated || authLoading || onboardingJustCompleted) return;
    if (isLoading) return;
    if (onboardingStatusCacheRef.current?.hasSeenOnboarding === true) return;
    if (!profile || profile.has_seen_onboarding !== false) return;
    if (!showOnboarding) {
      setShowOnboarding(true);
    }
  }, [isAuthenticated, authLoading, isLoading, profile, onboardingJustCompleted, showOnboarding, setShowOnboarding]);

  // 初始化存储空间监控（应用启动时）
  useEffect(() => {
    StorageMonitor.initialize();
  }, []);

  // 预加载常用页面组件，避免首次打开时的延迟和抖动
  useEffect(() => {
    if (isAuthenticated && !authLoading) {
      // 预加载"我的"相关页面组件
      import('./components/MyOrdersScreen');
      import('./components/MyReportsScreen');
      import('./components/ProfileSettingsScreen');
      import('./components/MyHealthProfileScreen');
      import('./components/MyDevicesScreen');
    }
  }, [isAuthenticated, authLoading]);


  // ✅ 用户偏好配置加载已迁移到useAppPreferences Hook

  // 加载其他localStorage数据
  useEffect(() => {
    const loadOtherUserData = async () => {
      try {
        const [overrides, addresses] = await Promise.all([
          getUserStorageItem<Record<string, Partial<DayData>>>('userDayDataOverrides'),
          getUserStorageItem<Record<string, string>>('mealAddresses'),
        ]);

        if (overrides) setUserDayDataOverrides(overrides);
        if (addresses) setMealAddresses(addresses);
      } catch (error) {
        console.error('[App] Error loading other user data from localStorage:', error);
      }
    };

    if (isAuthenticated && !authLoading) {
      loadOtherUserData();
    }
  }, [isAuthenticated, authLoading]);

  useEffect(() => {
    const clearOnboardingState = async () => {
      console.log('🧹 [App] Clearing all onboarding state from localStorage');

      // Use user-isolated storage functions
      await Promise.all([
        removeUserStorageItem('onboarding_step'),
        removeUserStorageItem('onboarding_data'),
        removeUserStorageItem('onboarding_completed'),
        removeUserStorageItem('onboarding_skipped'),
        removeUserStorageItem('health_report_saved'),
        removeUserStorageItem('step14_profile_saved')
      ]);

      // CRITICAL: Clear chat cache only for current user
      try {
        const currentUserId = await getCurrentUserId();
        if (currentUserId) {
          const keysToRemove: string[] = [];
          const userIdPart = `:user:${currentUserId}`;

          for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key && (
              (key.includes('chat_messages') && key.includes(userIdPart)) || 
              (key.includes('chat_history') && key.includes(userIdPart)) ||
              (key.startsWith('cache:chat_messages') && key.includes(userIdPart)) ||
              (key.startsWith('records:chat_messages') && key.includes(userIdPart))
            )) {
              keysToRemove.push(key);
            }
          }

          keysToRemove.forEach(key => localStorage.removeItem(key));
          console.log(`✅ [App] Cleared ${keysToRemove.length} chat cache items for user ${currentUserId}`);
        } else {
          console.log('⚠️ [App] No current user ID, skipping chat cache cleanup');
        }
      } catch (error) {
        console.error('❌ [App] Error clearing chat cache:', error);
      }

      console.log('✅ [App] Onboarding and chat state cleared');
    };

    const checkOnboardingStatus = async (onStatusDetermined?: () => void) => {
      onboardingDiag('check:start', { lock: onboardingCheckLockRef.current });
      // 检查锁：防止重复执行
      if (onboardingCheckLockRef.current) {
        console.log('⏸️ [App] Onboarding check already in progress, skipping duplicate check');
        onboardingDiag('check:skip-locked');
        onStatusDetermined?.(); // 🔥 修复：即使跳过，也标记为已确定
        return;
      }

      try {
        onboardingCheckLockRef.current = true;

        // CRITICAL: Skip check if onboarding just completed (prevents race condition)
        if (onboardingJustCompleted) {
          console.log('⏸️ [App] Onboarding just completed, skipping status check to prevent redirect');
          onboardingDiag('check:skip-onboarding-just-completed');
          setCheckingOnboarding(false);
          onboardingCheckLockRef.current = false;
          onStatusDetermined?.(); // 🔥 修复：标记状态已确定
          return;
        }

        // CRITICAL: Skip check if onboarding is currently showing (prevents redirect during onboarding flow)
        if (showOnboarding) {
          console.log('⏸️ [App] Onboarding is currently showing, skipping status check to prevent redirect');
          onboardingDiag('check:skip-onboarding-visible');
          setCheckingOnboarding(false);
          onboardingCheckLockRef.current = false;
          onStatusDetermined?.(); // 🔥 修复：标记状态已确定
          return;
        }

        // CRITICAL: Check cache first - if we recently confirmed user has completed onboarding, use that
        if (onboardingStatusCacheRef.current) {
          const cacheAge = Date.now() - onboardingStatusCacheRef.current.timestamp;
          if (cacheAge < 10000 && onboardingStatusCacheRef.current.hasSeenOnboarding === true) {
            console.log('✅ [App] Using cached onboarding status - user has completed onboarding');
            setShowOnboarding(false);
            setCheckingOnboarding(false);
            onboardingCheckLockRef.current = false;
            onStatusDetermined?.(); // 🔥 修复：标记状态已确定
            return;
          }
        }

        // CRITICAL: Check UserProfileContext first - if profile already loaded and shows completed, use that
        // 🔥 添加调试日志（先获取 user，避免作用域问题）
        const { data: { user: currentUser } } = await supabase.auth.getUser();

        // 🔥 关键修复：使用 ref 获取最新的 profile 值，避免闭包问题
        // 不要依赖闭包中的旧值，使用 ref 获取最新的 profile
        const currentProfile = profileRef.current; // 使用 ref 获取最新值

        console.log('🔍 [App] checkOnboardingStatus - Profile data:', {
          profile: currentProfile ? {
            has_seen_onboarding: currentProfile.has_seen_onboarding,
            user_id: currentProfile.display_user_id || currentProfile.user_id,
          } : null,
          isLoading,
          userId: currentUser?.id,
          profileFromRef: !!profileRef.current,
          profileFromClosure: !!profile,
        });

        // Use the user we already fetched above
        const user = currentUser;

        if (!user) {
          // No authenticated user - clear any stale localStorage and show welcome page
          // 🔥 修复：减少日志输出
          await clearOnboardingState();
          // CRITICAL: Force close onboarding flow if it was open
          setShowOnboarding(false);
          setCheckingOnboarding(false);
          onStatusDetermined?.(); // 🔥 修复：标记状态已确定
          return;
        }

        // User is authenticated - check database for onboarding status
        console.log('👤 [App] User authenticated:', user.id);

        // 🔥 关键修复：优先使用 UserProfileContext 的数据（即使 isLoading，也可能已经有数据）
        // 不要等待 isLoading 完成，直接检查 profile 对象
        if (currentProfile?.has_seen_onboarding === true) {
          // UserProfileContext 已经有数据且显示用户已完成引导，直接使用
          console.log(`✅ [App] UserProfileContext has onboarding status - has_seen_onboarding: true, skipping onboarding`);
          onboardingStatusCacheRef.current = {
            hasSeenOnboarding: true,
            timestamp: Date.now()
          };
          // 🔥 关键修复：如果用户已完成引导，强制设置为 false，不要显示引导页
          setShowOnboarding(false);
          setCheckingOnboarding(false);
          setCheckingOnboardingAfterLogin(false);
          onboardingCheckLockRef.current = false;
          onboardingDiag('decision:profile-context-completed');
          onStatusDetermined?.();
          return;
        }

        if (currentProfile?.has_seen_onboarding === false) {
          // UserProfileContext 已经有数据且显示用户需要引导
          console.log(`📋 [App] UserProfileContext has onboarding status - has_seen_onboarding: false, showing onboarding`);
          onboardingStatusCacheRef.current = {
            hasSeenOnboarding: false,
            timestamp: Date.now()
          };
          setShowOnboarding(true);
          setCheckingOnboarding(false);
          setCheckingOnboardingAfterLogin(false);
          onboardingCheckLockRef.current = false;
          onboardingDiag('decision:profile-context-needs-onboarding');
          onStatusDetermined?.();
          return;
        }

        // 🔥 新增：如果 profile 还在加载，但缓存显示用户已完成引导，直接使用缓存
        if (isLoading && onboardingStatusCacheRef.current?.hasSeenOnboarding === true) {
          const cacheAge = Date.now() - onboardingStatusCacheRef.current.timestamp;
          if (cacheAge < 300000) { // 5分钟内的缓存有效
            console.log('✅ [App] Using cached onboarding status (profile still loading): hasSeenOnboarding = true');
            setShowOnboarding(false);
            setCheckingOnboarding(false);
            setCheckingOnboardingAfterLogin(false);
            onboardingCheckLockRef.current = false;
            onStatusDetermined?.();
            return;
          }
        }

        // 🔥 修复：如果 UserProfileContext 还在加载或没有明确状态，直接查询数据库
        // 不再依赖 UserProfileContext 的加载状态来判断是否为新用户
        // 这样可以避免在加载过程中误判，数据库是唯一真实来源
        if (isLoading) {
          console.log('⏳ [App] UserProfileContext is loading, querying database directly to avoid false new user detection');
        } else if (!isLoading && profile === null) {
          console.log('⚠️ [App] UserProfileContext loaded but no profile found, querying database to confirm');
        }

        // 为数据库查询添加超时保护（改进版本：避免未处理的 Promise rejection）
        let profileData: { has_seen_onboarding: boolean } | null = null;
        let profileError: Error | null = null;
        let timeoutId: NodeJS.Timeout | null = null;
        let queryResolved = false;

        try {
          const profileQueryPromise = supabase
            .from('user_profiles')
            .select('has_seen_onboarding')
            .eq('user_id', user.id)
            .maybeSingle();

          // 确保即使超时后，原始 Promise 也不会产生未处理的 rejection
          profileQueryPromise
            .then(() => {
              queryResolved = true;
            })
            .catch(() => {
              queryResolved = true;
              // 静默处理，避免未处理的 Promise rejection 警告
              // 错误已在 Promise.race 的 catch 中处理
            });

          const timeoutPromise = new Promise<never>((_, reject) => {
            timeoutId = setTimeout(() => {
              if (!queryResolved) {
                reject(new Error('Profile query timeout after 6 seconds'));
              }
            }, 6000); // P0：适度放宽，减少弱网下误判；仍以 DB 结果为最终真相
          });

          // 使用 Promise.race，但确保超时后清理
          const result = await Promise.race([
            profileQueryPromise.then(result => {
              // 查询成功，清除超时定时器
              queryResolved = true;
              if (timeoutId) {
                clearTimeout(timeoutId);
                timeoutId = null;
              }
              return result;
            }).catch(err => {
              // 如果查询失败，清除超时定时器
              queryResolved = true;
              if (timeoutId) {
                clearTimeout(timeoutId);
                timeoutId = null;
              }
              throw err;
            }),
            timeoutPromise
          ]);

          profileData = result.data;
          profileError = result.error;
        } catch (error) {
          // 捕获超时或其他错误
          queryResolved = true;
          if (timeoutId) {
            clearTimeout(timeoutId);
            timeoutId = null;
          }

          if (error instanceof Error && error.message.includes('timeout')) {
            console.warn('⚠️ [App] Profile query timeout - checking UserProfileContext');
            onboardingDiag('db:timeout');
            profileError = error;
          } else {
            console.error('❌ [App] Error querying profile:', error);
            profileError = error instanceof Error ? error : new Error('Unknown error');
          }
        } finally {
          // 确保清理超时定时器
          if (timeoutId) {
            clearTimeout(timeoutId);
          }
        }

        if (profileError) {
          // 🔥 关键修复：查询失败或超时时，优先使用 UserProfileContext 的数据
          // 不要默认显示引导页，优先检查已有数据

          // 1. 首先检查缓存
          if (onboardingStatusCacheRef.current?.hasSeenOnboarding === true) {
            const cacheAge = Date.now() - onboardingStatusCacheRef.current.timestamp;
            if (cacheAge < 300000) { // 5分钟内的缓存有效
              console.log('✅ [App] Profile query failed/timeout, but cache shows user has completed onboarding - using cache');
              setShowOnboarding(false);
              setCheckingOnboarding(false);
              setCheckingOnboardingAfterLogin(false);
              onboardingCheckLockRef.current = false;
              onStatusDetermined?.();
              return;
            }
          }

          // 2. 检查 UserProfileContext（即使 isLoading，也可能已经有数据）
          // 🔥 修复：不要等待，直接检查 profile 对象，即使 isLoading 为 true
          // 🔥 关键修复：使用 currentProfile（最新的值），而不是闭包中的 profile
          if (currentProfile?.has_seen_onboarding === true) {
            console.log('✅ [App] Profile query failed/timeout, but UserProfileContext shows user has completed onboarding - using cached data');
            setShowOnboarding(false);
            setCheckingOnboarding(false);
            setCheckingOnboardingAfterLogin(false);
            onboardingCheckLockRef.current = false;
            // 更新缓存
            onboardingStatusCacheRef.current = {
              hasSeenOnboarding: true,
              timestamp: Date.now()
            };
            onStatusDetermined?.();
            return;
          }

          // 3. DB 失败/超时且 RQ 仍在加载：用 profileRef 即时读档，避免 setInterval 闭包读到陈旧 isLoading
          if (isLoading) {
            const latest = profileRef.current;
            if (latest?.has_seen_onboarding === true) {
              console.log('✅ [App] DB 超时/失败但 profileRef 显示已完成引导');
              onboardingStatusCacheRef.current = { hasSeenOnboarding: true, timestamp: Date.now() };
              setShowOnboarding(false);
              setCheckingOnboarding(false);
              setCheckingOnboardingAfterLogin(false);
              onboardingCheckLockRef.current = false;
              onStatusDetermined?.();
              return;
            }
            if (latest?.has_seen_onboarding === false) {
              console.log('📋 [App] DB 超时/失败但 profileRef 显示需引导');
              onboardingStatusCacheRef.current = { hasSeenOnboarding: false, timestamp: Date.now() };
              setShowOnboarding(true);
              setCheckingOnboarding(false);
              setCheckingOnboardingAfterLogin(false);
              onboardingCheckLockRef.current = false;
              onStatusDetermined?.();
              return;
            }
            console.warn('⚠️ [App] DB 超时/失败且档案仍在加载、尚无明确 has_seen — 暂不进入引导，待 Profile 加载后由 effect 收敛');
            setShowOnboarding(false);
            setCheckingOnboarding(false);
            setCheckingOnboardingAfterLogin(false);
            onboardingCheckLockRef.current = false;
            onStatusDetermined?.();
            return;
          }

          // 4. UserProfileContext 已加载完成，检查数据
          // 🔥 修复：使用 currentProfile（最新的值）
          if (currentProfile === null) {
            // 没有 profile，可能是新用户，显示引导页
            console.log('📋 [App] Profile query failed/timeout and no profile found - showing onboarding');
            startTransition(() => {
              setShowOnboarding(true);
              setCheckingOnboarding(false);
              setCheckingOnboardingAfterLogin(false);
              onboardingCheckLockRef.current = false;
            });
            onStatusDetermined?.();
            return;
          }

          if (currentProfile.has_seen_onboarding === false) {
            // 确认用户需要引导
            console.log('📋 [App] Profile query failed/timeout but profile shows user needs onboarding');
            startTransition(() => {
              setShowOnboarding(true);
              setCheckingOnboarding(false);
              setCheckingOnboardingAfterLogin(false);
              onboardingCheckLockRef.current = false;
            });
            onStatusDetermined?.();
            return;
          }

          // 5. 如果还是不确定，不显示引导页（避免误跳转）
          console.log('⚠️ [App] Profile query failed/timeout but status uncertain - not showing onboarding to avoid false redirect');
          setShowOnboarding(false);
          setCheckingOnboarding(false);
          setCheckingOnboardingAfterLogin(false);
          onboardingCheckLockRef.current = false;
          onStatusDetermined?.();
          return;
        }

        console.log('📊 [App] Profile data from DB:', profileData);

        // CRITICAL: Update cache with the result
        if (profileData?.has_seen_onboarding !== undefined) {
          onboardingStatusCacheRef.current = {
            hasSeenOnboarding: profileData.has_seen_onboarding,
            timestamp: Date.now()
          };
        }

        // Clean up any stale localStorage flags using user-isolated storage
        await Promise.all([
          removeUserStorageItem('onboarding_completed'),
          removeUserStorageItem('onboarding_skipped')
        ]);

        // CRITICAL: If user has completed onboarding, clear any stale onboarding_step
        // This prevents showing onboarding when user has already completed it
        if (profileData?.has_seen_onboarding) {
          console.log('🧹 [App] User has completed onboarding - clearing stale onboarding_step');
          await Promise.all([
            removeUserStorageItem('onboarding_step'),
            removeUserStorageItem('onboarding_data'),
            removeUserStorageItem('health_report_saved')
          ]);
        }

        // Decision logic: Database is the single source of truth
        // 🔥 修复：使用 startTransition 批量更新状态，避免多次重新渲染
        const needsOnboarding = !profileData || !profileData.has_seen_onboarding;
        console.log('🔍 [App] Final onboarding decision:', {
          hasProfileData: !!profileData,
          has_seen_onboarding: profileData?.has_seen_onboarding,
          needsOnboarding,
        });
          onboardingDiag('decision:final', {
            hasProfileData: !!profileData,
            hasSeenOnboarding: profileData?.has_seen_onboarding ?? null,
            needsOnboarding,
          });

        if (needsOnboarding) {
          // User has not completed onboarding - show onboarding flow
          console.log('🎯 [App] User needs onboarding (has_seen_onboarding: false or no profile)');
        } else {
          // User has completed onboarding - go to app
          console.log('✅ [App] User has completed onboarding - showing app');
          // 🔥 关键修复：确保缓存已更新，并强制不显示引导页
          onboardingStatusCacheRef.current = {
            hasSeenOnboarding: true,
            timestamp: Date.now()
          };
        }
        // 🔥 修复：批量更新状态，避免组件重新挂载，同时清除 checkingOnboardingAfterLogin
        startTransition(() => {
          setShowOnboarding(needsOnboarding);
          setCheckingOnboarding(false);
          setCheckingOnboardingAfterLogin(false);
          onboardingCheckLockRef.current = false;
        });
        onStatusDetermined?.(); // 🔥 修复：标记状态已确定
      } catch (error) {
        console.error('❌ [App] Error checking onboarding status:', error);
      } finally {
        setCheckingOnboarding(false);
        onboardingCheckLockRef.current = false;
      }
    };

    // 添加超时保护：如果3秒后还在加载，强制设置为false（更积极的超时）
    let timeoutId: NodeJS.Timeout | null = null;

    // 🔥 修复：只在用户已认证时设置超时，退出登录时不应该触发超时警告
    if (isAuthenticated || authLoading) {
      timeoutId = setTimeout(async () => {
        // 🔥 修复：在超时回调中检查最新的用户状态，避免使用闭包中的旧值
        const { data: { user } } = await supabase.auth.getUser();
        if (checkingOnboarding && user) {
          console.warn('⚠️ [App] Onboarding check timeout (3s) - forcing completion');
          setCheckingOnboarding(false);
        }
      }, 3000);
    }

    // 🔥 关键修复：在调用 checkOnboardingStatus 之前，先检查缓存和 profile
    // 如果缓存或 profile 显示用户已完成引导，立即设置状态，不要调用 checkOnboardingStatus
    if (onboardingStatusCacheRef.current?.hasSeenOnboarding === true) {
      const cacheAge = Date.now() - onboardingStatusCacheRef.current.timestamp;
      if (cacheAge < 300000) { // 5分钟内的缓存有效（延长缓存时间）
        console.log('✅ [App] Using cached onboarding status on mount - user has completed onboarding');
        setShowOnboarding(false);
        setCheckingOnboarding(false);
        setCheckingOnboardingAfterLogin(false);
        setInitialAppReady(true);
        return;
      }
    }

    // 如果 profile 已加载且显示用户已完成引导，直接使用
    if (!isLoading && profile?.has_seen_onboarding === true) {
      console.log('✅ [App] Profile already loaded - user has completed onboarding');
      setShowOnboarding(false);
      setCheckingOnboarding(false);
      setCheckingOnboardingAfterLogin(false);
      setInitialAppReady(true);
      onboardingStatusCacheRef.current = {
        hasSeenOnboarding: true,
        timestamp: Date.now()
      };
      return;
    }

    // 只有在确实需要时才检查
    if (!isLoading && profile?.has_seen_onboarding === false) {
      console.log('📋 [App] Profile shows user needs onboarding');
      setShowOnboarding(true);
      setCheckingOnboarding(false);
      setCheckingOnboardingAfterLogin(false);
      setInitialAppReady(true);
      return;
    }

    // 如果 profile 还在加载或不确定，才调用 checkOnboardingStatus
    setCheckingOnboarding(true);
    checkOnboardingStatus();

    // Listen for auth state changes (sign in/out)
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      console.log('🔔 [App] Auth state changed:', event);

      if (event === 'SIGNED_OUT') {
        // 🔥 修复：减少日志输出，只在开发环境输出详细信息
        if (import.meta.env.DEV) {
          console.log('👋 [App] User signed out - clearing state');
        }
        // 重置检查锁和标记
        onboardingCheckLockRef.current = false;
        hasHandledInitialSessionRef.current = false;
        hasHandledSignedInRef.current = false;
        // ✅ 偏好加载和保存已迁移到useAppPreferences Hook，无需手动重置
        // Clear all localStorage on sign out
        clearOnboardingState().catch(error => {
          console.error('❌ [App] Error clearing onboarding state on sign out:', error);
        });
        // CRITICAL: Force close any open onboarding flow
        setShowOnboarding(false);
        setCheckingOnboarding(false);
        setCheckingOnboardingAfterLogin(false); // 🔥 修复：也清除这个标志
        onboardingDiag('auth:signed-out');
        // Don't set currentScreen - let the hasActiveSession check handle showing login page
      } else if (event === 'INITIAL_SESSION') {
        // 只在第一次处理 INITIAL_SESSION，避免页面可见性变化时重复触发
        if (!hasHandledInitialSessionRef.current && session?.user) {
          console.log('🔔 [App] Initial session detected (first time), checking onboarding status');
          hasHandledInitialSessionRef.current = true;

          // 🔥 关键修复：立即检查缓存，如果用户已完成引导，立即设置状态
          if (onboardingStatusCacheRef.current?.hasSeenOnboarding === true) {
            const cacheAge = Date.now() - onboardingStatusCacheRef.current.timestamp;
            if (cacheAge < 60000) { // 1分钟内的缓存有效
              console.log('✅ [App] Initial session - Using cached onboarding status (user has completed)');
              setShowOnboarding(false);
              setCheckingOnboarding(false);
              setCheckingOnboardingAfterLogin(false);
              onboardingDiag('auth:initial-session-use-cache-completed');
              return;
            }
          }

          // CRITICAL: 如果 UserProfileContext 已经有数据，直接使用，不需要查询数据库
          if (profile?.has_seen_onboarding === true) {
            console.log('✅ [App] Initial session - UserProfileContext already has data, user has completed onboarding');
            setShowOnboarding(false);
            setCheckingOnboarding(false);
            setCheckingOnboardingAfterLogin(false);
            onboardingStatusCacheRef.current = { hasSeenOnboarding: true, timestamp: Date.now() };
            return;
          }

          // 等待UserProfileContext加载完数据（但缩短延迟）
          setTimeout(async () => {
            // 再次检查 UserProfileContext，可能已经加载完成
            if (profile?.has_seen_onboarding === true) {
              console.log('✅ [App] Initial session - UserProfileContext loaded, user has completed onboarding');
              setShowOnboarding(false);
              setCheckingOnboarding(false);
              setCheckingOnboardingAfterLogin(false);
              onboardingStatusCacheRef.current = { hasSeenOnboarding: true, timestamp: Date.now() };
              onboardingDiag('auth:initial-session-profile-completed');
              return;
            }
            // 🔥 修复：只有在确实需要时才调用 checkOnboardingStatus
            // 如果缓存显示用户已完成，不要调用
            if (onboardingStatusCacheRef.current?.hasSeenOnboarding !== true) {
              console.log('🔄 [App] Initial session - checking onboarding status after data load');
              await checkOnboardingStatus();
            }
          }, 300); // 🔥 优化：从800ms减少到300ms，加快响应
        } else {
          console.log('⏭️ [App] Ignoring INITIAL_SESSION (already handled or no session)');
        }
      } else if (event === 'SIGNED_IN') {
        // 只在第一次处理 SIGNED_IN，避免页面可见性变化时重复触发
        if (!hasHandledSignedInRef.current) {
          console.log('🔑 [App] User signed in (first time) - checking onboarding status');
          hasHandledSignedInRef.current = true;

          // 设置检查标志，防止首页闪烁
          setCheckingOnboardingAfterLogin(true);

          let onboardingStatusDetermined = false;

          // P0：超时不再「一律进引导」，用 profileRef 再判，避免老用户弱网误进 Onboarding
          const signedInTimeoutId = setTimeout(() => {
            if (onboardingStatusDetermined) return;
            console.warn('⚠️ [App] SIGNED_IN onboarding check timeout (5s) — resolving from profileRef');
            const p = profileRef.current;
            startTransition(() => {
              setCheckingOnboardingAfterLogin(false);
              setCheckingOnboarding(false);
              onboardingCheckLockRef.current = false;
              if (p?.has_seen_onboarding === true) {
                setShowOnboarding(false);
                onboardingStatusCacheRef.current = { hasSeenOnboarding: true, timestamp: Date.now() };
              } else if (p?.has_seen_onboarding === false) {
                setShowOnboarding(true);
              } else {
                setShowOnboarding(false);
              }
            });
            onboardingDiag('auth:signed-in-timeout-fallback', { profileRefHasSeen: p?.has_seen_onboarding ?? null });
          }, 5000);

          try {
            // 🔥 优化：减少延迟，从100ms减少到50ms，因为UserProfileContext可能已经加载
            await new Promise(resolve => setTimeout(resolve, 50));

            // 执行onboarding检查，添加超时包装
            const checkPromise = checkOnboardingStatus(() => {
              onboardingStatusDetermined = true; // 🔥 修复：通过回调标记状态已确定
            });
            const checkTimeout = new Promise((_, reject) => {
              setTimeout(() => {
                reject(new Error('checkOnboardingStatus timeout'));
              }, 8000);
            });

            await Promise.race([checkPromise, checkTimeout]);
          } catch (error) {
            console.error('❌ [App] Error during onboarding check after login:', error);
          } finally {
            clearTimeout(signedInTimeoutId);

            if (!onboardingStatusDetermined) {
              console.log('✅ [App] Onboarding 状态未在 race 内确定 — 按 profileRef 收敛，不默认强制进引导');
              const p = profileRef.current;
              if (p?.has_seen_onboarding === true) {
                setShowOnboarding(false);
                onboardingStatusCacheRef.current = { hasSeenOnboarding: true, timestamp: Date.now() };
              } else if (p?.has_seen_onboarding === false) {
                setShowOnboarding(true);
              } else {
                setShowOnboarding(false);
              }
              setCheckingOnboardingAfterLogin(false);
              setCheckingOnboarding(false);
              onboardingCheckLockRef.current = false;
              onboardingDiag('auth:signed-in-race-fallback', { profileRefHasSeen: p?.has_seen_onboarding ?? null });
            } else {
              console.log('⏭️ [App] Onboarding status already determined, skipping cleanup');
            }
          }
        } else {
          console.log('⏭️ [App] Ignoring SIGNED_IN (already handled)');
        }
      }
    });

    // 🔥 修复：返回清理函数，清除超时和订阅
    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
      subscription.unsubscribe();
    };
  }, []);

  React.useEffect(() => {
    const today = new Date();
    const weekStart = new Date(today);
    weekStart.setDate(today.getDate() - 6);
    setDisplayedWeekStart(weekStart);
  }, []);

  // Header高度管理已由AppHeader组件内部处理

  // 数据加载已由useDashboardData Hook处理，无需手动加载

  // React Query 会自动处理数据更新，无需监听事件
  // 如果使用 React Query hooks 管理数据，数据会自动刷新

  useEffect(() => {
    // 🔥 修复：总是保存（条件总是为 true 是多余的），但添加防抖避免频繁保存
    setUserStorageItem('userDayDataOverrides', userDayDataOverrides).catch(error => {
      console.error('[App] Error saving userDayDataOverrides:', error);
    });
  }, [userDayDataOverrides]);

  // ✅ 用户偏好保存逻辑已迁移到useAppPreferences Hook，自动保存

  const handleOpenOnboardingNutritionSolution = () => {
    console.log('🥗 [App] Opening Nutrition Solution page during onboarding');
    console.log('🔍 [App] Before setting state - showOnboardingNutritionSolution:', showOnboardingNutritionSolution);
    setShowOnboardingNutritionSolution(true);
    console.log('✅ [App] State update triggered - showOnboardingNutritionSolution should be true now');
  };

  // CRITICAL: Use ref to prevent duplicate execution
  const isHandlingNutritionCompleteRef = React.useRef(false);

  const handleCloseOnboardingNutritionSolution = async () => {
    // CRITICAL: Prevent duplicate execution
    if (isHandlingNutritionCompleteRef.current) {
      console.warn('⚠️ [App] handleCloseOnboardingNutritionSolution already in progress, ignoring duplicate call');
      return;
    }

    console.log('🎉 [App] Nutrition Solution completed - finishing onboarding flow');
    isHandlingNutritionCompleteRef.current = true;

    try {
      // Set flag to prevent redirect during transition - CRITICAL for preventing flash
      setOnboardingJustCompleted(true);
      console.log('🛡️ [App] onboardingJustCompleted flag set to TRUE - preventing checkOnboardingStatus recheck');

      // CRITICAL: Mark onboarding as completed in database
      console.log('💾 [App] Marking onboarding as completed in database...');
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        const { error: updateError } = await supabase
          .from('user_profiles')
          .update({
            has_seen_onboarding: true,
            onboarding_completed: true,
            updated_at: new Date().toISOString()
          })
          .eq('user_id', user.id);

        if (updateError) {
          console.error('❌ [App] Failed to mark onboarding as completed:', updateError);
        } else {
          console.log('✅ [App] Onboarding marked as completed in database');
