// 根据食物名称生成图标
const generateFoodIcon = (name: string): string => {
  const iconMap: { [key: string]: string } = {
    '米饭': '🍚', '米': '🍚',
    '面条': '🍜', '面': '🍜',
    '包子': '🥟', '包': '🥟',
