const CustomSupplementScreen: React.FC<CustomSupplementScreenProps> = ({
  hasOrder = false,
  orderGateLoading = false,
}) => {
  const [supplements, setSupplements] = useState<CustomSupplement[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentCardIndex, setCurrentCardIndex] = useState(0);
  const [isSticky, setIsSticky] = useState(false);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const mainContainerRef = useRef<HTMLDivElement>(null);
  const cardSectionRef = useRef<HTMLDivElement>(null);
  const supplementUtils = useSupplementUtils();
  const { mealPlanConfig, refreshMealPlanConfig } = useUserProfile();
  const [fallbackStartDate, setFallbackStartDate] = useState<string | null>(null);
  const [stageSummary, setStageSummary] = useState<SupplementStageResponse | null>(null);
  const [stageLoading, setStageLoading] = useState(false);
  useEffect(() => {
    loadSupplements();
  }, []);

  useEffect(() => {
    if (!hasOrder) {
      setStageSummary(null);
      setStageLoading(false);
      return;
    }
    setStageLoading(true);
    supplementStageService.getActiveSupplementStage()
      .then(setStageSummary)
      .catch(() => setStageSummary(null))
      .finally(() => setStageLoading(false));
  }, [hasOrder]);

  // 开始时间：打开时刷新配置；mealPlanConfig 为空时从 service 拉取（与配置配送计划同步）
  useEffect(() => {
    refreshMealPlanConfig();
  }, [refreshMealPlanConfig]);
  useEffect(() => {
    if (mealPlanConfig?.startDate) return;
    supabase.auth.getUser().then(({ data: { user } }) => {
      if (user?.id) {
        getMealPlanConfig(user.id).then((cfg) => {
          if (cfg?.startDate) {
            setFallbackStartDate(formatDateShort(cfg.startDate));
          }
        });
      }
    });
  }, [mealPlanConfig?.startDate]);

  const loadSupplements = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        setLoading(false);
        return;
      }

      const { data, error } = await supabase
        .from('custom_supplements')
        .select('*')
        .eq('user_id', user.id)
        .order('start_date', { ascending: false });

      if (error) throw error;

      setSupplements(data || []);
    } catch (error) {
      console.error('Failed to load supplements:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const mainContainer = mainContainerRef.current;
    const cardSection = cardSectionRef.current;
    if (!mainContainer || !cardSection) return;

    const handleVerticalScroll = () => {
      const rect = cardSection.getBoundingClientRect();
      const shouldBeSticky = rect.top <= 10;
      setIsSticky(shouldBeSticky);
    };

    handleVerticalScroll();
    mainContainer.addEventListener('scroll', handleVerticalScroll, { passive: true });
    return () => {
      mainContainer.removeEventListener('scroll', handleVerticalScroll);
    };
  }, [supplements]);

  useEffect(() => {
    if (loading) return;

    const container = scrollContainerRef.current;
    if (!container) {
      return;
    }

    const handleHorizontalScroll = () => {
      const containerRect = container.getBoundingClientRect();
      const containerCenter = containerRect.left + containerRect.width / 2;

      const cards = container.children;
      let closestIndex = 0;
      let minDistance = Infinity;

      for (let i = 0; i < cards.length; i++) {
        const card = cards[i] as HTMLElement;
        const cardRect = card.getBoundingClientRect();
        const cardCenter = cardRect.left + cardRect.width / 2;
        const distance = Math.abs(cardCenter - containerCenter);

        if (distance < minDistance) {
          minDistance = distance;
          closestIndex = i;
        }
      }

      setCurrentCardIndex(closestIndex);
    };

    handleHorizontalScroll();
    container.addEventListener('scroll', handleHorizontalScroll, { passive: true });
    return () => {
      container.removeEventListener('scroll', handleHorizontalScroll);
    };
  }, [supplements, loading]);

  const orderStatusPending = orderGateLoading && !hasOrder;
  const isDemoMode = !hasOrder && !orderGateLoading;

  const scrollToCard = useCallback((index: number) => {
    const container = scrollContainerRef.current;
    if (!container || index < 0 || index >= container.children.length) return;

    const targetCard = container.children[index] as HTMLElement;
    const containerRect = container.getBoundingClientRect();
    const cardRect = targetCard.getBoundingClientRect();

    const scrollLeft = container.scrollLeft + (cardRect.left - containerRect.left);

    container.scrollTo({
      left: scrollLeft,
      behavior: 'smooth'
    });

    setCurrentCardIndex(index);
  }, []);



  const activeSupplements = supplements.filter(s => s.status === 'active');
  const otherSupplements = supplements.filter(s => s.status !== 'active');
  const stageDerivedSupplements = useMemo<CustomSupplement[]>(() => {
    if (!hasOrder || !stageSummary?.has_plan || !stageSummary?.stages?.length) return [];
    const startDateRaw = stageSummary.start_date || toLocalDateString(new Date());
    const startDate = new Date(`${startDateRaw}T00:00:00+08:00`);
    const typeCycle = ['vitamin', 'mineral', 'herbal', 'protein'];

    const toLocalDateString = (date: Date) => {
      const y = date.getFullYear();
      const m = String(date.getMonth() + 1).padStart(2, '0');
      const d = String(date.getDate()).padStart(2, '0');
      return `${y}-${m}-${d}`;
    };

    const toDate = (offsetDay: number) => {
      const d = new Date(startDate);
      d.setDate(d.getDate() + Math.max(0, offsetDay));
      return toLocalDateString(d);
    };

    const rows: CustomSupplement[] = [];
    stageSummary.stages.forEach((stage) => {
      const stageItems = (stage.supplements && stage.supplements.length > 0)
        ? stage.supplements
        : (stage.supplement
          ? [{ supplement_id: stage.supplement.id, per_day_qty: stage.per_day_qty, supplement: stage.supplement }]
          : []);

      stageItems.forEach((item, idx) => {
        const stageStatus = stage.is_current
          ? 'active'
          : ((stageSummary.current_day || 1) > (stage.end_day || 0) ? 'completed' : 'pending');
        rows.push({
          id: `stage-${stage.index}-${item.supplement?.id || item.supplement_id || idx}`,
          supplement_name: item.supplement?.name || `补剂${stage.index}-${idx + 1}`,
          supplement_type: typeCycle[(stage.index - 1) % typeCycle.length],
          dosage: `${item.per_day_qty ?? stage.per_day_qty ?? 1}颗`,
          frequency: '每日一次',
          start_date: toDate((stage.start_day || 1) - 1),
          end_date: toDate((stage.end_day || stage.start_day || 1) - 1),
          status: stageStatus,
          instructions: `第${stage.index}阶段 · ${stage.stage_name}`,
          icon_path: '',
        });
      });
    });

    return rows;
  }, [hasOrder, stageSummary]);

  const allDisplaySupplements = useMemo(() => {
    if (hasOrder && stageDerivedSupplements.length > 0) return stageDerivedSupplements;
    return supplements.length > 0 ? [...activeSupplements, ...otherSupplements] : [];
  }, [hasOrder, stageDerivedSupplements, supplements.length, activeSupplements, otherSupplements]);

  // 有订单但数据暂未就绪时，回退展示说明卡，避免页面“全空白”
  const displayCards =
    ((!hasOrder && !orderGateLoading) || (hasOrder && !stageLoading && allDisplaySupplements.length === 0))
      ? INFORMATIONAL_CARDS
      : [];

  const initialSupplementCardIndex = useMemo(() => {
    if (!hasOrder || allDisplaySupplements.length === 0) return 0;

    const currentStageIndex = stageSummary?.current_stage?.index;
    if (currentStageIndex && currentStageIndex > 0) {
      const stagePrefix = `stage-${currentStageIndex}-`;
      const stageIdx = allDisplaySupplements.findIndex((s) => s.id.startsWith(stagePrefix));
      if (stageIdx >= 0) return stageIdx;
    }

    const today = toLocalDateString(new Date());
    const dateRangeIdx = allDisplaySupplements.findIndex((s) => {
      const start = s.start_date || '';
      const end = s.end_date || '9999-12-31';
      return start <= today && today <= end;
    });
    if (dateRangeIdx >= 0) return dateRangeIdx;

    const activeIdx = allDisplaySupplements.findIndex((s) => s.status === 'active');
    if (activeIdx >= 0) return activeIdx;

    return 0;
  }, [hasOrder, allDisplaySupplements, stageSummary?.current_stage?.index]);

  useEffect(() => {
    if (loading) return;

    const timer = window.setTimeout(() => {
      if (hasOrder && allDisplaySupplements.length > 0) {
        scrollToCard(initialSupplementCardIndex);
        return;
      }
      if (!hasOrder && displayCards.length > 0) {
        setCurrentCardIndex(0);
      }
    }, 80);

    return () => window.clearTimeout(timer);
  }, [loading, hasOrder, allDisplaySupplements.length, displayCards.length, initialSupplementCardIndex, scrollToCard]);

  const innerScroll = (
      <div ref={mainContainerRef} className="flex-1 overflow-y-auto scrollbar-hide pb-6 bg-gray-100 min-h-0 h-full">
        {loading ? (
          <LoadingState spinnerColor="text-purple-400" />
        ) : orderStatusPending ? (
          <div className="px-4 py-12 text-center">
            <p className="text-sm text-gray-600">正在确认您的服务与订单状态…</p>
            <p className="text-xs text-gray-400 mt-2">请稍候，避免误显示演示补剂卡片</p>
          </div>
        ) : (
        <>
        {isDemoMode && (
          <div className="px-4 mt-2">
            <div className="mb-4 rounded-xl bg-amber-50 border border-amber-200 px-4 py-3">
              <p className="text-sm text-amber-800 font-medium">以下为模拟数据，仅供参考</p>
              <p className="text-xs text-amber-700 mt-1">完成订单后即可查看您的专属补剂方案</p>
            </div>
          </div>
        )}

        {displayCards.length > 0 ? (
          <>
            {/* Informational Cards */}
            <div ref={cardSectionRef} className={`transition-all duration-200 ${isSticky ? 'sticky top-[10px] z-20 bg-gray-100 -mx-4 px-4 pb-4 shadow-sm' : ''}`}>
              <div className="relative">
                <div className="absolute inset-x-0 top-0 h-4 bg-gradient-to-b from-gray-200/50 to-transparent pointer-events-none z-10"></div>
                <div
                  ref={scrollContainerRef}
                  className="flex overflow-x-auto snap-x snap-mandatory scrollbar-hide pl-4 pr-0 my-4"
                  style={{ scrollSnapType: 'x mandatory' }}
                >
                  {displayCards.map((card) => (
                    <div key={card.id} className="flex-shrink-0 snap-center pr-4" style={{ width: 'calc(100% - 32px)' }}>
                    <div className="bg-white rounded-3xl overflow-hidden shadow-lg" style={{ minHeight: '520px', display: 'flex', flexDirection: 'column' }}>
                      {/* 1px spacing at top */}
                      <div className="h-px bg-gray-100"></div>
                      {/* Card Header with Gradient Background */}
                      <div className={`bg-gradient-to-br ${card.bgColor} pt-6 px-6 pb-8 relative`}>
                        {/* Badge */}
                        <div className="mb-4">
                          <span className="text-sm text-gray-700 font-medium">{card.badge}</span>
                        </div>

                        {/* Title */}
                        <h3 className="text-3xl font-bold text-gray-900 mb-3">{card.title}</h3>

                        {/* Benefits */}
                        <p className="text-sm text-gray-700 leading-relaxed mb-4">
                          {card.benefits}
                        </p>

                        {/* Pill Image */}
                        <div className="absolute top-6 right-6">
                          <img
                            src={card.pillImageUrl}
                            alt={card.title}
                            className="w-20 h-28 object-contain"
                          />
                        </div>
                      </div>

                      {/* Card Content - Reasons */}
                      <div className="px-6 py-6 space-y-6 flex-1">
                        {card.reasons.map((reason, idx) => (
                          <div key={idx}>
                            <h4 className="text-base font-semibold text-gray-900 mb-2">
                              {reason.title}
                            </h4>
                            <p className="text-sm text-gray-600 leading-relaxed">
                              {reason.description}
                            </p>
                          </div>
                        ))}

                        {/* Footer Link */}
                        <button className="flex items-center text-sm text-gray-500 hover:text-gray-700 transition-colors mt-8">
                          <span>了解补剂详情和参考文献</span>
                          <ChevronRight className="w-4 h-4 ml-1" />
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
              </div>

              {/* Pagination Dots */}
              {displayCards.length > 1 && (
                <div className="flex justify-center items-center gap-2 py-4">
                  {displayCards.map((_, index) => (
                    <button
                      key={index}
                      onClick={() => scrollToCard(index)}
                      className={`h-2 rounded-full transition-all ${
                        currentCardIndex === index
                          ? 'w-6 bg-gray-900'
                          : 'w-2 bg-gray-300'
                      }`}
                    />
                  ))}
                </div>
              )}
            </div>
          </>
        ) : (hasOrder && allDisplaySupplements.length > 0) ? (
          <>
            {/* Scrollable Supplement Cards */}
            <div ref={cardSectionRef} className={`transition-all duration-200 ${isSticky ? 'sticky top-[10px] z-20 bg-gray-100 -mx-4 px-4 pb-4 shadow-sm' : ''}`}>
              <div className="relative">
                <div className="absolute inset-x-0 top-0 h-4 bg-gradient-to-b from-gray-200/50 to-transparent pointer-events-none z-10"></div>
                <div
                  ref={scrollContainerRef}
                  className="flex overflow-x-auto snap-x snap-mandatory scrollbar-hide pl-4 pr-0 my-4"
                  style={{ scrollSnapType: 'x mandatory' }}
                >
                  {allDisplaySupplements.map((supplement) => {
                    const isActive = supplement.status === 'active';
                    const isStageBackfill = supplement.id.startsWith('stage-');
                    return (
                      <div key={supplement.id} className="flex-shrink-0 snap-center pr-4" style={{ width: 'calc(100% - 32px)' }}>
                      <div className="relative bg-white rounded-3xl overflow-hidden pb-6 shadow-lg border-2 border-gray-100">
                        {/* 1px spacing at top */}
                        <div className="h-px bg-gray-100"></div>
                        {/* Gradient Header */}
                        <div
                          className={`bg-gradient-to-br ${
                            isActive
                              ? supplementUtils.getSupplementGradient(supplement.supplement_type)
                              : (isStageBackfill ? 'from-slate-200 to-slate-300' : 'from-gray-200 to-gray-300')
                          } pt-8 px-6 pb-6 relative`}
                          style={{ minHeight: '280px' }}
                        >
                          {/* Decorative Circle */}
                          <div className="absolute top-6 right-6">
                            <div className="w-24 h-32 bg-white/30 rounded-full shadow-lg transform rotate-12"></div>
                          </div>

                          {/* Icon Display */}
                          <div className="absolute top-8 right-8">
                            <div className="w-20 h-20 bg-white rounded-2xl flex items-center justify-center shadow-md">
                              <img
                                src={supplement.icon_path}
                                alt={supplement.supplement_name}
                                className={`w-14 h-16 object-contain ${!isActive ? 'opacity-50' : ''}`}
                                onError={(e) => {
                                  e.currentTarget.style.display = 'none';
                                  const parent = e.currentTarget.parentElement;
                                  if (parent) {
                                    parent.innerHTML = `<div class="w-10 h-10 ${isActive ? 'text-gray-600' : 'text-gray-400'}"><svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="4" width="16" height="16" rx="2"></rect><line x1="9" y1="9" x2="15" y2="15"></line><line x1="15" y1="9" x2="9" y2="15"></line></svg></div>`;
                                  }
                                }}
                              />
                            </div>
                          </div>

                          {/* Supplement Info in Gradient Area */}
                          <div className="relative z-10">
                            <p className="text-sm text-gray-800 mb-3">{supplement.frequency}</p>
                            <h3 className="text-3xl font-bold text-gray-900 mb-4">{supplement.supplement_name}</h3>

                            <div className="flex items-center space-x-2 mb-4">
                              <span className={`text-xs px-2 py-1 rounded-full ${supplementUtils.getSupplementTypeColor(supplement.supplement_type)}`}>
                                {supplementUtils.getSupplementTypeLabel(supplement.supplement_type)}
                              </span>
                              <StatusBadge status={supplementUtils.getStatusBadgeType(supplement.status)} className="px-3 py-1.5 rounded-lg" />
                            </div>

                            <div className="space-y-2 text-gray-800">
                              <div className="flex items-center space-x-2 text-sm">
                                <Pill className="w-4 h-4" />
                                <span className="font-medium">用量：{supplement.dosage}</span>
                              </div>
                              <div className="flex items-center space-x-2 text-sm">
                                <Clock className="w-4 h-4" />
                                <span className="font-medium">频率：{supplement.frequency}</span>
                              </div>
                            </div>
                          </div>
                        </div>

                        {/* Divider */}
                        <div className="h-px bg-gray-200 mx-6"></div>

                        {/* Details Section */}
                        <div className="px-6 pt-6 pb-4">
                          <h4 className="text-lg font-semibold text-gray-900 mb-4">补剂详情</h4>

                          {supplement.instructions && !isStageBackfill && (
                            <div className="bg-blue-50 rounded-xl p-3 mb-4">
                              <div className="flex items-start space-x-2">
                                <AlertCircle className="w-4 h-4 text-blue-600 flex-shrink-0 mt-0.5" />
                                <p className="text-sm text-gray-700 leading-relaxed">{supplement.instructions}</p>
                              </div>
                            </div>
                          )}

                          <div className="space-y-3 mb-4">
                            <div className="flex items-center justify-between">
                              <div className="flex items-center space-x-2 text-sm text-gray-600">
                                <Calendar className="w-4 h-4" />
                                <span>开始时间</span>
                              </div>
                              <span className="text-sm font-medium text-gray-900">{formatDate(supplement.start_date)}</span>
                            </div>
                            {supplement.end_date && (
                              <div className="flex items-center justify-between">
                                <div className="flex items-center space-x-2 text-sm text-gray-600">
                                  <Calendar className="w-4 h-4" />
                                  <span>结束时间</span>
                                </div>
                                <span className="text-sm font-medium text-gray-900">{formatDate(supplement.end_date)}</span>
                              </div>
                            )}
                          </div>

                          {isActive && !isStageBackfill && (
                            <div className="flex space-x-3 mt-4">
                              <button className="flex-1 py-2.5 rounded-xl border-2 border-gray-900 text-gray-900 text-sm font-medium hover:bg-gray-50 transition-colors">
                                暂停使用
                              </button>
                              <button className="flex-1 py-2.5 rounded-xl bg-purple-300 text-purple-800 text-sm font-semibold hover:bg-purple-400 transition-colors">
                                续订
                              </button>
                            </div>
                          )}

                          <button className="text-sm text-gray-500 hover:text-gray-700 transition-colors flex items-center mt-4">
                            了解补剂详情和参考文献
                            <span className="ml-1">›</span>
                          </button>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
              </div>

              {/* Scroll Indicators */}
              {allDisplaySupplements.length > 1 && (
                <div className="flex justify-center items-center gap-2 py-4">
                  {allDisplaySupplements.map((_, index) => (
                    <button
                      key={index}
                      onClick={() => scrollToCard(index)}
                      className={`h-2 rounded-full transition-all ${
                        currentCardIndex === index
                          ? 'w-6 bg-gray-900'
                          : 'w-2 bg-gray-300'
                      }`}
                    />
                  ))}
                </div>
              )}
            </div>

          </>
        ) : hasOrder && stageLoading ? (
          <div className="px-4">
            <EmptyState
              icon={<span className="text-4xl">⏳</span>}
              title="正在同步补剂方案"
              description="请稍候，正在加载当前阶段补剂内容"
            />
          </div>
        ) : (
          <div className="px-4">
            <EmptyState 
              icon={<Pill className="w-10 h-10 text-gray-400" />}
              title={hasOrder ? '当前暂无可展示补剂' : '暂无定制补剂方案'}
              description={hasOrder ? '补剂方案正在初始化，请稍后重试' : '完成健康评估后将获得专属补剂推荐'}
            />
          </div>
        )}

        {/* Bottom spacing */}
        <div className="h-4"></div>
        </>
        )}
      </div>
  );

  return (
    <div className="flex flex-col flex-1 min-h-0 h-full bg-gray-100 overflow-hidden">
      {innerScroll}
    </div>
  );
};

export default CustomSupplementScreen;

import React, { useState, useEffect, useRef } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { UserPackage, MockPackageData, calculatePackageDates } from '../services/packageService';
import { DrawerScreen } from './common/DrawerScreen';
import { SecondaryPageHeader } from './common/SecondaryPageHeader';

interface DateSelectionPageProps {
  onClose: () => void;
  onNext: (selectedDates: Date[], excludedDates: Date[], selectedMealTypes: string[]) => void;
  packageData?: UserPackage | MockPackageData | null;
  initialSelectedDates?: Date[];
  initialExcludedDates?: Date[];
  initialSelectedMealTypes?: string[];
}

const DateSelectionPage: React.FC<DateSelectionPageProps> = ({
  onClose,
  onNext,
  packageData,
  initialSelectedDates,
  initialExcludedDates,
  initialSelectedMealTypes
}) => {
  const packageDuration = packageData?.package_duration || 7; // 测试演示用，正常情况下无订单无法配置
  const includedMeals = packageData?.included_meals || ['breakfast', 'lunch', 'dinner'];
  const normalizeToIncluded = (input?: string[] | null): string[] => {
    const source = Array.isArray(input) ? input : [];
    const includedSet = new Set(includedMeals.map((m) => String(m).toLowerCase()));
    const filtered = source
      .map((m) => String(m).toLowerCase())
      .filter((m) => includedSet.has(m));
    return filtered.length > 0 ? filtered : includedMeals;
  };

  const [selectedDates, setSelectedDates] = useState<Date[]>(initialSelectedDates || []);
  const [selectedMealTypes, setSelectedMealTypes] = useState<string[]>(
    normalizeToIncluded(initialSelectedMealTypes)
  );
  const [excludedDates, setExcludedDates] = useState<Date[]>(initialExcludedDates || []);
  const [lastClickTime, setLastClickTime] = useState<number>(0);
  const [lastClickedDate, setLastClickedDate] = useState<Date | null>(null);
  const [currentMonth, setCurrentMonth] = useState(new Date().getMonth());
  const [currentYear, setCurrentYear] = useState(new Date().getFullYear());
  const [calculatedDates, setCalculatedDates] = useState<{
    dates: Date[];
    currentMonthDays: number;
    nextMonthDays: number;
    nextMonthFullDays: number;
    actualStartDate: Date;
  } | null>(null);

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  useEffect(() => {
    const startDate = new Date();
    startDate.setHours(0, 0, 0, 0);
    const packageDatesData = calculatePackageDates(startDate, packageDuration);
    setCalculatedDates(packageDatesData);
  }, [packageDuration]);


  const generateAllAvailableDates = () => {
    if (!calculatedDates) return [];
    const dates: Date[] = [];
    const lastDayOfMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    for (let i = 1; i <= lastDayOfMonth; i++) {
      const date = new Date(currentYear, currentMonth, i);
      date.setHours(0, 0, 0, 0);
      dates.push(date);
    }
    return dates;
  };

  const handlePrevMonth = () => {
    const now = new Date();
    const currentMonthValue = now.getMonth();
    if (currentMonth === currentMonthValue) {
      return;
    }
    if (currentMonth === 0) {
      setCurrentMonth(11);
      setCurrentYear(currentYear - 1);
    } else {
      setCurrentMonth(currentMonth - 1);
    }
  };

  const handleNextMonth = () => {
    const now = new Date();
    const currentMonthValue = now.getMonth();
    const currentYearValue = now.getFullYear();
    let nextMonth = currentMonthValue + 1;
    let nextYear = currentYearValue;
    if (nextMonth > 11) {
      nextMonth = 0;
      nextYear += 1;
    }
    if (currentMonth === nextMonth && currentYear === nextYear) {
      return;
    }
    if (currentMonth === 11) {
      setCurrentMonth(0);
      setCurrentYear(currentYear + 1);
    } else {
      setCurrentMonth(currentMonth + 1);
    }
  };

  const groupDatesByMonth = (dates: Date[]) => {
    const groups: { month: number; year: number; dates: Date[]; allDates: Date[] }[] = [];
    dates.forEach(date => {
      const month = date.getMonth();
      const year = date.getFullYear();
      let group = groups.find(g => g.month === month && g.year === year);
      if (!group) {
        group = { month, year, dates: [], allDates: [] };
        groups.push(group);
      }
      group.dates.push(date);
    });
    groups.forEach((group) => {
      const firstDayOfMonth = new Date(group.year, group.month, 1);
      const lastDayOfMonth = new Date(group.year, group.month + 1, 0);
      const startDate = new Date(firstDayOfMonth);
      const dayOfWeek = startDate.getDay();
      startDate.setDate(startDate.getDate() - dayOfWeek);
      const allDates: Date[] = [];
      const currentDate = new Date(startDate);
      while (currentDate <= lastDayOfMonth || allDates.length % 7 !== 0) {
        allDates.push(new Date(currentDate));
        currentDate.setDate(currentDate.getDate() + 1);
      }
      group.allDates = allDates;
    });
    return groups;
  };

  const isDateInPackage = (date: Date) => {
    const isSelected = selectedDates.some(d => d.toDateString() === date.toDateString());
    const isExcluded = excludedDates.some(d => d.toDateString() === date.toDateString());
    return isSelected && !isExcluded;
  };

  const handleDateClick = (clickedDate: Date) => {
    const now = Date.now();
    const isDoubleClick =
      lastClickedDate &&
      lastClickedDate.toDateString() === clickedDate.toDateString() &&
      now - lastClickTime < 300;

    setLastClickTime(now);
    setLastClickedDate(clickedDate);

    // Handle double-click on selected date to exclude it
    if (isDoubleClick && isDateInPackage(clickedDate)) {
      if (excludedDates.length >= 3) {
        console.log('❌ 最多只能取消3天');
        return;
      }
      const newExcludedDates = [...excludedDates, clickedDate];
      setExcludedDates(newExcludedDates);
      if (selectedDates.length > 0) {
        const lastDate = selectedDates[selectedDates.length - 1];
        const nextDate = new Date(lastDate);
        nextDate.setDate(lastDate.getDate() + 1);
        setSelectedDates([...selectedDates, nextDate]);
      }
      console.log('✅ 取消日期:', clickedDate.toDateString());
      console.log('📅 已取消天数:', newExcludedDates.length);
      return;
    }

    // Single click: only set new start date if no dates selected, or if clicking on an unselected date
    if (selectedDates.length === 0 || !isDateInPackage(clickedDate)) {
      const newSelectedDates: Date[] = [];
      for (let i = 0; i < packageDuration; i++) {
        const date = new Date(clickedDate);
        date.setDate(clickedDate.getDate() + i);
        newSelectedDates.push(date);
      }
      setSelectedDates(newSelectedDates);
      setExcludedDates([]);
    }
  };

  const isDatePastOrToday = (date: Date) => {
    const compareDate = new Date(date);
    compareDate.setHours(0, 0, 0, 0);
    return compareDate < today;
  };

  const toggleMealType = (mealType: string) => {
    // 餐次严格跟随订单商品配置：不允许新增或取消。
    if (!includedMeals.includes(mealType)) return;
  };

  const isMealLocked = (mealType: string) => {
    return includedMeals.includes(mealType);
  };

  const isMealDisabled = (mealType: string) => {
    return !includedMeals.includes(mealType) || isMealLocked(mealType);
  };

  const isValid = () => {
    return selectedDates.length > 0 && selectedMealTypes.length > 0;
  };

  const handleNext = () => {
    if (isValid()) {
      onNext(selectedDates, excludedDates, selectedMealTypes);
    }
  };

  const allDates = generateAllAvailableDates();
  const dateGroups = groupDatesByMonth(allDates);

  return (
    <DrawerScreen show={true} onClose={onClose} showDragHandle={false}>
      <div className="flex flex-col h-full bg-white overflow-hidden">
        {/* Header */}
        <SecondaryPageHeader 
          title="选择开始日期" 
          onClose={onClose} 
        />

        <div className="flex-1 overflow-y-auto scrollbar-hide">
          <div className="ml-4 mr-4 mt-[5px] px-4 py-3 bg-white border border-gray-300 rounded-lg">
            <div className="flex items-center justify-between mb-2">
              <h3 className="text-base font-semibold text-gray-800">选择开始日期</h3>
              <div className="flex items-center">
                <button onClick={handlePrevMonth} className="p-1">
                  <ChevronLeft className="w-5 h-5 text-gray-600" />
                </button>
                <span className="text-sm font-medium text-gray-800 mx-2">
                  {currentYear}年{currentMonth + 1}月
                </span>
                <button onClick={handleNextMonth} className="p-1">
                  <ChevronRight className="w-5 h-5 text-gray-600" />
                </button>
              </div>
            </div>

            <div className="grid grid-cols-7 gap-0 mb-1">
              {['周日', '周一', '周二', '周三', '周四', '周五', '周六'].map((day) => (
                <div key={day} className="text-center text-xs text-gray-500 font-medium py-0.5">
                  {day}
                </div>
              ))}
            </div>

            {dateGroups.length > 0 && (
              <div className="grid grid-cols-7 gap-x-0 gap-y-0 mb-1.5">
                {dateGroups[0].allDates.map((date, index) => {
                  const isSelected = isDateInPackage(date);
                  const isExcluded = excludedDates.some(d => d.toDateString() === date.toDateString());
                  const isPastOrToday = isDatePastOrToday(date);
                  const isInCurrentMonth = date.getMonth() === dateGroups[0].month;
                  const isAvailableDate = dateGroups[0].dates.some(d => d.toDateString() === date.toDateString());

                  return (
                    <button
                      key={index}
                      disabled={isPastOrToday || !isAvailableDate}
                      onClick={() => !isPastOrToday && isAvailableDate && handleDateClick(date)}
                      className={`
                        aspect-square flex items-center justify-center text-sm font-medium relative py-0
                        ${isPastOrToday || !isAvailableDate
                          ? 'text-gray-300 cursor-not-allowed'
                          : isSelected
                            ? 'text-green-600 font-semibold'
                            : isExcluded
                              ? 'text-red-400 line-through'
                              : isInCurrentMonth
                                ? 'text-gray-800'
                                : 'text-gray-400'
                        }
                      `}
                    >
                      {isSelected && (
                        <div className="absolute inset-0 flex items-center justify-center">
                          <div className="w-6 h-6 rounded-full bg-green-100"></div>
                        </div>
                      )}
                      {isExcluded && (
                        <div className="absolute inset-0 flex items-center justify-center">
                          <div className="w-6 h-6 rounded-full bg-red-100"></div>
                        </div>
                      )}
                      <span className="relative z-10">{date.getDate()}</span>
                    </button>
                  );
                })}
              </div>
            )}

            <div className="border-t border-gray-300 my-2"></div>

            <div className="flex items-center justify-between text-sm">
              <div className="flex items-center space-x-6">
                <div>
                  <span className="text-gray-600">开始：</span>
                  <span className="text-gray-800 font-bold">
                    {selectedDates.length > 0 ? `${selectedDates[0].getMonth() + 1}月${selectedDates[0].getDate()}日` : ''}
                  </span>
                </div>
                <div>
                  <span className="text-gray-600">结束：</span>
                  <span className="text-gray-800 font-bold">
                    {selectedDates.length > 0 ? `${selectedDates[selectedDates.length - 1].getMonth() + 1}月${selectedDates[selectedDates.length - 1].getDate()}日` : ''}
                  </span>
                </div>
              </div>
              {selectedDates.length > 0 && (
                <button
                  onClick={() => {
                    setSelectedDates([]);
                    setExcludedDates([]);
                  }}
                  className="px-3 py-1 text-xs text-gray-600 border border-gray-300 rounded-md hover:bg-gray-50 transition-colors"
                >
                  重置
                </button>
              )}
            </div>
            {excludedDates.length > 0 && (
              <div className="mt-2 text-xs text-gray-500">
                已取消 {excludedDates.length} 天，剩余 {selectedDates.length - excludedDates.length} 天配送 {excludedDates.length < 3 && `(最多可取消${3 - excludedDates.length}天)`}
              </div>
            )}
            {selectedDates.length > 0 && excludedDates.length === 0 && (
              <div className="mt-2 text-xs text-gray-400">
                💡 双击已选日期可取消该天配送（最多3天）
              </div>
            )}
          </div>

          <div className="px-4 py-2 mt-1">
            <div className="grid grid-cols-3 gap-2">
              <button
                onClick={() => toggleMealType('breakfast')}
                disabled={isMealDisabled('breakfast')}
                className={`
                  relative py-3 rounded-lg text-sm font-medium transition-all border
                  ${selectedMealTypes.includes('breakfast')
                    ? isMealLocked('breakfast')
                      ? 'bg-green-50 border-green-400 text-gray-700 cursor-not-allowed'
                      : 'bg-white border-green-400 text-gray-800'
                    : 'bg-gray-100 border-gray-300 text-gray-500'
                  }
                `}
              >
                早餐
                {selectedMealTypes.includes('breakfast') && (
                  <div className="absolute top-1.5 right-1.5 w-5 h-5 bg-green-500 rounded-full flex items-center justify-center">
                    <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                    </svg>
                  </div>
                )}
              </button>

              <button
                onClick={() => toggleMealType('lunch')}
                disabled={isMealDisabled('lunch')}
                className={`
                  relative py-3 rounded-lg text-sm font-medium transition-all border
                  ${selectedMealTypes.includes('lunch')
                    ? isMealLocked('lunch')
                      ? 'bg-green-50 border-green-400 text-gray-700 cursor-not-allowed'
                      : 'bg-white border-green-400 text-gray-800'
                    : 'bg-gray-100 border-gray-300 text-gray-500'
                  }
                `}
              >
                午餐
                {selectedMealTypes.includes('lunch') && (
                  <div className="absolute top-1.5 right-1.5 w-5 h-5 bg-green-500 rounded-full flex items-center justify-center">
                    <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                    </svg>
                  </div>
                )}
              </button>

              <button
                onClick={() => toggleMealType('dinner')}
                disabled={isMealDisabled('dinner')}
                className={`
                  relative py-3 rounded-lg text-sm font-medium transition-all border
                  ${selectedMealTypes.includes('dinner')
                    ? isMealLocked('dinner')
                      ? 'bg-green-50 border-green-400 text-gray-700 cursor-not-allowed'
                      : 'bg-white border-green-400 text-gray-800'
                    : 'bg-gray-100 border-gray-300 text-gray-500'
                  }
                `}
              >
                晚餐
                {selectedMealTypes.includes('dinner') && (
                  <div className="absolute top-1.5 right-1.5 w-5 h-5 bg-green-500 rounded-full flex items-center justify-center">
                    <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                    </svg>
                  </div>
                )}
              </button>
            </div>
          </div>

          <div className="h-24"></div>
        </div>

        {/* Footer */}
        <div className="border-t border-gray-100 bg-white px-4 py-3">
          <button
            onClick={handleNext}
            disabled={!isValid()}
            className={`
              w-full py-3 rounded-xl font-medium text-base transition-all
              ${isValid()
                ? 'bg-gradient-to-r from-green-400 to-emerald-500 text-white hover:from-green-500 hover:to-emerald-600'
                : 'bg-gray-200 text-gray-400 cursor-not-allowed'
              }
            `}
          >
            确定
          </button>
        </div>
      </div>
    </DrawerScreen>
  );
};

