    loadStatistics();
    loadHRVData();
  }, [selectedPeriod, currentDate, userId]);

  const loadStatistics = async () => {
    try {
      const stats = await emotionService.getOrCreateStatistics(userId, selectedPeriod, currentDate);
      setStatistics(stats);
    } catch (error) {
