import React, { useState, useMemo, useCallback } from 'react';
import { BarChart3 } from 'lucide-react';
import { formatWeekLabel } from '../utils/dateUtils';
import { PeriodSelector } from './common/PeriodSelector'
import { DateNavigator } from './common/DateNavigator'
import { DragPanel } from './common/DragPanel'
import { DetailHeader } from './common/DetailHeader'
import { SectionCard } from './common/SectionCard'
import { useMeasurementsRecordsQuery, type MeasurementRecord } from '../hooks/useMeasurementsRecordsQuery'
import { ConfirmModal } from './common/ConfirmModal'
import { AlertDialog } from './common/AlertDialog'
import { useAlert } from '../hooks/useAlert'

interface MeasurementsDetailScreenProps {
  onClose: () => void;
  selectedDate: Date;
}

type MeasurementForm = {
  chest: string;
  waist: string;
  upperArm: string;
  hips: string;
  thigh: string;
  calf: string;
};

const FIELD_DEFS: { key: keyof MeasurementForm; label: string; emoji: string }[] = [
  { key: 'chest', label: '胸围', emoji: '👕' },
  { key: 'waist', label: '腰围', emoji: '👖' },
  { key: 'upperArm', label: '上臂围', emoji: '💪' },
  { key: 'hips', label: '臀围', emoji: '🍑' },
  { key: 'thigh', label: '大腿围', emoji: '🦵' },
  { key: 'calf', label: '小腿围', emoji: '🦵' },
];

const emptyForm = (): MeasurementForm => ({
  chest: '',
  waist: '',
  upperArm: '',
  hips: '',
  thigh: '',
  calf: '',
});

const MeasurementsDetailScreen: React.FC<MeasurementsDetailScreenProps> = ({ onClose, selectedDate: initialDate }) => {
  const [selectedDate, setSelectedDate] = useState(initialDate);
  const [selectedPeriod, setSelectedPeriod] = useState<'天' | '周' | '月' | '年'>('天');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingRecord, setEditingRecord] = useState<MeasurementRecord | null>(null);
  const [form, setForm] = useState<MeasurementForm>(emptyForm);
  const [deleteConfirmRecord, setDeleteConfirmRecord] = useState<MeasurementRecord | null>(null);
  const [deletingRecordId, setDeletingRecordId] = useState<string | null>(null);
  const { alertState, showError, hideAlert } = useAlert();

  // 计算本周的日期范围（用于记录部分，固定显示本周）
  const currentWeekRange = useMemo(() => {
    const weekStart = new Date(selectedDate);
    const dayOfWeek = weekStart.getDay();
    const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek; // 周一为开始
    weekStart.setDate(weekStart.getDate() + diff);
    weekStart.setHours(0, 0, 0, 0);

    const weekEnd = new Date(weekStart);
    weekEnd.setDate(weekStart.getDate() + 6);
    weekEnd.setHours(23, 59, 59, 999);

    return { start: weekStart, end: weekEnd };
  }, [selectedDate]);

  const {
    records: allMeasurementRecords,
    addRecord,
    updateRecord,
    deleteRecord,
    refresh,
    isAdding,
    isUpdating,
  } = useMeasurementsRecordsQuery(currentWeekRange.start, currentWeekRange.end);

  // 获取本周的记录（固定显示，不受周期切换影响）
  const measurementRecords = useMemo(() => {
    return allMeasurementRecords || [];
  }, [allMeasurementRecords]);

  // 从记录中提取测量数据
  const measurementData = useMemo(() => {
    if (measurementRecords && measurementRecords.length > 0) {
      const latestRecord = measurementRecords[0];
      const measurementDataFromDB = latestRecord.measurement_data || {};
      return {
        chest: measurementDataFromDB.chest || null,
        waist: measurementDataFromDB.waist || null,
        upperArm: measurementDataFromDB.upperArm || null,
        hips: measurementDataFromDB.hips || null,
        thigh: measurementDataFromDB.thigh || null,
        calf: measurementDataFromDB.calf || null
      };
    }
    return {
      chest: null,
      waist: null,
      upperArm: null,
      hips: null,
      thigh: null,
      calf: null
    };
  }, [measurementRecords]);

  const formatDate = (date: Date) => {
    try {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');

      switch (selectedPeriod) {
        case '天':
          return `${year}-${month}-${day}`;
        case '周':
          return formatWeekLabel(date);
        case '月':
          return `${year}年${month}月`;
        case '年':
          return `${year}年`;
        default:
          return `${year}-${month}-${day}`;
      }
    } catch (error) {
      console.error('Error formatting date:', error);
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    }
  };

  // 围度数据 - 从数据库加载的实际值
  const measurements = [
    { name: '胸围', icon: '👕', color: 'text-teal-500', value: measurementData.chest },
    { name: '腰围', icon: '👖', color: 'text-blue-500', value: measurementData.waist },
    { name: '上臂围', icon: '💪', color: 'text-pink-500', value: measurementData.upperArm },
    { name: '臀围', icon: '🍑', color: 'text-purple-500', value: measurementData.hips },
    { name: '大腿围', icon: '🦵', color: 'text-red-500', value: measurementData.thigh },
    { name: '小腿围', icon: '🦵', color: 'text-orange-500', value: measurementData.calf },
  ];

  const navigateDate = (direction: 'prev' | 'next') => {
    const newDate = new Date(selectedDate);

    switch (selectedPeriod) {
      case '天':
        newDate.setDate(newDate.getDate() + (direction === 'next' ? 1 : -1));
        break;
      case '周':
        newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
        break;
      case '月':
        newDate.setMonth(newDate.getMonth() + (direction === 'next' ? 1 : -1));
        break;
      case '年':
        newDate.setFullYear(newDate.getFullYear() + (direction === 'next' ? 1 : -1));
        break;
    }

    setSelectedDate(newDate);
  };

  const openAddModal = useCallback(() => {
    setEditingRecord(null);
    setForm(emptyForm());
    setIsModalOpen(true);
  }, []);

  const openEditModal = useCallback((record: MeasurementRecord) => {
    const d = record.measurement_data || {};
    setEditingRecord(record);
    setForm({
      chest: d.chest != null ? String(d.chest) : '',
      waist: d.waist != null ? String(d.waist) : '',
      upperArm: d.upperArm != null ? String(d.upperArm) : '',
      hips: d.hips != null ? String(d.hips) : '',
      thigh: d.thigh != null ? String(d.thigh) : '',
      calf: d.calf != null ? String(d.calf) : '',
    });
    setIsModalOpen(true);
  }, []);

  const closeModal = useCallback(() => {
    setIsModalOpen(false);
    setEditingRecord(null);
    setForm(emptyForm());
  }, []);

  const parseOptionalCm = (s: string): number | null => {
    const t = s.trim();
    if (t === '') return null;
    const n = parseFloat(t);
    if (Number.isNaN(n) || n <= 0 || n > 300) return null;
    return n;
  };

  const handleSaveMeasurements = async () => {
    const body = {
      chest: parseOptionalCm(form.chest),
      waist: parseOptionalCm(form.waist),
      upperArm: parseOptionalCm(form.upperArm),
      hips: parseOptionalCm(form.hips),
      thigh: parseOptionalCm(form.thigh),
      calf: parseOptionalCm(form.calf),
    };
    const hasAny =
      body.chest != null ||
      body.waist != null ||
      body.upperArm != null ||
      body.hips != null ||
      body.thigh != null ||
      body.calf != null;
    if (!hasAny) {
      showError('请至少填写一项', '围度请填写至少一个有效数值（厘米，1–300）');
      return;
    }

    setIsModalOpen(false);
    const savedForm = { ...form };
    const savedEditing = editingRecord;
    setForm(emptyForm());
    setEditingRecord(null);

    try {
      const recordDate = new Date(selectedDate);
      const now = new Date();
      recordDate.setHours(now.getHours(), now.getMinutes(), now.getSeconds(), now.getMilliseconds());

      if (savedEditing) {
        await updateRecord({
          id: savedEditing.id,
          body,
          date: recordDate,
          notes: savedEditing.notes,
        });
      } else {
        await addRecord({ body, date: recordDate });
      }
      await refresh();
    } catch (e) {
      console.error('[Measurements] save failed', e);
      setForm(savedForm);
      setEditingRecord(savedEditing);
      setIsModalOpen(true);
      showError('保存失败', e instanceof Error ? e.message : '请稍后重试');
    }
  };

  const confirmDelete = async () => {
    if (!deleteConfirmRecord) return;
    setDeletingRecordId(deleteConfirmRecord.id);
    const id = deleteConfirmRecord.id;
    setDeleteConfirmRecord(null);
    try {
      await deleteRecord(id);
      await refresh();
    } catch (e) {
      console.error('[Measurements] delete failed', e);
      showError('删除失败', '请稍后重试');
    } finally {
      setDeletingRecordId(null);
    }
  };

  return (
    <>
    <DragPanel show={true} onClose={onClose} zIndex={60} mask={{ visible: false }}
      header={
        <>
          <DetailHeader 
            title="围度记录" 
            leftAction={{ label: '返回', onClick: onClose }} 
            rightAction={{ label: '+', onClick: openAddModal }}
          />
          {/* Period Selector */}
          <div className="bg-gray-50 px-4 pt-2 pb-1">
            <PeriodSelector
              options={['天','周','月','年'].map(l => ({ label: l, value: l }))}
              value={selectedPeriod}
              onChange={(v) => setSelectedPeriod(v as '天'|'周'|'月'|'年')}
            />
          </div>
        </>
      }>

      <div className="px-4 space-y-1 flex-1 overflow-y-auto pb-4 scrollbar-hide">
        {/* Charts Section - Only show for non-day periods */}
        {selectedPeriod !== '天' && (
          <SectionCard className="my-1 px-3 py-6">
            <h3 className="text-lg font-bold text-gray-800 mb-2 text-center">围度统计</h3>
            <p className="text-sm text-gray-500 text-center leading-relaxed">
              多周期趋势图将按真实记录汇总展示，当前版本请在「天」视图查看明细；下方「记录」为本周数据。
            </p>
            <div className="flex items-center justify-center pt-4">
              <DateNavigator
                label={formatDate(selectedDate)}
                onPrev={() => navigateDate('prev')}
                onNext={() => navigateDate('next')}
              />
            </div>
          </SectionCard>
        )}

        {/* Measurements Grid - Always show */}
        <SectionCard className="my-1">
          <div className="grid grid-cols-3 gap-6">
            {measurements.map((measurement, index) => (
              <div key={index} className="text-center">
                <div className="text-2xl mb-2">{measurement.icon}</div>
                <div className={`text-sm font-medium mb-1 ${measurement.color}`}>
                  {measurement.name}
                </div>
                <div className={`text-lg font-bold ${measurement.value !== null && measurement.value !== undefined ? 'text-gray-800' : 'text-gray-400'}`}>
                  {measurement.value !== null && measurement.value !== undefined ? measurement.value : '--'}
                </div>
              </div>
            ))}
          </div>
        </SectionCard>

        {/* Records Section - Always show current week records */}
        <SectionCard className="my-1">
            <div className="flex items-center space-x-2 mb-6">
              <BarChart3 className="w-5 h-5 text-gray-400" />
              <span className="text-lg font-medium text-gray-700">记录</span>
            </div>

            {measurementRecords.length === 0 ? (
              <div className="text-center py-8">
                <div className="text-gray-400 text-sm">
                  暂无记录，请点击右上「+」添加
                </div>
              </div>
            ) : (
              <div className="space-y-1">
                {measurementRecords.map((record: any) => {
                  const recordData = record.measurement_data || {};
                  const recordTime = new Date(record.recorded_at);

                  // 🔥 修复：如果是昨天的记录，显示日期+时间；如果是今天的记录，只显示时间
                  const today = new Date();
                  today.setHours(0, 0, 0, 0);
                  const recordDate = new Date(recordTime);
                  recordDate.setHours(0, 0, 0, 0);

                  const isToday = recordDate.getTime() === today.getTime();
                  const isYesterday = recordDate.getTime() === today.getTime() - 24 * 60 * 60 * 1000;

                  let timeDisplay = '';
                  if (isToday) {
                    timeDisplay = recordTime.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
                  } else if (isYesterday) {
                    timeDisplay = `昨天 ${recordTime.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}`;
                  } else {
                    // 更早的日期，显示完整日期+时间
                    timeDisplay = recordTime.toLocaleString('zh-CN', { 
                      month: '2-digit', 
                      day: '2-digit', 
                      hour: '2-digit', 
                      minute: '2-digit' 
                    });
                  }

                  return (
                    <div key={record.id} className="bg-gray-50 rounded-xl p-4">
                      <div className="mb-3">
                          <div className="text-xs text-gray-400 mb-2">
                            {timeDisplay}
                          </div>
                          <div className="grid grid-cols-2 gap-3">
                            {recordData.chest !== null && recordData.chest !== undefined && (
                              <div className="flex items-center space-x-2">
                                <span className="text-lg">👕</span>
                                <div>
                                  <div className="text-xs text-teal-500">胸围</div>
                                  <div className="text-sm font-bold text-gray-800">{recordData.chest}</div>
                                </div>
                              </div>
                            )}
                            {recordData.waist !== null && recordData.waist !== undefined && (
                              <div className="flex items-center space-x-2">
                                <span className="text-lg">👖</span>
                                <div>
                                  <div className="text-xs text-blue-500">腰围</div>
                                  <div className="text-sm font-bold text-gray-800">{recordData.waist}</div>
                                </div>
                              </div>
                            )}
                            {recordData.upperArm !== null && recordData.upperArm !== undefined && (
                              <div className="flex items-center space-x-2">
                                <span className="text-lg">💪</span>
                                <div>
                                  <div className="text-xs text-pink-500">上臂围</div>
                                  <div className="text-sm font-bold text-gray-800">{recordData.upperArm}</div>
                                </div>
                              </div>
                            )}
                            {recordData.hips !== null && recordData.hips !== undefined && (
                              <div className="flex items-center space-x-2">
                                <span className="text-lg">🍑</span>
                                <div>
                                  <div className="text-xs text-purple-500">臀围</div>
                                  <div className="text-sm font-bold text-gray-800">{recordData.hips}</div>
                                </div>
                              </div>
                            )}
                            {recordData.thigh !== null && recordData.thigh !== undefined && (
                              <div className="flex items-center space-x-2">
                                <span className="text-lg">🦵</span>
                                <div>
                                  <div className="text-xs text-red-500">大腿围</div>
                                  <div className="text-sm font-bold text-gray-800">{recordData.thigh}</div>
                                </div>
                              </div>
                            )}
                            {recordData.calf !== null && recordData.calf !== undefined && (
                              <div className="flex items-center space-x-2">
                                <span className="text-lg">🦵</span>
                                <div>
                                  <div className="text-xs text-orange-500">小腿围</div>
                                  <div className="text-sm font-bold text-gray-800">{recordData.calf}</div>
                                </div>
                              </div>
                            )}
                          </div>
                      </div>
                      <div className="flex gap-2 justify-end">
                          <button
                            type="button"
                            className="text-sm px-3 py-1.5 rounded-lg bg-gray-200 text-gray-800"
                            onClick={() => openEditModal(record)}
                          >
                            编辑
                          </button>
                          <button
                            type="button"
                            disabled={deletingRecordId === record.id}
                            className="text-sm px-3 py-1.5 rounded-lg bg-red-50 text-red-600 disabled:opacity-50"
                            onClick={() => setDeleteConfirmRecord(record)}
                          >
                            删除
                          </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </SectionCard>

        {/* Bottom spacing */}
        <div className="h-2"></div>
      </div>
    </DragPanel>

      <DragPanel
        show={isModalOpen}
        onClose={closeModal}
        zIndex={70}
        mask={{ visible: true, clickable: true }}
        maxHeight="85vh"
        maxWidth="max-w-xs"
        header={
          <div className="px-4 py-2 text-center text-sm text-gray-600">
            {editingRecord ? '编辑围度' : '添加围度'}
          </div>
        }
      >
        <div className="px-4 pb-4 space-y-3">
          <p className="text-xs text-gray-500">至少填写一项，单位：厘米（1–300）</p>
          <div className="grid grid-cols-2 gap-3">
            {FIELD_DEFS.map(({ key, label, emoji }) => (
              <label key={key} className="flex flex-col gap-1">
                <span className="text-xs text-gray-600">
                  {emoji} {label}
                </span>
                <input
                  type="number"
                  inputMode="decimal"
                  min={1}
                  max={300}
                  step={0.1}
                  className="border border-gray-200 rounded-lg px-2 py-2 text-sm"
                  value={form[key]}
                  onChange={(e) => setForm((f) => ({ ...f, [key]: e.target.value }))}
                  placeholder="—"
                />
              </label>
            ))}
          </div>
          <div className="flex gap-3 pt-2">
            <button
              type="button"
              onClick={closeModal}
              className="flex-1 py-2.5 bg-gray-100 text-gray-700 rounded-xl text-sm font-medium"
            >
              取消
            </button>
            <button
              type="button"
              disabled={isAdding || isUpdating}
              onClick={handleSaveMeasurements}
              className="flex-1 py-2.5 bg-teal-500 text-white rounded-xl text-sm font-medium disabled:opacity-50"
            >
              {editingRecord ? '保存' : '添加'}
            </button>
          </div>
        </div>
      </DragPanel>

      <ConfirmModal
        show={!!deleteConfirmRecord}
        title="删除围度记录"
        message={deleteConfirmRecord ? new Date(deleteConfirmRecord.recorded_at).toLocaleString('zh-CN') : ''}
        onCancel={() => setDeleteConfirmRecord(null)}
        onConfirm={confirmDelete}
      />

      <AlertDialog
        show={alertState.show}
        type={alertState.type}
        title={alertState.title}
        message={alertState.message}
        onClose={hideAlert}
      />
    </>
  );
};

export default MeasurementsDetailScreen;

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../config/supabase';
import { OnboardingProvider } from '../contexts/OnboardingContext';
import HealthReportPage from './onboarding/HealthReportPage';
import NutritionSolutionPage from './onboarding/NutritionSolutionPage';
import MyHealthProfileScreen from './MyHealthProfileScreen';
import { DrawerScreen } from './common/DrawerScreen';
import { LoadingState } from './common/LoadingState';
import { EmptyState } from './common/EmptyState';
import { ConfirmModal } from './common/ConfirmModal';
import { AlertDialog } from './common/AlertDialog';
import { SecondaryPageHeader } from './common/SecondaryPageHeader';
import { formatDateTime } from '../utils/dateFormatters';
import { useAllHealthAssessmentsQuery } from '../hooks/useHealthAssessmentQuery';
import { useUserProfile } from '../contexts/UserProfileContext';

interface HealthAssessment {
  id: string;
  assessment_date: string;
  overall_score: number;
  diet_score: number;
  fitness_score: number;
  rest_score: number;
  psychology_score: number;
  exercise_score: number;
  primary_improvement_area: string;
  questionnaire_data?: {
    currentWeight?: number;
    targetWeight?: number;
    fitnessGoal?: string;
    [key: string]: any;
  };
}

interface UserProfileData {
  current_weight?: number;
  target_weight?: number;
  fitness_goal?: string;
}

interface MyReportsScreenProps {
  onClose: () => void;
  onOpenReassessment: (resetProgress?: boolean) => void;
  onOpenHealthProfile: () => void;
  onGoToMealPlan?: () => void;
}

const MyReportsScreen: React.FC<MyReportsScreenProps> = ({ onClose, onOpenReassessment, onOpenHealthProfile, onGoToMealPlan }) => {
  // ✅ user 不再需要，profile数据从UserProfileContext获取
  // ✅ 使用 UserProfileContext 获取用户档案数据，而不是直接查询数据库
  const { profile } = useUserProfile();
  void onOpenHealthProfile;
  void onGoToMealPlan;
  // 使用 React Query hook 管理健康评估列表
  const { assessments: assessmentsData, isLoading: assessmentsLoading, refresh: refreshAssessments } = useAllHealthAssessmentsQuery();
  const [assessments, setAssessments] = useState<HealthAssessment[]>([]);
  // ✅ profileData 现在从 UserProfileContext 的 profile 获取，无需本地状态
  const profileData: UserProfileData | null = profile ? {
    current_weight: profile.current_weight,
    target_weight: profile.target_weight,
    fitness_goal: profile.fitness_goal,
  } : null;
  const [loading, setLoading] = useState(true);
  const [showHealthReport, setShowHealthReport] = useState(false);
  const [selectedAssessmentId, setSelectedAssessmentId] = useState<string | null>(null);
  const [showNutritionSolution, setShowNutritionSolution] = useState(false);
  const [showReportArchive, setShowReportArchive] = useState(false);
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);
  const [swipedAssessmentId, setSwipedAssessmentId] = useState<string | null>(null);
  const [showAlert, setShowAlert] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');
  const touchStartX = useRef<{ [key: string]: number }>({});
  const touchStartY = useRef<{ [key: string]: number }>({});

  // 当 React Query 数据更新时，同步到本地状态
  useEffect(() => {
    if (assessmentsData) {
      setAssessments(assessmentsData as HealthAssessment[]);
    }
  }, [assessmentsData]);

  // 当加载状态变化时，更新本地loading状态
  useEffect(() => {
    setLoading(assessmentsLoading);
  }, [assessmentsLoading]);

  useEffect(() => {
    // ✅ profile数据现在由UserProfileContext自动管理，无需手动加载
    console.log('📊 [MyReportsScreen] Component mounted');

    // 用户状态变化已通过 React Query 和 Context 自动处理，无需监听事件

    // Listen for page visibility changes to refresh when user returns
    const handleVisibilityChange = () => {
      if (!document.hidden) {
        console.log('👁️ [MyReportsScreen] Page visible, refreshing data');
        // React Query 会自动处理缓存刷新
        refreshAssessments();
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      console.log('🧹 [MyReportsScreen] Component unmounting, cleaning up listeners');
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [refreshAssessments]);

  // ✅ loadProfileData 已被 useUserProfile Hook 替代
  // 从 UserProfileContext 获取数据，无需直接查询数据库


  const isLatestAssessment = (assessmentId: string) => {
    return assessments.length > 0 && assessments[0].id === assessmentId;
  };

  const getGoalText = () => {
    const goal = profileData?.fitness_goal;
    const goals: Record<string, string> = {
      'weight_loss': '减轻体重',
      'maintain_health': '焕肤',
      'tone': '保持健康',
      'confidence': '保持自信',
      'other': '其它'
    };
    return goals[goal || ''] || '未设置';
  };

  const getGoalTextFromGoal = (goal: string) => {
    const goals: Record<string, string> = {
      'weight_loss': '减轻体重',
      'maintain_health': '焕肤',
      'tone': '保持健康',
      'confidence': '保持自信',
      'other': '其它'
    };
    return goals[goal || ''] || '未设置';
  };

  const handleCardClick = (assessmentId: string) => {
    // 如果卡片处于滑动状态,点击后恢复原位
    if (swipedAssessmentId === assessmentId) {
      const cardElement = document.getElementById(`assessment-card-${assessmentId}`);
      if (cardElement) {
        cardElement.style.transform = 'translateX(0)';
        cardElement.style.transition = 'transform 0.3s ease';
      }
      setSwipedAssessmentId(null);
    } else {
      // 在「我的报告」内部打开二级弹窗，底层保持报告列表
      setShowReportArchive(true);
    }
  };

  const handleViewClick = (e: React.MouseEvent, assessmentId: string) => {
    e.stopPropagation();
    setSelectedAssessmentId(assessmentId);
    setShowHealthReport(true);
  };

  const handleTouchStart = (assessmentId: string, e: React.TouchEvent) => {
    // 最新评测记录不允许滑动删除
    if (isLatestAssessment(assessmentId)) return;

    touchStartX.current[assessmentId] = e.touches[0].clientX;
    touchStartY.current[assessmentId] = e.touches[0].clientY;
  };

  const handleTouchMove = (assessmentId: string, e: React.TouchEvent) => {
    if (!touchStartX.current[assessmentId]) return;

    const currentX = e.touches[0].clientX;
    const currentY = e.touches[0].clientY;
    const diffX = touchStartX.current[assessmentId] - currentX;
    const diffY = Math.abs(touchStartY.current[assessmentId] - currentY);

    if (Math.abs(diffX) > diffY) {
      e.preventDefault();
      const cardElement = document.getElementById(`assessment-card-${assessmentId}`);
      if (cardElement) {
        if (diffX > 0) {
          const newOffset = Math.min(80, Math.max(0, diffX));
          cardElement.style.transform = `translateX(-${newOffset}px)`;
        } else {
          const currentTransform = cardElement.style.transform;
          const match = currentTransform.match(/translateX\((-?\d+)px\)/);
          const currentOffset = match ? Math.abs(parseInt(match[1])) : 0;
          if (currentOffset > 0) {
            const newOffset = Math.max(0, currentOffset + diffX);
            cardElement.style.transform = `translateX(-${newOffset}px)`;
          }
        }
        cardElement.style.transition = 'none';
      }
    }
  };

  const handleTouchEnd = (assessmentId: string) => {
    if (!touchStartX.current[assessmentId]) return;

    const cardElement = document.getElementById(`assessment-card-${assessmentId}`);
    if (cardElement) {
      const transform = cardElement.style.transform;
      const match = transform.match(/translateX\((-?\d+)px\)/);
      const offset = match ? parseInt(match[1]) : 0;

      if (offset < -40) {
        cardElement.style.transform = 'translateX(-80px)';
        cardElement.style.transition = 'transform 0.3s ease';
        setSwipedAssessmentId(assessmentId);
      } else {
        cardElement.style.transform = 'translateX(0)';
        cardElement.style.transition = 'transform 0.3s ease';
        if (swipedAssessmentId === assessmentId) {
          setSwipedAssessmentId(null);
        }
      }
    }

    delete touchStartX.current[assessmentId];
    delete touchStartY.current[assessmentId];
  };

  const handleDeleteClick = (assessmentId: string) => {
    if (isLatestAssessment(assessmentId)) {
      setAlertMessage('当前评测报告正在使用中，无法删除');
      setShowAlert(true);
      const cardElement = document.getElementById(`assessment-card-${assessmentId}`);
      if (cardElement) {
        cardElement.style.transform = 'translateX(0)';
        cardElement.style.transition = 'transform 0.3s ease';
      }
      setSwipedAssessmentId(null);
      return;
    }
    setDeleteConfirmId(assessmentId);
  };

  const handleConfirmDelete = async () => {
    if (!deleteConfirmId) return;

    try {
      const { error } = await supabase
        .from('health_assessments')
        .delete()
        .eq('id', deleteConfirmId);

      if (error) throw error;

      // 恢复卡片到原位后再删除
      if (swipedAssessmentId) {
        const cardElement = document.getElementById(`assessment-card-${swipedAssessmentId}`);
        if (cardElement) {
          cardElement.style.transform = 'translateX(0)';
          cardElement.style.transition = 'transform 0.3s ease';
        }
      }

      // 🔥 修复：先更新本地状态，然后刷新 React Query 缓存
      setAssessments(assessments.filter(a => a.id !== deleteConfirmId));
      setSwipedAssessmentId(null);
      setDeleteConfirmId(null);

      // 🔥 修复：刷新 React Query 缓存，确保删除后数据同步
      refreshAssessments();
    } catch (error) {
      console.error('Failed to delete assessment:', error);
      if (swipedAssessmentId) {
        const cardElement = document.getElementById(`assessment-card-${swipedAssessmentId}`);
        if (cardElement) {
          cardElement.style.transform = 'translateX(0)';
          cardElement.style.transition = 'transform 0.3s ease';
        }
        setSwipedAssessmentId(null);
      }
      setDeleteConfirmId(null);
    }
  };

  const handleCancelDelete = () => {
    if (swipedAssessmentId) {
      const cardElement = document.getElementById(`assessment-card-${swipedAssessmentId}`);
      if (cardElement) {
        cardElement.style.transform = 'translateX(0)';
        cardElement.style.transition = 'transform 0.3s ease';
      }
      setSwipedAssessmentId(null);
    }
    setDeleteConfirmId(null);
  };

  /**
   * 报告/营养方案必须叠在 DrawerScreen **内部**，保持与列表相同的 fixed z-[80] 白底宿主；
   * 若 early return 卸掉 Drawer，在部分 WebView 堆叠下会露出底下 AppRouter（多为「我的」），误像「跳回个人中心」。
   */
  const stackOverlayClass = 'absolute inset-0 z-[35] flex flex-col bg-white min-h-0';

  return (
    <DrawerScreen show={true} onClose={onClose} showDragHandle={false} showMask={false}>
      <div className="flex flex-col h-full min-h-0 bg-gray-50 relative">
        {showNutritionSolution ? (
          <div className={stackOverlayClass}>
            <OnboardingProvider>
              <NutritionSolutionPage
                onComplete={() => {
                  setShowNutritionSolution(false);
                }}
                readOnly={true}
              />
            </OnboardingProvider>
          </div>
        ) : showHealthReport && selectedAssessmentId ? (
          <div className={stackOverlayClass}>
            <HealthReportPage
              onComplete={() => {
                setShowHealthReport(false);
                setSelectedAssessmentId(null);
              }}
              onOpenNutritionSolution={() => {
                setShowHealthReport(false);
                setShowNutritionSolution(true);
              }}
              assessmentId={selectedAssessmentId}
            />
          </div>
        ) : (
          <>
        <SecondaryPageHeader title="我的报告" onClose={onClose} />

        <div className="flex-1 min-h-0 overflow-y-auto px-4 py-3">
        {loading ? (
          <LoadingState />
        ) : (
        <>
        <div className="bg-white rounded-2xl p-4 mb-4">
          <div className="flex items-center justify-between">
            <div className="flex items-start space-x-3 flex-1">
              <div className="w-10 h-10 bg-yellow-100 rounded-full flex items-center justify-center flex-shrink-0">
                <span className="text-xl">💡</span>
              </div>
              <div className="flex-1">
                <p className="text-xs text-gray-600 leading-relaxed">
                  由于个人的身体状况、生活习惯可能会发生变化，建议每3个月重新进行一次评估。重新评测将生成一条新的健康报告，历史报告将被保留
                </p>
              </div>
            </div>
            <button
              onClick={() => onOpenReassessment(true)}
              className="ml-3 px-4 py-2 bg-yellow-400 text-gray-900 text-xs font-semibold rounded-full hover:bg-yellow-500 transition-colors whitespace-nowrap"
            >
              重新评测
            </button>
          </div>
        </div>

        {assessments.length === 0 ? (
          <EmptyState 
            icon={<span className="text-4xl">📊</span>}
            title="暂无健康评估报告"
          />
        ) : (
          <div className="space-y-3 pb-24">
            {assessments.map((assessment) => {
              // CRITICAL: 从assessment的questionnaire_data中获取体重数据，而不是从user_profiles获取
              // 这样每个报告显示的是创建时的快照数据，不会受到后续user_profiles更新的影响
              const currentWeight = assessment.questionnaire_data?.currentWeight || profileData?.current_weight;
              const targetWeight = assessment.questionnaire_data?.targetWeight || profileData?.target_weight;
              const assessmentFitnessGoal = assessment.questionnaire_data?.fitnessGoal || profileData?.fitness_goal;

              return (
                <div key={assessment.id} className="relative overflow-hidden rounded-2xl">
                  {/* Delete background (不显示给最新记录) */}
                  {!isLatestAssessment(assessment.id) && (
                    <div className="absolute inset-0 bg-red-500 flex items-center justify-end pr-6">
                      <span className="text-white font-medium">删除</span>
                    </div>
                  )}

                  {/* Assessment card */}
                  <div
                    id={`assessment-card-${assessment.id}`}
                    onClick={() => handleCardClick(assessment.id)}
                    onTouchStart={(e) => handleTouchStart(assessment.id, e)}
                    onTouchMove={(e) => handleTouchMove(assessment.id, e)}
                    onTouchEnd={() => handleTouchEnd(assessment.id)}
                    className="w-full bg-white rounded-2xl p-5 text-gray-800 relative shadow-sm border border-gray-200 cursor-pointer hover:shadow-md transition-shadow"
                    style={{ transition: 'transform 0.3s ease' }}
                  >
                    <div className="flex items-start justify-between mb-6">
                      <div>
                        <div className="flex items-center gap-1 mb-2">
                          <span className="text-sm text-gray-600 whitespace-nowrap">健康综合分数：</span>
                          {isLatestAssessment(assessment.id) && (
                            <span className="text-[10px] text-gray-400 bg-gray-100 px-3 py-0.5 rounded-full whitespace-nowrap">
                              使用中
                            </span>
                          )}
                        </div>
                        <div className="text-2xl font-bold text-gray-900">
                          {assessment.overall_score}
                          <span className="text-base text-gray-500">/100分</span>
                        </div>
                      </div>

                      <div className="text-right">
                        <div className="flex items-baseline justify-end gap-1 mb-2">
                          <span className="text-sm text-gray-600">目标：</span>
                          <span className="text-sm text-gray-600">{assessmentFitnessGoal ? getGoalTextFromGoal(assessmentFitnessGoal) : getGoalText()}</span>
                        </div>
                        {currentWeight && targetWeight ? (
                          <div className="text-xl font-bold text-gray-900 whitespace-nowrap">
                            {currentWeight.toFixed(1)}kg→{targetWeight.toFixed(1)}kg
                          </div>
                        ) : (
                          <div className="text-base text-gray-400">未设置</div>
                        )}
                      </div>
                    </div>

                    <div className="flex items-center justify-between">
                      <div>
                        <div className="text-sm text-gray-600 mb-1">评测日期：</div>
                        <p className="text-sm text-gray-500">
                          {formatDateTime(assessment.assessment_date)}
                        </p>
                      </div>

                      <button
                        onClick={(e) => handleViewClick(e, assessment.id)}
                        className="px-5 py-1.5 rounded-full border border-gray-900 bg-yellow-400 hover:bg-yellow-500 text-gray-900 text-xs font-medium transition-colors"
                      >
                        查看
                      </button>
                    </div>
                  </div>

                  {/* Delete button when swiped */}
                  {swipedAssessmentId === assessment.id && (
                    <div
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteClick(assessment.id);
                      }}
                      className="absolute top-0 right-0 bottom-0 bg-red-500 flex items-center justify-center cursor-pointer rounded-r-2xl"
                      style={{ width: '80px', zIndex: 5 }}
                    >
                      <span className="text-white font-medium text-sm">删除</span>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
        </>
        )}
        </div>

        {/* Delete Confirmation Modal */}
        <ConfirmModal
          show={!!deleteConfirmId}
          title="确认删除"
          message="确定要删除这份健康评测报告吗？删除后将无法恢复。"
          onCancel={handleCancelDelete}
          onConfirm={handleConfirmDelete}
          confirmText="确认删除"
          zIndex={100}
        />

        {/* Alert Dialog */}
        <AlertDialog
          show={showAlert}
          type="warning"
          title="提示"
          message={alertMessage}
          onClose={() => setShowAlert(false)}
          confirmText="确定"
        />
        {showReportArchive && (
          <MyHealthProfileScreen
            title="报告档案"
            onClose={() => setShowReportArchive(false)}
          />
        )}
          </>
        )}
      </div>
    </DrawerScreen>
  );
};

export default MyReportsScreen;

import React, { useState, useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { ChevronRight, MapPin, Package, Watch, Settings, Shield, HelpCircle, FileText, Copy, Check, LogOut, CalendarClock } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { useUserProfile } from '../contexts/UserProfileContext';
import { useProfileBadges, dismissProfileBadge } from '../hooks/useProfileBadges';
import LoginPage from './LoginPage';
import { ConfirmModal } from './common/ConfirmModal';
import { AlertDialog } from './common/AlertDialog';
import { useAlert } from '../hooks/useAlert';

interface ProfileScreenProps {
  onClose: () => void;
  onOpenPersonalInfo?: () => void;
  onOpenMyProfile?: () => void;
  onOpenAddress?: () => void;
  onOpenOrders?: () => void;
  onOpenDeliveryPlan?: () => void;
  onOpenReports?: () => void;
  onOpenDevices?: () => void;
  onOpenSettings?: () => void;
}

const ProfileScreen: React.FC<ProfileScreenProps> = ({
  onClose,
  onOpenPersonalInfo,
  onOpenMyProfile,
  onOpenAddress,
  onOpenOrders,
  onOpenDeliveryPlan,
  onOpenReports,
  onOpenDevices,
  onOpenSettings
}) => {
  const { isAuthenticated, signOut } = useAuth();
  const { profile, isLoading: profileLoading } = useUserProfile();
  const { ordersBadge, deliveryPlanBadge } = useProfileBadges();
  const queryClient = useQueryClient();
  const { alertState, showInfo, hideAlert } = useAlert();

  useEffect(() => {
    dismissProfileBadge('profile').then(() =>
      queryClient.invalidateQueries({ queryKey: ['profile-badges'] })
    );
  }, [queryClient]);

  React.useEffect(() => {
    if (!import.meta.env.DEV) return;
    console.log('👤 [ProfileScreen] Profile state:', {
      isAuthenticated,
      hasProfile: !!profile,
      profileLoading,
      nickname: profile?.nickname,
      displayUserId: profile?.display_user_id,
    });
  }, [isAuthenticated, profile, profileLoading]);
  const [showLoginPage, setShowLoginPage] = useState(false);
  const [copied, setCopied] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  const handleCopyUserId = (userId: string) => {
    navigator.clipboard.writeText(userId).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }).catch(err => {
      console.error('Failed to copy:', err);
    });
  };

  const menuSections = [
    {
      items: [
        { id: 'orders', label: '我的订单', icon: Package, badge: ordersBadge },
        { id: 'delivery-plan', label: '我的配送计划', icon: CalendarClock, badge: deliveryPlanBadge },
        { id: 'address', label: '收货地址', icon: MapPin },
      ]
    },
    {
      items: [
        { id: 'reports', label: '我的报告', icon: FileText },
        { id: 'devices', label: '我的设备', icon: Watch },
      ]
    },
    {
      items: [
        { id: 'settings', label: '设置', icon: Settings },
        { id: 'privacy', label: '隐私管理', icon: Shield },
        { id: 'help', label: '帮助与客服', icon: HelpCircle },
      ]
    },
    ...(isAuthenticated ? [{
      items: [
        { id: 'logout', label: '退出登录', icon: LogOut },
      ]
    }] : [])
  ];

  const handleMenuClick = async (itemId: string) => {
    switch (itemId) {
      case 'address':
        if (onOpenAddress) onOpenAddress();
        break;
      case 'orders':
        if (onOpenOrders) onOpenOrders();
        break;
      case 'delivery-plan':
        if (onOpenDeliveryPlan) onOpenDeliveryPlan();
        break;
      case 'reports':
        if (onOpenReports) onOpenReports();
        break;
      case 'devices':
        if (onOpenDevices) onOpenDevices();
        break;
      case 'settings':
        if (onOpenSettings) onOpenSettings();
        else showInfo('设置', '当前入口未连接设置页，请从个人资料进入。');
        break;
      case 'privacy':
        showInfo(
          '隐私管理',
          '我们按最小必要原则处理健康与账号数据。详细说明与导出/删除等能力将在后续版本提供；如需帮助请联系客服。'
        );
        break;
      case 'help':
        showInfo('帮助与客服', '使用中遇到问题可反馈给运营或技术支持；App 内智能助手也可协助日常健康问答。');
        break;
      case 'logout':
        setShowLogoutConfirm(true);
        break;
      default:
        if (import.meta.env.DEV) console.warn('[ProfileScreen] Unhandled menu:', itemId);
        showInfo('提示', '该功能即将开放。');
    }
  };

  if (showLoginPage) {
    return <LoginPage onBack={() => setShowLoginPage(false)} />;
  }

  return (
    <div className="flex flex-col bg-white">
      {/* Header - 已由App.tsx统一导航栏处理 */}
      {/* Scrollable Content */}
      <div className="px-6 pt-3 space-y-4 pb-4">
        {/* Profile Card */}
        <div
          className="bg-gray-100 rounded-xl p-3 shadow-sm cursor-pointer"
          onClick={() => {
            if (!isAuthenticated) {
              setShowLoginPage(true);
            } else if (onOpenPersonalInfo) {
              onOpenPersonalInfo();
            }
          }}
        >
          <div className="flex items-center space-x-3">
            <div className="w-12 h-12 rounded-full overflow-hidden bg-gray-200">
              {profile?.gender === 'male' ? (
                <img src="/nanmote.png" alt="Profile" className="w-full h-full object-cover" />
              ) : profile?.gender === 'female' ? (
                <img src="/nvmote.png" alt="Profile" className="w-full h-full object-cover" />
              ) : (
                <img
                  src="https://images.pexels.com/photos/774909/pexels-photo-774909.jpeg?auto=compress&cs=tinysrgb&w=100"
                  alt="Profile"
                  className="w-full h-full object-cover"
                />
              )}
            </div>
            <div className="flex-1">
              <h2 className="text-base font-semibold text-gray-800">
                {isAuthenticated ? (profile?.nickname || '用户') : '用户昵称'}
              </h2>
              {isAuthenticated ? (
                profile?.display_user_id ? (
                  <div className="flex items-center space-x-1">
                    <p className="text-xs text-gray-500">
                      ID:{profile.display_user_id}
                    </p>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleCopyUserId(profile.display_user_id!);
                      }}
                      className="p-0.5 hover:bg-gray-200 rounded transition-colors"
                    >
                      {copied ? (
                        <Check className="w-3 h-3 text-green-500" />
                      ) : (
                        <Copy className="w-3 h-3 text-gray-400" />
                      )}
                    </button>
                  </div>
                ) : profileLoading ? (
                  <p className="text-xs text-gray-500">加载中...</p>
                ) : (
                  <p className="text-xs text-gray-500">
                    点击查看个人信息{profile === null ? '（未找到档案）' : ''}
                  </p>
                )
              ) : (
                <p className="text-xs text-gray-500">点击登录</p>
              )}
            </div>
            <ChevronRight className="w-5 h-5 text-gray-400" />
          </div>
        </div>

        {/* Menu Content */}
          {menuSections.map((section, sectionIndex) => (
            <div key={sectionIndex} className="space-y-2">
              {section.title && (
                <h3 className="text-sm font-medium text-gray-500 px-2 mb-2">{section.title}</h3>
              )}

              <div className="bg-white rounded-xl overflow-hidden shadow-sm">
                {section.items.map((item, itemIndex) => (
                  <button
                    key={item.id}
                    onClick={() => handleMenuClick(item.id)}
                    className={`
                      w-full flex items-center justify-between px-4 py-4
                      hover:bg-gray-50 active:bg-gray-100 transition-colors
                      ${itemIndex !== section.items.length - 1 ? 'border-b border-gray-100' : ''}
                    `}
                  >
                    <div className="flex items-center space-x-3">
                      <item.icon className="w-5 h-5 text-gray-600" />
                      <span className="text-base text-gray-800">{item.label}</span>
                    </div>

                    <div className="flex items-center space-x-2">
                      {item.badge && (
                        <div className="w-2 h-2 bg-red-500 rounded-full"></div>
                      )}
                      <ChevronRight className="w-5 h-5 text-gray-400" />
                    </div>
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>

      {/* Logout Confirmation Modal */}
      <AlertDialog
        show={alertState.show}
        type={alertState.type}
        title={alertState.title}
        message={alertState.message}
        onClose={hideAlert}
        zIndex={75}
      />

      <ConfirmModal
        show={showLogoutConfirm}
        title="确认退出登录？"
        message="退出登录后，您需要重新登录才能使用相关功能。"
        onCancel={() => setShowLogoutConfirm(false)}
        onConfirm={async () => {
          try {
            setShowLogoutConfirm(false); // 先关闭模态框，避免用户重复点击
            await signOut();
            // signOut 成功后，App.tsx 会通过 onAuthStateChange 自动跳转到登录页
          } catch (error) {
            console.error('Failed to logout:', error);
            // 即使出错，也尝试关闭模态框
            setShowLogoutConfirm(false);
            // 可以在这里显示错误提示（如果需要）
            alert('退出登录失败，请重试');
          }
        }}
        confirmText="确认退出"
        zIndex={65}
      />
    </div>
  );
};

export default ProfileScreen;

import React, { useState } from 'react';
import { ChevronRight, Camera, AlertTriangle } from 'lucide-react';
import { useUserProfile } from '../contexts/UserProfileContext';
import { useAuth } from '../contexts/AuthContext';
import { supabase } from '../config/supabase';
import { kgToLbs, cmToFeetInches, calculateAge } from '../utils/bmrCalculations';
import { DrawerScreen } from './common/DrawerScreen';
import { ConfirmModal } from './common/ConfirmModal';
import { AlertDialog } from './common/AlertDialog';
import { SecondaryPageHeader } from './common/SecondaryPageHeader';
import { toLocalDateString } from '../utils/dateUtils';

interface ProfileSettingsScreenProps {
  onClose: () => void;
  onOpenOnboarding?: (resetProgress: boolean) => void;
}

interface ProfileField {
  label: string;
  value: string;
  id: string;
  isReadOnly?: boolean;
}

interface ProfileSection {
  title: string;
  fields: ProfileField[];
}

const ProfileSettingsScreen: React.FC<ProfileSettingsScreenProps> = ({ onClose, onOpenOnboarding }) => {
  const { profile } = useUserProfile();
  const { user } = useAuth();
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [showAlert, setShowAlert] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');
  const [alertType, setAlertType] = useState<'success' | 'error' | 'warning' | 'info'>('error');

  const handleClose = () => {
    onClose();
  };

  const formatGender = (gender?: string) => {
    if (gender === 'male') return '男';
    if (gender === 'female') return '女';
    return '未设置';
  };

  const formatDate = (date?: Date | string) => {
    if (!date) return '未设置';
    const d = typeof date === 'string' ? new Date(date) : date;
    return toLocalDateString(d);
  };

  const formatWeight = (weight?: number) => {
    if (!weight) return '未设置';
    return profile?.unit_preference === 'imperial'
      ? `${kgToLbs(weight).toFixed(1)} lbs`
      : `${weight.toFixed(1)} kg`;
  };

  const formatHeight = (height?: number) => {
    if (!height) return '未设置';
    if (profile?.unit_preference === 'imperial') {
      const { feet, inches } = cmToFeetInches(height);
      return `${feet}'${inches}"`;
    }
    return `${Math.round(height)} cm`;
  };

  const getAge = (): string => {
    if (profile?.birthday) {
      return `${calculateAge(profile.birthday)} 岁`;
    }
    return profile?.age ? `${profile.age} 岁` : '未设置';
  };

  const formatPhone = (phone?: string): string => {
    if (!phone) return '未设置';
    if (phone.length === 11) {
      return `${phone.slice(0, 3)}****${phone.slice(7)}`;
    }
    return phone;
  };

  const handleDeleteAccount = async () => {
    setIsDeleting(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        console.error('No authenticated user found');
        setAlertMessage('未找到登录用户');
        setAlertType('error');
        setShowAlert(true);
        setIsDeleting(false);
        return;
      }

      // Delete all user-related data from database tables
      const tablesToClear = [
        'health_records',
        'ai_conversations',
        'emotion_records',
        'meal_plans',
        'health_assessments',
        'nutrition_plans',
        'custom_reports',
        'custom_supplements',
        'user_packages',
        'delivery_addresses',
        'user_devices',
        'emotion_statistics',
        'chat_messages',
        'user_profiles'
      ];

      for (const table of tablesToClear) {
        try {
          await supabase.from(table).delete().eq('user_id', user.id);
        } catch (err) {
          console.error(`Error deleting from ${table}:`, err);
        }
      }

      // Clear all local storage
      localStorage.clear();

      // Sign out the user
      await supabase.auth.signOut();

      // Redirect to login/onboarding
      window.location.reload();
    } catch (error) {
      console.error('Error deleting account:', error);
      setAlertMessage('账号注销失败,请稍后重试');
      setAlertType('error');
      setShowAlert(true);
    } finally {
      setIsDeleting(false);
      setShowDeleteConfirm(false);
    }
  };

  const basicInfoFields: ProfileField[] = [
    {
      label: '我的昵称',
      value: profile?.nickname || '未设置',
      id: 'nickname'
    },
    {
      label: '性别',
      value: formatGender(profile?.gender),
      id: 'gender'
    },
    {
      label: '生日',
      value: formatDate(profile?.birthday),
      id: 'birthday'
    },
    {
      label: '年龄',
      value: getAge(),
      id: 'age',
      isReadOnly: true
    },
    {
      label: '身高',
      value: formatHeight(profile?.height),
      id: 'height'
    },
    {
      label: '体重',
      value: formatWeight(profile?.current_weight),
      id: 'current_weight'
    },
    {
      label: '注册手机号',
      value: formatPhone(profile?.phone),
      id: 'phone',
      isReadOnly: true
    }
  ];

  const sections: ProfileSection[] = [
    {
      title: '基本信息',
      fields: basicInfoFields
    }
  ];

  return (
    <DrawerScreen show={true} onClose={handleClose} showDragHandle={false} showMask={false}>
      <div className="flex flex-col h-full bg-gray-50">
        <SecondaryPageHeader title="编辑资料" onClose={handleClose} />

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto pb-6 scrollbar-hide">
            {/* Avatar Section */}
            <div className="flex justify-center py-6">
              <div className="relative">
                <div className="w-24 h-24 rounded-full overflow-hidden bg-gradient-to-br from-blue-100 to-blue-50">
                  {profile?.avatar_url ? (
                    <img src={profile.avatar_url} alt="Avatar" className="w-full h-full object-cover" />
                  ) : profile?.gender === 'male' ? (
                    <img src="/nanmote.png" alt="Avatar" className="w-full h-full object-cover" />
                  ) : profile?.gender === 'female' ? (
                    <img src="/nvmote.png" alt="Avatar" className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-gray-400">
                      <span className="text-3xl">👤</span>
                    </div>
                  )}
                </div>
                <button className="absolute bottom-0 right-0 w-8 h-8 bg-gray-800 rounded-full flex items-center justify-center shadow-lg hover:bg-gray-700 transition-colors">
                  <Camera className="w-4 h-4 text-white" />
                </button>
              </div>
            </div>

            {/* Profile Sections */}
            <div className="px-4 space-y-3">
              {sections.map((section, sectionIndex) => (
                <div key={sectionIndex}>
                  {/* Section Header */}
                  <div className="px-2 py-1.5 mb-1.5">
                    <h2 className="text-xs font-medium text-gray-500 uppercase tracking-wide">
                      {section.title}
                    </h2>
                  </div>

                  {/* Section Fields */}
                  <div className="bg-white rounded-2xl overflow-hidden">
                    {section.fields.map((field, fieldIndex) => (
                      <div
                        key={field.id}
                        className={`w-full flex items-center justify-between px-4 py-3 ${
                          fieldIndex !== section.fields.length - 1 ? 'border-b border-gray-100' : ''
                        }`}
                      >
                        <span className="text-sm text-gray-800">{field.label}</span>
                        <div className="flex items-center space-x-2">
                          <span className={`text-sm ${field.isReadOnly ? 'text-gray-400' : 'text-gray-500'}`}>
                            {field.value}
                          </span>
                          {!field.isReadOnly && (
                            <button
                              onClick={() => {
                              }}
                              className="p-1"
                            >
                              <ChevronRight className="w-4 h-4 text-gray-400" />
                            </button>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}

              {/* Delete Account Section */}
              <div className="mt-6">
                <button
                  onClick={() => setShowDeleteConfirm(true)}
                  className="w-full bg-white rounded-2xl px-4 py-3 flex items-center justify-between hover:bg-red-50 transition-colors group"
                >
                  <div className="flex items-center space-x-2">
                    <AlertTriangle className="w-5 h-5 text-red-500" />
                    <span className="text-sm text-red-500 font-medium">注销账号</span>
                  </div>
                  <ChevronRight className="w-4 h-4 text-red-400 group-hover:text-red-500" />
                </button>
                <p className="text-xs text-gray-400 mt-2 px-2">
                  注销后将永久删除所有数据,此操作不可恢复
                </p>
              </div>
            </div>
        </div>

        {/* Delete Confirmation Modal */}
        <ConfirmModal
          show={showDeleteConfirm}
          title="确认注销账号?"
          message={
            <div className="text-center">
              <div className="flex items-center justify-center w-16 h-16 bg-red-100 rounded-full mx-auto mb-4">
                <AlertTriangle className="w-8 h-8 text-red-500" />
              </div>
              <p className="text-sm text-gray-600">
                此操作将永久删除您的所有数据,包括健康记录、饮食计划、运动数据等。此操作不可恢复,请谨慎操作。
              </p>
            </div>
          }
          onCancel={() => setShowDeleteConfirm(false)}
          onConfirm={handleDeleteAccount}
          confirmText={isDeleting ? '正在注销...' : '确认注销'}
          cancelText="取消"
          zIndex={80}
        />

        {/* Alert Dialog */}
        <AlertDialog
          show={showAlert}
          type={alertType}
          title="提示"
          message={alertMessage}
          onClose={() => setShowAlert(false)}
          confirmText="确定"
        />
      </div>
    </DrawerScreen>
  );
};

export default ProfileSettingsScreen;

