import React, { useEffect, useRef, useState } from 'react';

interface ScrollPickerProps {
  value: number;
  onChange: (value: number) => void;
  min: number;
  max: number;
  unit?: string;
}

const ScrollPicker: React.FC<ScrollPickerProps> = ({ value, onChange, min, max, unit = '' }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const itemHeight = 50;
  const visibleItems = 4;
  const itemsAboveCenter = 2;

  const items = Array.from({ length: max - min + 1 }, (_, i) => min + i);

  const scrollToValue = (val: number) => {
    if (containerRef.current) {
      const index = val - min;
      const scrollTop = index * itemHeight;
      containerRef.current.scrollTop = scrollTop;
    }
  };

  useEffect(() => {
    scrollToValue(value);
  }, []);

  const handleScroll = () => {
    if (containerRef.current && !isDragging) {
      const scrollTop = containerRef.current.scrollTop;
      const index = Math.round(scrollTop / itemHeight);
      const newValue = Math.max(min, Math.min(max, min + index));
      if (newValue !== value) {
        onChange(newValue);
      }
    }
  };

  const handleScrollEnd = () => {
    if (containerRef.current) {
      const scrollTop = containerRef.current.scrollTop;
      const index = Math.round(scrollTop / itemHeight);
      const newValue = Math.max(min, Math.min(max, min + index));
      onChange(newValue);
      scrollToValue(newValue);
      setIsDragging(false);
    }
  };

  const handleTouchStart = () => {
    setIsDragging(true);
  };

  const handleTouchEnd = () => {
    handleScrollEnd();
  };

  const getItemStyle = (item: number): React.CSSProperties => {
    const index = item - min;
    const currentIndex = value - min;
    const distance = Math.abs(index - currentIndex);

    let opacity = 1;
    let scale = 1;
    let color = '#1f2937';
    let fontWeight = 'bold';
    let translateY = 0;

    if (distance === 0) {
      opacity = 1;
      scale = 0.6;
      color = '#1f2937';
      fontWeight = 'bold';
      translateY = 0;
    } else if (distance === 1) {
      opacity = 0.7;
      scale = 0.45;
      color = '#6b7280';
      fontWeight = '600';
      translateY = (index > currentIndex ? -8 : 8);
    } else if (distance === 2) {
      opacity = 0.5;
      scale = 0.35;
      color = '#9ca3af';
      fontWeight = 'normal';
      translateY = (index > currentIndex ? -14 : 14);
    } else {
      opacity = 0.3;
      scale = 0.3;
      color = '#d1d5db';
      fontWeight = 'normal';
      translateY = (index > currentIndex ? -18 : 18);
    }

    return {
      opacity,
      transform: `scale(${scale}) translateY(${translateY}px)`,
      color,
      fontWeight,
      transition: 'all 0.2s ease-out',
    };
  };

  return (
    <div className="relative w-full h-60 flex items-center justify-center">
      <div
        ref={containerRef}
        className="h-full w-full overflow-y-scroll scrollbar-hide snap-y snap-mandatory"
        onScroll={handleScroll}
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        onMouseDown={handleTouchStart}
        onMouseUp={handleTouchEnd}
        style={{
          paddingTop: `${itemHeight * itemsAboveCenter}px`,
          paddingBottom: `${itemHeight * itemsAboveCenter}px`,
        }}
      >
        {items.map((item) => (
          <div
            key={item}
            className="flex items-center justify-center snap-start"
            style={{
              height: `${itemHeight}px`,
              ...getItemStyle(item),
            }}
          >
            <div className="flex items-center gap-2">
              <span className="text-6xl">{item}</span>
              {unit && item === value && (
                <span className="text-3xl font-medium text-gray-600">{unit}</span>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ScrollPicker;

import React, { useState, useEffect } from 'react';
import { DrawerScreen } from './common/DrawerScreen';
import { SecondaryPageHeader } from './common/SecondaryPageHeader';
import { LoadingState } from './common/LoadingState';
import { EmptyState } from './common/EmptyState';
import { useExecutionProgram } from '../hooks/useExecutionProgram';
import { useExecutionReport } from '../hooks/useExecutionReport';
import { CheckCircle2, TrendingUp, Heart, Sparkles, Calendar, RefreshCw } from 'lucide-react';
import { formatDateTime } from '../utils/dateFormatters';
import { toLocalDateString } from '../utils/dateUtils';

interface SmartReportScreenProps {
  onClose: () => void;
}

/**
 * 智能执行报告页面
 * 显示每日/周报/里程碑报告，包含进度解释、情绪托管、身份强化
 */
const SmartReportScreen: React.FC<SmartReportScreenProps> = ({ onClose }) => {
  const { program } = useExecutionProgram();
  const { 
    dailyReport, 
    weeklyReport, 
    isLoadingDaily, 
    isLoadingWeekly,
    generateDailyReport,
    generateWeeklyReport 
  } = useExecutionReport(program?.id || null);

  const [activeTab, setActiveTab] = useState<'daily' | 'weekly'>('daily');
  const [isGenerating, setIsGenerating] = useState(false);

  const today = toLocalDateString(new Date());

  // 🔥 智能生成报告：只在任务完成情况变化时生成，否则直接显示已有报告
  useEffect(() => {
    if (!program?.id) return;

    // 检查是否有报告，如果没有才生成
    const checkAndGenerate = async () => {
      try {
        const currentReport = activeTab === 'daily' ? dailyReport : weeklyReport;

        // 如果没有报告，才生成
        if (!currentReport) {
          console.log('📊 [SmartReportScreen] No report found, generating...');
          setIsGenerating(true);
          if (activeTab === 'daily') {
            await generateDailyReport(today);
          } else {
            const weekStartDate = (() => {
              const date = new Date();
              const day = date.getDay();
              const diff = date.getDate() - day + (day === 0 ? -6 : 1);
              const monday = new Date(date.setDate(diff));
              return toLocalDateString(monday);
            })();
            await generateWeeklyReport(weekStartDate);
          }
          console.log('✅ [SmartReportScreen] Report generated');
        } else {
          console.log('✅ [SmartReportScreen] Report exists, checking if regeneration needed...');
          // 如果有报告，generateDailyReport 内部会检查任务变化，只在有变化时重新生成
          // 这里不设置 isGenerating，让用户看到已有报告，后台检查更新
          if (activeTab === 'daily') {
            generateDailyReport(today).catch(err => {
              console.error('❌ [SmartReportScreen] Error checking report update:', err);
            });
          } else {
            const weekStartDate = (() => {
              const date = new Date();
              const day = date.getDay();
              const diff = date.getDate() - day + (day === 0 ? -6 : 1);
              const monday = new Date(date.setDate(diff));
              return toLocalDateString(monday);
            })();
            generateWeeklyReport(weekStartDate).catch(err => {
              console.error('❌ [SmartReportScreen] Error checking report update:', err);
            });
          }
        }
      } catch (error) {
        console.error('❌ [SmartReportScreen] Error in checkAndGenerate:', error);
      } finally {
        setIsGenerating(false);
      }
    };

    checkAndGenerate();
  }, [program?.id, activeTab, today, generateDailyReport, generateWeeklyReport]);

  // 如果没有执行计划，显示空状态
  if (!program) {
    return (
      <DrawerScreen show={true} onClose={onClose} showDragHandle={false} showMask={false}>
        <div className="flex flex-col h-full bg-gray-50">
          <div className="sticky top-0 z-20 flex-shrink-0">
            <SecondaryPageHeader title="执行报告" onClose={onClose} />
          </div>
          <div className="flex-1 flex items-center justify-center px-4">
          <EmptyState
            icon={<span className="text-4xl">📊</span>}
            title="暂无执行计划"
            description="您需要先有活跃的执行计划才能查看报告"
          />
          </div>
        </div>
      </DrawerScreen>
    );
  }

  // 处理生成报告
  const handleGenerateReport = async (type: 'daily' | 'weekly') => {
    try {
      setIsGenerating(true);
      if (type === 'daily') {
        await generateDailyReport(today);
      } else {
        const weekStartDate = (() => {
          const date = new Date();
          const day = date.getDay();
          const diff = date.getDate() - day + (day === 0 ? -6 : 1);
          const monday = new Date(date.setDate(diff));
          return toLocalDateString(monday);
        })();
        await generateWeeklyReport(weekStartDate);
      }
    } catch (error) {
      console.error('Error generating report:', error);
      alert('生成报告失败，请重试');
    } finally {
      setIsGenerating(false);
    }
  };

  // 获取当前报告
  const currentReport = activeTab === 'daily' ? dailyReport : weeklyReport;
  const isLoading = activeTab === 'daily' ? isLoadingDaily : isLoadingWeekly;

  const summarySectionTitle = activeTab === 'daily' ? '今日总结' : '本周总结';
  const achievementsSectionTitle = activeTab === 'daily' ? '今日成就' : '本周亮点';

  return (
    <DrawerScreen show={true} onClose={onClose} showDragHandle={false} showMask={false}>
      <div className="flex flex-col h-full bg-gray-50 overflow-y-auto">
        <div className="sticky top-0 z-20 flex-shrink-0 bg-gray-50">
          <SecondaryPageHeader title="执行报告" onClose={onClose} />
        </div>

        <div className="flex-1 px-4 py-4">
          {/* 标签切换 */}
          <div className="flex gap-2 mb-4 bg-white rounded-xl p-1 shadow-sm">
            <button
              onClick={() => setActiveTab('daily')}
              className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition-colors ${
                activeTab === 'daily'
                  ? 'bg-gradient-to-r from-purple-500 to-blue-500 text-white shadow-sm'
                  : 'text-gray-600 hover:bg-gray-50'
              }`}
            >
              每日报告
            </button>
            <button
              onClick={() => setActiveTab('weekly')}
              className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition-colors ${
                activeTab === 'weekly'
                  ? 'bg-gradient-to-r from-purple-500 to-blue-500 text-white shadow-sm'
                  : 'text-gray-600 hover:bg-gray-50'
              }`}
            >
              周报
            </button>
          </div>

          {/* 加载状态 - 查询中或生成中 */}
          {(isLoading || isGenerating) && (
            <div className="bg-white rounded-2xl p-8 shadow-sm">
              <LoadingState spinnerColor="text-purple-400" />
              {isGenerating && (
                <div className="text-center mt-4 text-sm text-gray-500">
                  正在生成最新报告...
                </div>
              )}
            </div>
          )}

          {/* 报告内容 - 只有在不加载且不生成时才显示 */}
          {!isLoading && !isGenerating && currentReport && (
            <div className="space-y-4">
              {/* 进度概览 */}
              {currentReport.report_content.progress && (
                <div className="bg-gradient-to-br from-purple-50 to-blue-50 rounded-2xl p-5 shadow-sm border border-purple-100">
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2">
                      <TrendingUp className="w-5 h-5 text-purple-600" />
                      <h3 className="text-lg font-semibold text-gray-900">进度概览</h3>
                    </div>
                    <div className="text-right">
                      <div className="text-2xl font-bold text-gray-900">
                        {currentReport.report_content.progress.current_day}
                        <span className="text-sm text-gray-500">/{currentReport.report_content.progress.total_days}</span>
                      </div>
                      <div className="text-xs text-gray-500">天</div>
                    </div>
                  </div>

                  <div className="mb-2">
                    <div className="flex items-center justify-between text-sm mb-1">
                      <span className="text-gray-600">完成率</span>
                      <span className="font-semibold text-gray-900">
                        {currentReport.report_content.progress.completion_rate}%
                      </span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-gradient-to-r from-purple-500 to-blue-500 h-2 rounded-full transition-all duration-300"
                        style={{ width: `${currentReport.report_content.progress.completion_rate}%` }}
                      />
                    </div>
                  </div>
                </div>
              )}

              {/* 总结 */}
              {currentReport.report_content.summary && (
                <div className="bg-white rounded-2xl p-5 shadow-sm border border-gray-200">
                  <div className="flex items-center gap-2 mb-3">
                    <Calendar className="w-5 h-5 text-purple-600" />
                    <h3 className="text-lg font-semibold text-gray-900">{summarySectionTitle}</h3>
                  </div>
                  <p className="text-gray-700 leading-relaxed">
                    {currentReport.report_content.summary}
                  </p>
                </div>
              )}

              {/* 成就 */}
              {currentReport.report_content.achievements && currentReport.report_content.achievements.length > 0 && (
                <div className="bg-white rounded-2xl p-5 shadow-sm border border-gray-200">
                  <div className="flex items-center gap-2 mb-3">
                    <CheckCircle2 className="w-5 h-5 text-green-600" />
                    <h3 className="text-lg font-semibold text-gray-900">{achievementsSectionTitle}</h3>
                  </div>
                  <ul className="space-y-2">
                    {currentReport.report_content.achievements.map((achievement, index) => (
                      <li key={index} className="flex items-start gap-2">
                        <span className="text-green-500 mt-0.5">✓</span>
                        <span className="text-gray-700">{achievement}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}



              {/* 情绪托管 */}
              {currentReport.report_content.emotional_support && (
                <div className="bg-gradient-to-br from-pink-50 to-purple-50 rounded-2xl p-5 shadow-sm border border-pink-100">
                  <div className="flex items-center gap-2 mb-3">
                    <Heart className="w-5 h-5 text-pink-600" />
                    <h3 className="text-lg font-semibold text-gray-900">情绪支持</h3>
                  </div>
                  <p className="text-gray-700 leading-relaxed">
                    {currentReport.report_content.emotional_support}
                  </p>
                </div>
              )}

              {/* 身份强化 */}
              {currentReport.report_content.identity_reinforcement && (
                <div className="bg-gradient-to-br from-purple-50 to-blue-50 rounded-2xl p-5 shadow-sm border border-purple-100">
                  <div className="flex items-center gap-2 mb-3">
                    <Sparkles className="w-5 h-5 text-purple-600" />
                    <h3 className="text-lg font-semibold text-gray-900">身份强化</h3>
                  </div>
                  <p className="text-gray-700 leading-relaxed font-medium">
                    {currentReport.report_content.identity_reinforcement}
                  </p>
                </div>
              )}

              {/* 报告生成时间 */}
              <div className="flex items-center justify-center mt-4">
                <div className="text-center text-xs text-gray-400">
                  报告生成时间：{formatDateTime(currentReport.created_at)}
                </div>
              </div>
            </div>
          )}

          {/* 空状态 - 没有报告 */}
          {!isLoading && !currentReport && (
            <div className="bg-white rounded-2xl p-8 shadow-sm">
              <EmptyState
                icon={<span className="text-4xl">📊</span>}
                title={`暂无${activeTab === 'daily' ? '每日' : '周'}报告`}
                description={`点击下方按钮生成${activeTab === 'daily' ? '今日' : '本周'}的执行报告`}
              />
              <button
                onClick={() => handleGenerateReport(activeTab)}
                disabled={isGenerating}
                className="mt-6 w-full flex items-center justify-center gap-2 px-4 py-3 bg-gradient-to-r from-purple-500 to-blue-500 text-white rounded-xl font-medium hover:from-purple-600 hover:to-blue-600 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isGenerating ? (
                  <>
                    <RefreshCw className="w-4 h-4 animate-spin" />
                    <span>生成中...</span>
                  </>
                ) : (
                  <>
                    <Sparkles className="w-4 h-4" />
                    <span>生成{activeTab === 'daily' ? '今日' : '本周'}报告</span>
                  </>
                )}
              </button>
            </div>
          )}
        </div>
      </div>
    </DrawerScreen>
  );
};

export default SmartReportScreen;

