/**
 * 今日餐卡片 - 在对话窗口内展示当天餐食详情（菜品+营养）
 * 图3 风格：餐次、营养信息、菜品列表、配送状态
 *
 * 数据源分工：菜品/热量来自 **active-meal-schedule**（排期模板）；`mealPlanConfig` 仅用于无排期时的兜底展示与「第几天」mock；
 * **includedMeals**：有订单时先按排期/配置得到候选餐次，再与 **合约餐次**（orderMealPlanSlots）求交，与配送配置、日反馈一致。
 */

import React, { useEffect, useMemo, useState } from 'react';
import { X, UtensilsCrossed, CheckCircle } from 'lucide-react';
import { useQueryClient } from '@tanstack/react-query';
import { useUserProfile } from '../../contexts/UserProfileContext';
import { useAuth } from '../../contexts/AuthContext';
import { useChatContext } from '../../contexts/ChatContext';
import { useExecutionProgram } from '../../hooks/useExecutionProgram';
import { useContractMealSlotsEn } from '../../hooks/useContractMealSlotsEn';
import { useTodayConsumedMeals, TODAY_CONSUMED_MEALS_KEY } from '../../hooks/useTodayConsumedMeals';
import { getMealPlanConfig } from '../../services/mealPlanConfigService';
import { nutritionSyncService } from '../../services/nutritionSyncService';
import { setUserStorageItem } from '../../utils/userStorage';
import { executionTaskService } from '../../services/executionTaskService';
import { mealPlanData } from '../../utils/mockData';
import { getMealStatusByMealType, isMealDeliveryComplete } from '../../utils/mealUtils';
import { StatusBadge } from '../common/StatusBadge';
import { activeMealScheduleService, type ActiveMealScheduleEntry } from '../../services/activeMealScheduleService';
import { toBeijingDateString } from '../../utils/dateUtils';
import { DEFAULT_AI_COMPANION_NAME } from '../../services/aiSettingsService';

const MEAL_LABELS: Record<string, string> = {
  breakfast: '早餐',
  lunch: '午餐',
  dinner: '晚餐',
};
const FIRST_FEEDBACK_DELAY_MS = 1000;
const CARD_FEEDBACK_DELAY_MS = 2000;

export interface TodayMealsCardProps {
  onClose: () => void;
}

export default function TodayMealsCard({ onClose }: TodayMealsCardProps) {
  const { mealPlanConfig } = useUserProfile();
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const { addFeedbackMessage, ownerName, aiName } = useChatContext();
  const { program, hasOrder, isLoadingOrder } = useExecutionProgram();
  const { data: contractSlotsEn } = useContractMealSlotsEn();
  const { consumedMeals } = useTodayConsumedMeals();
  /** 有有效订单即视为已接入，避免执行计划同步延迟导致“有单却显示暂无餐食” */
  const isJourneyStarted = !isLoadingOrder && !!hasOrder;
  const [fallbackConfig, setFallbackConfig] = useState<typeof mealPlanConfig>(null);
  const [syncingMeal, setSyncingMeal] = useState<string | null>(null);
  const [optimisticConsumed, setOptimisticConsumed] = useState<Set<string>>(new Set());
  const [todayScheduleEntries, setTodayScheduleEntries] = useState<ActiveMealScheduleEntry[]>([]);
  const [scheduleLoaded, setScheduleLoaded] = useState(false);
  const getBusinessDateStr = (d: Date) => toBeijingDateString(d);

  // 🔥 与定制食谱一致：优先用 mealPlanConfig，否则从 service 拉取（确保今日餐与餐食计划内容一致）
  useEffect(() => {
    if (!mealPlanConfig && user?.id) {
      getMealPlanConfig(user.id).then(setFallbackConfig);
    } else {
      setFallbackConfig(null);
    }
  }, [mealPlanConfig, user?.id]);

  useEffect(() => {
    let isMounted = true;
    setScheduleLoaded(false);
    const todayStr = getBusinessDateStr(new Date());
    activeMealScheduleService.getActiveWeekSchedule('this_week', todayStr)
      .then((resp) => {
        if (!isMounted) return;
        const merged = resp?.entries || [];
        const rows = merged.filter((e) => String(e.date || '').split('T')[0] === todayStr);
        setTodayScheduleEntries(rows);
        setScheduleLoaded(true);
      })
      .catch(() => {
        if (!isMounted) return;
        setTodayScheduleEntries([]);
        setScheduleLoaded(true);
      });
    return () => {
      isMounted = false;
    };
  }, [user?.id]);

  // 当服务端数据已包含该餐次时，清除乐观更新（避免重复）
  useEffect(() => {
    setOptimisticConsumed((prev) => {
      if (prev.size === 0) return prev;
      const next = new Set(prev);
      prev.forEach((m) => {
        if (consumedMeals.has(m)) next.delete(m);
      });
      return next.size === prev.size ? prev : next;
    });
  }, [consumedMeals]);

  const effectiveConfig = mealPlanConfig ?? fallbackConfig;

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const startDate = effectiveConfig?.startDate
    ? new Date(effectiveConfig.startDate)
    : new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
  startDate.setHours(0, 0, 0, 0);

  const daysSinceStart = Math.floor((today.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
  const currentMealPlanDay = daysSinceStart + 1;

  const currentMeal =
    currentMealPlanDay >= 1 &&
    currentMealPlanDay <= 30 &&
    mealPlanData[currentMealPlanDay as keyof typeof mealPlanData]
      ? mealPlanData[currentMealPlanDay as keyof typeof mealPlanData]
      : null;

  const getMealTypeFromPackageType = (packageType?: string) => {
    if (packageType === '早餐') return 'breakfast';
    if (packageType === '晚餐') return 'dinner';
    return 'lunch';
  };

  const scheduleMealMap = todayScheduleEntries.reduce((acc, entry) => {
    const formatKcal = (value: number) => Number(value.toFixed(1));
    const mealType = getMealTypeFromPackageType(entry.package_type);
    const foods = (entry.dishes || []).map((d, idx) => ({
      id: d.dish?.id || `${entry.id}-${idx}`,
      name: d.dish?.name || d.dish?.dish_code || '菜品',
      calories: formatKcal(Number(d.dish?.calories_kcal || 0) * Number(d.quantity || 1)),
      icon: '🍽️'
    }));
    const caloriesFromDishes = (entry.dishes || []).reduce((sum, d) => {
      const qty = Number(d.quantity || 1);
      return sum + Number(d.dish?.calories_kcal || 0) * qty;
    }, 0);
    const totalCalories = formatKcal(caloriesFromDishes || Number(entry.package?.total_calories_kcal || 0));
    acc[mealType] = {
      foods,
      calories: totalCalories
    };
    return acc;
  }, {} as Record<string, { foods: Array<{ id: string; name: string; calories: number; icon: string }>; calories: number }>);

  const mealTypes = ['breakfast', 'lunch', 'dinner'] as const;
  const getStatusBadgeType = (mealType: string) => {
    const mealStatus = getMealStatusByMealType(today, mealType);
    return mealStatus === '已配送完成'
      ? 'delivered'
      : mealStatus === '配送中'
        ? 'delivering'
        : mealStatus === '制作中'
          ? 'making'
          : 'not-started';
  };
  /** 有排期则只展示当日 MS 里出现的餐次；否则退回用户配送配置餐次；有订单时再与合约餐次求交 */
  const includedMeals = useMemo(() => {
    const raw = hasOrder
      ? (['breakfast', 'lunch', 'dinner'] as const).filter((m) => !!scheduleMealMap[m])
      : todayScheduleEntries.length > 0
        ? (['breakfast', 'lunch', 'dinner'] as const).filter((m) => !!scheduleMealMap[m])
        : (effectiveConfig?.selectedMealTypes || ['lunch', 'dinner']);
    if (!hasOrder || !contractSlotsEn?.length) return [...raw];
    const allow = new Set(contractSlotsEn.map((s) => String(s).toLowerCase()));
    return raw.filter((m) => allow.has(String(m).toLowerCase()));
  }, [hasOrder, contractSlotsEn, todayScheduleEntries, effectiveConfig?.selectedMealTypes]);

  const handleIntakeComplete = async (mealType: string, meal: { calories?: number; foods?: Array<{ name: string }> }) => {
    const canClick = isMealDeliveryComplete(today, mealType) && !consumedMeals.has(mealType) && !optimisticConsumed.has(mealType);
    if (!canClick || syncingMeal) return;

    setSyncingMeal(mealType);
    setOptimisticConsumed((prev) => new Set(prev).add(mealType));
    const mealLabel = MEAL_LABELS[mealType];
    try {
      const foodName = meal.foods?.length
        ? `${mealLabel}：${meal.foods.map((f) => f.name).join('、')}`
        : mealLabel;
      const calories = meal.calories || 0;
      const dateKey = getBusinessDateStr(today);
      const orderSyncId =
        user?.id != null
          ? `order-intake-${dateKey}-${mealType}-${user.id}-${Date.now()}`
          : `order-intake-${dateKey}-${mealType}-${Date.now()}`;
      await nutritionSyncService.saveFoodEntry(foodName, calories, mealLabel, 1, today, 'manual', undefined, undefined, {
        syncId: orderSyncId,
      });
      if (user?.id) {
        queryClient.invalidateQueries({ queryKey: ['food-records', user.id] });
        const nextArr = (() => {
          const old = queryClient.getQueryData<string[]>([TODAY_CONSUMED_MEALS_KEY, user.id, dateKey]);
          const arr = Array.isArray(old) ? [...old] : [];
          if (!arr.includes(mealType)) arr.push(mealType);
          return arr;
        })();
        queryClient.setQueryData<string[]>([TODAY_CONSUMED_MEALS_KEY, user.id, dateKey], nextArr);
        await setUserStorageItem('today-consumed-meals', { dateKey, meals: nextArr }); // 备份到 userStorage
        await queryClient.refetchQueries({ queryKey: ['dashboard-data', user.id, dateKey] });
      }
      if (program?.id) {
        try {
          const localDate = getBusinessDateStr(today);
          await executionTaskService.insertMealIntakeNotifications(program.id, localDate, mealType, mealLabel);
          queryClient.invalidateQueries({ queryKey: ['daily-tasks', program.id, localDate] });
        } catch (taskErr) {
          console.warn('[TodayMealsCard] 插入实时通知失败（不影响主流程）:', taskErr);
        }
      }
      await new Promise((resolve) => setTimeout(resolve, FIRST_FEEDBACK_DELAY_MS));
      await addFeedbackMessage(`${aiName || DEFAULT_AI_COMPANION_NAME}已完成[餐食：${mealLabel}]摄入记录并同步热量营养，${ownerName || '主人'}加油！`);
    } catch (e) {
      console.error('[TodayMealsCard] 同步热量失败:', e);
      setOptimisticConsumed((prev) => {
        const next = new Set(prev);
        next.delete(mealType);
        return next;
      });
      await new Promise((resolve) => setTimeout(resolve, CARD_FEEDBACK_DELAY_MS));
      await addFeedbackMessage('同步热量失败，请重试。');
    } finally {
      setSyncingMeal(null);
    }
  };

  return (
    <div className="mb-3 rounded-2xl border border-gray-200 bg-white shadow-lg overflow-hidden">
      <div className="px-3 py-2.5 flex items-center justify-between bg-gradient-to-r from-purple-50 to-blue-50 border-b border-gray-100">
        <div className="flex items-center gap-2">
          <UtensilsCrossed className="w-5 h-5 text-purple-600" />
          <span className="font-semibold text-gray-900">今日餐</span>
        </div>
        <button onClick={onClose} className="p-1.5 rounded-full hover:bg-gray-200/80">
          <X className="w-4 h-4 text-gray-600" />
        </button>
      </div>
      <div className="px-3 py-3">
        {!isJourneyStarted ? (
          <p className="text-sm text-gray-500 py-4 text-center">今日暂无餐食计划</p>
        ) : hasOrder && !scheduleLoaded ? (
          <p className="text-sm text-gray-500 py-4 text-center">正在同步今日排期...</p>
        ) : hasOrder && todayScheduleEntries.length === 0 ? (
          <p className="text-sm text-gray-500 py-4 text-center">今日暂无排期餐食</p>
        ) : (!currentMeal && todayScheduleEntries.length === 0) ? (
          <p className="text-sm text-gray-500 py-4 text-center">今日暂无餐食计划</p>
        ) : (
          <div className="space-y-4">
            {mealTypes.map((mealType) => {
              if (!includedMeals.includes(mealType)) return null;
              const meal = scheduleMealMap[mealType] || (!hasOrder ? currentMeal?.[mealType] : null);
              if (!meal) return null;
              const isConsumed = consumedMeals.has(mealType) || optimisticConsumed.has(mealType);

              return (
                <div
                  key={mealType}
                  className={`rounded-xl border overflow-hidden ${
                    isConsumed ? 'border-gray-100 bg-gray-50 opacity-80' : 'border-gray-200 bg-gray-50/50'
                  }`}
                >
                  <div className="px-3 py-2 flex items-center justify-between bg-gray-100/80 border-b border-gray-200">
                    <span className={`font-medium ${isConsumed ? 'text-gray-500' : 'text-gray-800'}`}>
                      {MEAL_LABELS[mealType]}
                    </span>
                    <StatusBadge status={getStatusBadgeType(mealType)} className="text-xs" />
                  </div>
                  <div className="p-2.5">
                    {meal.image && (
                      <div className="relative rounded-lg overflow-hidden mb-3">
                        <img
                          src={meal.image}
                          alt={MEAL_LABELS[mealType]}
                          className="w-full h-32 object-cover"
                        />
                        <div className="absolute top-2 right-2 bg-black/70 rounded-lg px-2 py-1 text-white text-xs">
                          {meal.nutrition?.map((n, i) => (
                            <span key={i}>
                              {n.name} {n.value}
                              {i < (meal.nutrition?.length || 0) - 1 ? ' · ' : ''}
                            </span>
                          ))}
                          {meal.calories && ` · ${meal.calories} kcal`}
                        </div>
                      </div>
                    )}
                    <div className="space-y-1.5">
                      {meal.foods?.map((f) => (
                        <div
                          key={f.id}
                          className={`flex items-center justify-between text-sm ${isConsumed ? 'text-gray-500' : 'text-gray-700'}`}
                        >
                          <span>
                            {f.icon} {f.name}
                          </span>
                          <span className="text-gray-500">{f.calories} kcal</span>
                        </div>
                      ))}
                    </div>
                    {!isConsumed ? (
                      <button
                        onClick={() => handleIntakeComplete(mealType, meal)}
                        disabled={!isMealDeliveryComplete(today, mealType) || syncingMeal === mealType}
                        className={`mt-3 w-full py-2 text-sm font-medium rounded-lg flex items-center justify-center gap-1.5 ${
                          isMealDeliveryComplete(today, mealType) && syncingMeal !== mealType
                            ? 'bg-gradient-to-r from-purple-500 to-blue-500 text-white hover:from-purple-600 hover:to-blue-600'
                            : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                        }`}
                      >
                        <CheckCircle className="w-4 h-4" />
                        {syncingMeal === mealType
                          ? '同步中...'
                          : isMealDeliveryComplete(today, mealType)
                            ? '完成摄入'
                            : '暂不可操作'}
                      </button>
                    ) : (
                      <div className="mt-3 py-2 text-sm font-medium text-green-700 bg-green-100 rounded-lg flex items-center justify-center gap-1.5">
                        <CheckCircle className="w-4 h-4 text-green-500" />
                        已摄入
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { User } from 'lucide-react';
import { splitAddressHighlightSegments, stripMarkdownBoldMarkersForChat } from '../../utils/chatUtils';

interface ChatMessageBubbleProps {
  type: 'user' | 'ai';
  content: string;
  timestamp?: string;
  emotionEmoji?: string;
  userGender?: 'male' | 'female' | '';
  showAvatar?: boolean;
  onAvatarClick?: () => void;
  className?: string;
}

/**
 * 聊天消息气泡组件
 * 支持用户消息和AI消息两种类型
 */
export function ChatMessageBubble({
  type,
  content,
  timestamp,
  emotionEmoji,
  userGender = '',
  showAvatar = true,
  onAvatarClick,
  className = ''
}: ChatMessageBubbleProps) {
  const isUser = type === 'user';
  const displayContent = !isUser ? stripMarkdownBoldMarkersForChat(content) : content;
  const aiLines = !isUser ? displayContent.split('\n') : [];

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} ${className}`}>
      {/* AI头像（左侧） */}
      {!isUser && showAvatar && onAvatarClick && (
        <button
          onClick={onAvatarClick}
          className="w-8 h-8 rounded-full bg-purple-200 flex items-center justify-center mr-2 flex-shrink-0 hover:bg-purple-300 transition-colors"
          aria-label="AI设置"
        >
          <span className="text-lg">🐰</span>
        </button>
      )}

      {/* 消息气泡 */}
      <div className={`max-w-xs ${
        isUser
          ? 'bg-purple-500 text-white rounded-2xl rounded-br-md max-w-[220px]'
          : 'bg-gray-100 text-gray-800 rounded-2xl rounded-bl-md max-w-[220px] border border-gray-200'
      } px-2.5 py-1.5 shadow-sm`}>
        <div className="text-sm leading-normal">
          {isUser
            ? <div className="whitespace-pre-line">{displayContent}</div>
            : aiLines.map((line, lineIdx) => {
                if (line.trim() === '---') {
                  return (
                    <div
                      key={`divider-${lineIdx}`}
                      className="my-1 border-t border-gray-300/60"
                    />
                  );
                }
                const segments = splitAddressHighlightSegments(line);
                return (
                  <React.Fragment key={`line-${lineIdx}`}>
                    {segments.map((seg, idx) => (
                      <span
                        key={`${lineIdx}-${idx}-${seg.highlight ? 'h' : 'n'}`}
                        className={seg.highlight ? 'font-semibold text-black' : undefined}
                      >
                        {seg.text}
                      </span>
                    ))}
                    {lineIdx < aiLines.length - 1 && <br />}
                  </React.Fragment>
                );
              })}
        </div>
        {emotionEmoji && (
          <div className="mt-1 text-right">
            <span className="text-lg">{emotionEmoji}</span>
          </div>
        )}
      </div>

      {/* 用户头像（右侧） */}
      {isUser && showAvatar && (
        <div className="w-8 h-8 rounded-full bg-gray-200 flex items-center justify-center ml-2 flex-shrink-0 overflow-hidden">
          {userGender === 'male' ? (
            <img src="/nanmote.png" alt="User" className="w-full h-full object-cover" />
          ) : userGender === 'female' ? (
            <img src="/nvmote.png" alt="User" className="w-full h-full object-cover" />
          ) : (
            <User className="w-5 h-5 text-gray-600" />
          )}
        </div>
      )}
    </div>
  );
}

/**
 * DataAnalysisCard - 数据分析卡片组件
 * 性能优化：使用React.memo避免不必要的重渲染
 */

import React, { useMemo } from 'react';
import { TrendingUp, TrendingDown, Minus, BarChart3 } from 'lucide-react';
import { SectionCard } from './SectionCard';

type DataPoint = {
  value: number;
  [key: string]: any;
};

type DataAnalysisCardProps = {
  currentData: DataPoint[];
  previousData?: DataPoint[];
  dataType: 'steps' | 'weight' | 'water' | 'exercise' | 'sleep' | 'bloodGlucose' | 'measurements';
  period: '月' | '年' | '季度';
  valueKey?: string; // 数据点的值字段名，默认为'value'，也可以是'steps', 'calories', 'amount'等
};

const DataAnalysisCardComponent: React.FC<DataAnalysisCardProps> = ({
  currentData,
  previousData,
  dataType,
  period,
  valueKey
}) => {
  // 设置默认值
  const finalValueKey: string = valueKey ?? 'value';
  // 计算统计指标
  const stats = useMemo(() => {
    const values = currentData
      .map(d => {
        const val = d[finalValueKey] || d.value || d.steps || d.calories || d.amount || 0;
        return typeof val === 'number' ? val : 0;
      })
      .filter(v => v > 0);

    if (values.length === 0) {
      return {
        avg: 0,
        max: 0,
        min: 0,
        hasData: false
      };
    }

    const avg = values.reduce((sum, v) => sum + v, 0) / values.length;
    const max = Math.max(...values);
    const min = Math.min(...values);

    return {
      avg: avg,
      max: max,
      min: min,
      hasData: true
    };
  }, [currentData, finalValueKey]);

  // 计算上一周期的统计指标
  const previousStats = useMemo(() => {
    if (!previousData || previousData.length === 0) {
      return null;
    }

    const values = previousData
      .map(d => {
        const val = d[finalValueKey] || d.value || d.steps || d.calories || d.amount || 0;
        return typeof val === 'number' ? val : 0;
      })
      .filter(v => v > 0);

    if (values.length === 0) {
      return null;
    }

    const avg = values.reduce((sum, v) => sum + v, 0) / values.length;
    return { avg };
  }, [previousData, finalValueKey]);

  // 计算变化百分比
  const changePercent = useMemo(() => {
    if (!previousStats || stats.avg === 0) {
      return null;
    }

    if (previousStats.avg === 0) {
      return stats.avg > 0 ? 100 : null;
    }

    return ((stats.avg - previousStats.avg) / previousStats.avg) * 100;
  }, [stats.avg, previousStats]);

  // 判断趋势
  const trend = useMemo(() => {
    if (changePercent === null) {
      return 'stable';
    }
    if (changePercent > 5) {
      return 'up';
    } else if (changePercent < -5) {
      return 'down';
    } else {
      return 'stable';
    }
  }, [changePercent]);

  // 生成可能的原因说明
  const getReasonExplanation = (): string[] => {
    if (!stats.hasData) {
      return ['数据不足，无法进行分析'];
    }

    const reasons: string[] = [];

    if (changePercent === null) {
      reasons.push('暂无对比数据');
      return reasons;
    }

    switch (dataType) {
      case 'steps':
        if (trend === 'up') {
          reasons.push('运动习惯可能有所改善');
          reasons.push('日常活动量可能增加');
          reasons.push('可能增加了步行或运动时间');
        } else if (trend === 'down') {
          reasons.push('活动量可能减少');
          reasons.push('可能因身体不适或休息日增加');
          reasons.push('日常运动习惯可能有所改变');
        } else {
          reasons.push('步数保持相对稳定');
          reasons.push('运动习惯较为规律');
        }
        break;

      case 'weight':
        if (trend === 'up') {
          reasons.push('饮食摄入可能增加');
          reasons.push('运动量可能减少');
          reasons.push('可能处于增重期或恢复期');
        } else if (trend === 'down') {
          reasons.push('饮食控制可能更严格');
          reasons.push('运动量可能增加');
          reasons.push('可能处于减重期');
        } else {
          reasons.push('体重保持相对稳定');
          reasons.push('饮食和运动可能较为平衡');
        }
        break;

      case 'water':
        if (trend === 'up') {
          reasons.push('饮水量可能增加');
          reasons.push('可能更注重水分补充');
          reasons.push('天气或活动量可能增加');
        } else if (trend === 'down') {
          reasons.push('饮水量可能减少');
          reasons.push('可能忘记及时补充水分');
          reasons.push('活动量可能减少');
        } else {
          reasons.push('饮水量保持相对稳定');
          reasons.push('水分补充习惯较为规律');
        }
        break;

      case 'exercise':
        if (trend === 'up') {
          reasons.push('运动强度或时长可能增加');
          reasons.push('可能增加了新的运动项目');
          reasons.push('运动频率可能提高');
        } else if (trend === 'down') {
          reasons.push('运动量可能减少');
          reasons.push('可能因时间安排或身体原因减少运动');
          reasons.push('运动强度可能降低');
        } else {
          reasons.push('运动量保持相对稳定');
          reasons.push('运动习惯较为规律');
        }
        break;

      case 'sleep':
        if (trend === 'up') {
          reasons.push('睡眠时长可能增加');
          reasons.push('作息可能更加规律');
          reasons.push('睡眠质量可能改善');
        } else if (trend === 'down') {
          reasons.push('睡眠时长可能减少');
          reasons.push('可能因工作压力或作息不规律');
          reasons.push('睡眠质量可能下降');
        } else {
          reasons.push('睡眠时长保持相对稳定');
          reasons.push('作息习惯较为规律');
        }
        break;

      case 'bloodGlucose':
        if (trend === 'up') {
          reasons.push('血糖水平可能上升');
          reasons.push('饮食结构可能发生变化');
          reasons.push('可能需要调整饮食或运动计划');
        } else if (trend === 'down') {
          reasons.push('血糖水平可能下降');
          reasons.push('饮食控制可能更有效');
          reasons.push('运动可能对血糖控制有帮助');
        } else {
          reasons.push('血糖水平保持相对稳定');
          reasons.push('血糖管理较为良好');
        }
        break;

      case 'measurements':
        if (trend === 'up') {
          reasons.push('围度可能有所增加');
          reasons.push('可能处于增肌或增重期');
          reasons.push('运动或饮食可能发生变化');
        } else if (trend === 'down') {
          reasons.push('围度可能有所减少');
          reasons.push('可能处于减脂期');
          reasons.push('运动或饮食控制可能更有效');
        } else {
          reasons.push('围度保持相对稳定');
          reasons.push('身体状态较为稳定');
        }
        break;

      default:
        reasons.push('数据变化需要进一步观察');
    }

    return reasons;
  };

  const reasons = getReasonExplanation();

  // 格式化数值
  const formatValue = (value: number): string => {
    if (dataType === 'weight') {
      return `${value.toFixed(1)}kg`;
    } else if (dataType === 'water') {
      return `${value.toFixed(0)}ml`;
    } else if (dataType === 'exercise') {
      return `${value.toFixed(0)}kcal`;
    } else if (dataType === 'sleep') {
      return `${value.toFixed(1)}h`;
    } else if (dataType === 'bloodGlucose') {
      return `${value.toFixed(1)}mmol/L`;
    } else if (dataType === 'measurements') {
      return `${value.toFixed(1)}cm`;
    } else {
      return `${value.toFixed(0)}`;
    }
  };

  if (!stats.hasData) {
    return null;
  }

  return (
    <SectionCard className="my-1">
      <div className="flex items-center space-x-2 mb-4">
        <BarChart3 className="w-5 h-5 text-gray-400" />
        <h3 className="text-lg font-medium text-gray-700">数据解读</h3>
      </div>

      {/* 统计信息 */}
      <div className="grid grid-cols-3 gap-4 mb-4">
        <div>
          <div className="text-xs text-gray-500 mb-1">平均值</div>
          <div className="text-lg font-bold text-gray-800">{formatValue(stats.avg)}</div>
        </div>
        <div>
          <div className="text-xs text-gray-500 mb-1">最高值</div>
          <div className="text-lg font-bold text-gray-800">{formatValue(stats.max)}</div>
        </div>
        <div>
          <div className="text-xs text-gray-500 mb-1">最低值</div>
          <div className="text-lg font-bold text-gray-800">{formatValue(stats.min)}</div>
        </div>
      </div>

      {/* 变化趋势 */}
      {changePercent !== null && (
        <div className="mb-4 p-3 bg-gray-50 rounded-xl">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2">
              {trend === 'up' && <TrendingUp className="w-5 h-5 text-green-500" />}
              {trend === 'down' && <TrendingDown className="w-5 h-5 text-red-500" />}
              {trend === 'stable' && <Minus className="w-5 h-5 text-gray-500" />}
              <span className="text-sm text-gray-600">
                较上{period === '季度' ? '季度' : period === '月' ? '月' : '年'}
              </span>
            </div>
            <div
              className={`text-lg font-bold ${
                trend === 'up'
                  ? 'text-green-600'
                  : trend === 'down'
                  ? 'text-red-600'
                  : 'text-gray-600'
              }`}
            >
              {changePercent > 0 ? '+' : ''}
              {changePercent.toFixed(1)}%
            </div>
          </div>
        </div>
      )}

      {/* 可能的原因说明 */}
      <div>
        <div className="text-sm font-medium text-gray-700 mb-2">可能的原因：</div>
        <ul className="space-y-1">
          {reasons.map((reason, index) => (
            <li key={index} className="text-sm text-gray-600 flex items-start">
              <span className="text-gray-400 mr-2">•</span>
              <span>{reason}</span>
            </li>
          ))}
        </ul>
      </div>
    </SectionCard>
  );
};

export const DataAnalysisCard = React.memo(DataAnalysisCardComponent);

import React, { useEffect, useLayoutEffect, useMemo, useRef, useState, useCallback } from 'react'
import { APP_HEADER_HEIGHT_CSS, FULL_PANEL_HEIGHT_MINUS_HEADER_CSS } from '../../constants/appLayout'

type MaskProps = {
  visible?: boolean
  clickable?: boolean
  zIndex?: number
}

type DragPanelProps = {
  zIndex?: number
  animationDuration?: number
  onClose: () => void
  show: boolean
  header?: React.ReactNode
  footer?: React.ReactNode
  mask?: MaskProps
  children?: React.ReactNode
  maxHeight?: string | number // 最大高度，用于非全屏弹窗
  maxWidth?: string // 最大宽度，用于居中弹窗（如 'max-w-xs', 'max-w-sm' 等）
}

export function DragPanel(props: DragPanelProps) {
  const {
    zIndex = 60,
    animationDuration = 500,
    onClose,
    show,
    header,
    footer,
    mask,
    children,
    maxHeight,
    maxWidth = 'max-w-sm', // 默认值
  } = props

  const [closing, setClosing] = useState(false)
  const closingLock = useRef(false)
  const panelRef = useRef<HTMLDivElement | null>(null)
  const scrollRef = useRef<HTMLDivElement | null>(null)
  const startY = useRef<number | null>(null)
  const startX = useRef<number | null>(null)
  const currentY = useRef<number>(0)
  const dragging = useRef(false)
  const isScrolling = useRef(false)
  const prevShowRef = useRef(show)

  // 监听 show prop 的变化，当从 true 变为 false 时触发关闭动画
  useEffect(() => {
    if (prevShowRef.current && !show && !closing && !closingLock.current) {
      // show 从 true 变为 false，触发关闭动画，但不调用 onClose（因为父组件已经通过 show prop 控制关闭）
      closingLock.current = true
      setClosing(true)

      // 重置拖拽状态
      dragging.current = false
      isScrolling.current = false
      startY.current = null
      startX.current = null
      currentY.current = 0
      document.body.style.userSelect = ''

      if (panelRef.current) {
        if (maxHeight) {
          // 居中弹窗使用scale和opacity动画
          panelRef.current.style.transition = `transform ${animationDuration}ms ease-out, opacity ${animationDuration}ms ease-out`
          panelRef.current.style.transform = 'scale(0.95)'
          panelRef.current.style.opacity = '0'
        } else {
          // 全屏弹窗使用translateY动画
          panelRef.current.style.transition = `transform ${animationDuration}ms ease-out`
          panelRef.current.style.transform = 'translateY(100%)'
        }
      }

      const timeoutId = setTimeout(() => {
        closingLock.current = false
        setClosing(false)
        if (panelRef.current) {
          panelRef.current.style.transition = ''
          panelRef.current.style.willChange = ''
          panelRef.current.style.transform = maxHeight ? 'scale(1)' : 'translateY(0)'
          if (maxHeight) {
            panelRef.current.style.opacity = '1'
          }
        }
      }, animationDuration)

      return () => clearTimeout(timeoutId)
    }
    prevShowRef.current = show
  }, [show, maxHeight, animationDuration])

  // 遮罩层比内容层低一个档位：z-60 内容 → z-55 遮罩，z-70 内容 → z-65 遮罩
  const maskZ = useMemo(() => {
    if (mask?.zIndex !== undefined) return mask.zIndex
    if (zIndex === 60) return 55
    if (zIndex === 70) return 65
    return zIndex - 5 // 默认低 5 个单位（保持向后兼容）
  }, [mask?.zIndex, zIndex])

  /** 全屏底部面板：滑入/滑出均由该状态 + CSS transition 驱动（避免子组件重绘冲掉 transform） */
  const [fsSlideIn, setFsSlideIn] = useState(false)

  // 定义 handleClose，必须在 useEffect 之前
  const handleClose = useCallback((skipOnClose = false) => {
    console.log('[DragPanel] handleClose called, skipOnClose:', skipOnClose, 'closingLock:', closingLock.current);
    if (closingLock.current) {
      console.log('[DragPanel] Already closing, ignoring');
      return
    }
    closingLock.current = true
    setClosing(true)
    if (!maxHeight) {
      setFsSlideIn(false)
    }

    // 重置拖拽状态
    dragging.current = false
    isScrolling.current = false
    startY.current = null
    startX.current = null
    currentY.current = 0
    document.body.style.userSelect = ''

    // 立即调用 onClose，不要等待动画
    if (!skipOnClose) {
      try {
        console.log('[DragPanel] Calling onClose immediately');
        onClose()
      } catch (error) {
        console.error('[DragPanel] Error in onClose callback:', error)
      }
    }

    if (panelRef.current) {
      if (maxHeight) {
        // 居中弹窗使用scale和opacity动画
        panelRef.current.style.transition = `transform ${animationDuration}ms ease-out, opacity ${animationDuration}ms ease-out`
        panelRef.current.style.transform = 'scale(0.95)'
        panelRef.current.style.opacity = '0'
      }
      // 全屏：关闭动画由 fsSlideIn=false + JSX transition 完成，勿再写 DOM transform，否则与 React 冲突
    }

    // 动画完成后重置状态
    const timeoutId = setTimeout(() => {
      closingLock.current = false
      setClosing(false)
      if (panelRef.current) {
        panelRef.current.style.transition = ''
        panelRef.current.style.willChange = ''
        if (maxHeight) {
          panelRef.current.style.transform = 'scale(1)'
          panelRef.current.style.opacity = '1'
        }
      }
      console.log('[DragPanel] Animation complete, reset closing state');
    }, animationDuration)

    // 返回清理函数（虽然这里不会直接使用，但可以确保清理）
    return () => clearTimeout(timeoutId)
  }, [onClose, animationDuration, maxHeight])

  /** 居中弹窗：进入时自下而上 + 淡入 */
  const [centerEntered, setCenterEntered] = useState(false)
  useLayoutEffect(() => {
    if (!maxHeight) return
    if (!show) {
      setCenterEntered(false)
      return
    }
    if (closing) return
    setCenterEntered(false)
    const id0 = requestAnimationFrame(() => {
      requestAnimationFrame(() => setCenterEntered(true))
    })
    return () => cancelAnimationFrame(id0)
  }, [show, maxHeight, closing])

  /** 全屏：打开时双帧后再 fsSlideIn，保证有过渡起点 */
  useLayoutEffect(() => {
    if (maxHeight) return
    if (!show) {
      setFsSlideIn(false)
      return
    }
    if (closing) return
    setFsSlideIn(false)
    requestAnimationFrame(() => {
      requestAnimationFrame(() => setFsSlideIn(true))
    })
  }, [show, maxHeight, closing])

  useEffect(() => {
    const onTouchMove = (e: TouchEvent) => {
      if (!dragging.current && startY.current != null) {
        // 检查是否是滚动意图
        const sc = scrollRef.current
        if (sc && e.touches.length > 0 && startX.current != null) {
          const deltaX = Math.abs(e.touches[0].clientX - startX.current)
          const deltaY = e.touches[0].clientY - startY.current

          // 如果垂直移动大于水平移动，且是向下滚动，允许滚动
          if (deltaY > 0 && deltaY > deltaX) {
            isScrolling.current = true
            return // 不阻止默认滚动行为，让浏览器处理滚动
          }

          // 如果内容可以滚动且用户向上滚动，允许滚动
          if (deltaY < 0 && sc.scrollTop > 0) {
            isScrolling.current = true
            return
          }

          // 如果内容在顶部且用户向下拖拽超过一定距离，开始拖拽关闭
          if (sc.scrollTop === 0 && deltaY > 10 && deltaY > deltaX) {
            dragging.current = true
            currentY.current = 0
            if (panelRef.current) {
              panelRef.current.style.transition = ''
              panelRef.current.style.willChange = 'transform'
            }
            document.body.style.userSelect = 'none'
            if (e.cancelable) e.preventDefault()
          }
        }
        return
      }

      if (dragging.current) {
        if (e.cancelable) e.preventDefault()
        const y = e.touches[0].clientY
        if (startY.current == null) return
        currentY.current = Math.max(0, y - startY.current)
        if (panelRef.current) {
          panelRef.current.style.transform = `translateY(${currentY.current}px)`
        }
      }
    }
    const onPointerMove = (e: PointerEvent) => {
      if (!dragging.current && startY.current != null) {
        // 检查是否是滚动意图
        const sc = scrollRef.current
        if (sc && startX.current != null) {
          const deltaX = Math.abs(e.clientX - startX.current)
          const deltaY = e.clientY - startY.current

          // 如果垂直移动大于水平移动，且是向下滚动，允许滚动
          if (deltaY > 0 && deltaY > deltaX) {
            isScrolling.current = true
            return // 不阻止默认滚动行为
          }

          // 如果内容可以滚动且用户向上滚动，允许滚动
          if (deltaY < 0 && sc.scrollTop > 0) {
            isScrolling.current = true
            return
          }

          // 如果内容在顶部且用户向下拖拽超过一定距离，开始拖拽关闭
          if (sc.scrollTop === 0 && deltaY > 10 && deltaY > deltaX) {
            dragging.current = true
            currentY.current = 0
            if (panelRef.current) {
              panelRef.current.style.transition = ''
              panelRef.current.style.willChange = 'transform'
            }
            document.body.style.userSelect = 'none'
            e.preventDefault()
          }
        }
        return
      }

      if (dragging.current) {
        e.preventDefault()
        const y = e.clientY
        if (startY.current == null) return
        currentY.current = Math.max(0, y - startY.current)
        if (panelRef.current) {
          panelRef.current.style.transform = `translateY(${currentY.current}px)`
        }
      }
    }
    const onMoveEnd = () => {
      if (isScrolling.current) {
        // 如果是滚动，重置状态
        isScrolling.current = false
        startY.current = null
        startX.current = null
        return
      }

      if (!dragging.current) return
      dragging.current = false
      // 关闭阈值固定 100px，保证一致的拖拽体验
      const threshold = 100
      if (currentY.current > threshold) {
        // 使用最新的 handleClose 函数
        handleClose()
      } else {
        if (panelRef.current) {
          panelRef.current.style.transition = `transform 0.3s ease-out`
          panelRef.current.style.transform = `translateY(0)`
          setTimeout(() => {
            if (panelRef.current) panelRef.current.style.transition = ''
          }, 310)
        }
      }
      startY.current = null
      startX.current = null
      currentY.current = 0
      if (panelRef.current) panelRef.current.style.willChange = ''
      document.body.style.userSelect = ''
    }
    document.addEventListener('touchmove', onTouchMove, { passive: false })
    document.addEventListener('pointermove', onPointerMove)
    document.addEventListener('touchend', onMoveEnd)
    document.addEventListener('pointerup', onMoveEnd)
    return () => {
      document.removeEventListener('touchmove', onTouchMove)
      document.removeEventListener('pointermove', onPointerMove)
      document.removeEventListener('touchend', onMoveEnd)
      document.removeEventListener('pointerup', onMoveEnd)
    }
  }, [handleClose])

  const isInteractiveTarget = (el: HTMLElement | null): boolean => {
    if (!el) return false
    const interactiveTags = ['INPUT', 'TEXTAREA', 'SELECT', 'BUTTON', 'A']
    if (interactiveTags.includes(el.tagName)) return true
    const contentEditable = (el as HTMLElement).getAttribute('contenteditable')
    if (contentEditable === 'true') return true
    return false
  }

  const canStartDrag = (e: React.TouchEvent | React.PointerEvent) => {
    const target = e.target as HTMLElement
    // 检查是否点击在拖拽手柄上
    const isDragHandle = target.closest('.drag-handle')

    // 如果是交互元素（按钮等），且不在拖拽手柄上，不触发拖拽
    if (isInteractiveTarget(target) && !isDragHandle) return false

    const sc = scrollRef.current
    if (sc && sc.scrollTop > 0 && !isDragHandle) return false

    // 记录初始触摸点位置，用于判断滚动方向
    if ('touches' in e && e.touches.length > 0) {
      startX.current = e.touches[0].clientX
    } else if ('clientX' in e) {
      startX.current = e.clientX
    }

    return true
  }

  const onHandleStart = (e: React.TouchEvent | React.PointerEvent) => {
    const target = e.target as HTMLElement
    // 检查是否点击在拖拽手柄上
    const isDragHandle = target.closest('.drag-handle')

    // 如果是拖拽手柄，直接允许拖拽
    if (isDragHandle) {
      // 重置滚动状态
      isScrolling.current = false

      const isTouch = 'touches' in e
      if (isTouch) {
        const te = e as React.TouchEvent
        startY.current = te.touches[0].clientY
        startX.current = te.touches[0].clientX
      } else {
        const pe = e as React.PointerEvent
        startY.current = pe.clientY
        startX.current = pe.clientX
      }

      // 拖拽手柄上立即开始拖拽
      dragging.current = true
      currentY.current = 0
      if (panelRef.current) {
        panelRef.current.style.transition = ''
        panelRef.current.style.willChange = 'transform'
      }
      document.body.style.userSelect = 'none'
      return
    }

    // 非拖拽手柄区域，使用原有逻辑
    if (!canStartDrag(e)) return

    // 重置滚动状态
    isScrolling.current = false

    const isTouch = 'touches' in e
    if (isTouch) {
      const te = e as React.TouchEvent
      // 不preventDefault，让浏览器先处理滚动
      startY.current = te.touches[0].clientY
    } else {
      const pe = e as React.PointerEvent
      startY.current = pe.clientY
    }

    // 对于触摸事件，延迟判断是否是拖拽，让滚动优先
    if (isTouch) {
      // 不立即设置dragging，让浏览器先尝试滚动
      // 如果用户真的想拖拽关闭，会在move事件中检测到
    } else {
      // 对于鼠标事件，可以立即设置dragging
      dragging.current = true
      currentY.current = 0
      if (panelRef.current) {
        panelRef.current.style.transition = ''
        panelRef.current.style.willChange = 'transform'
      }
      document.body.style.userSelect = 'none'
    }
  }

  if (!show && !closing) return null

  return (
    <>
      {maxHeight ? (
        // 居中显示的小弹窗
        <>
          {mask?.visible && (
            <div
              style={{ 
                zIndex: maskZ,
                opacity: closing ? 0 : 1,
                transition: `opacity ${animationDuration}ms ease-out`,
                pointerEvents: closing ? 'none' : 'auto'
              }}
              className="fixed inset-0"
              onClick={mask?.clickable ? handleClose : undefined}
            >
              {/* 遮罩层覆盖 app 主容器（max-w-sm mx-auto） */}
              <div className="w-full max-w-sm mx-auto h-full bg-black/50" />
            </div>
          )}
          <div 
            style={{ zIndex: zIndex + 1 }}
            className="fixed inset-0 flex items-center justify-center px-4 pointer-events-auto" 
            onClick={handleClose}
          >
            <div
              ref={panelRef}
              className={`w-full ${maxWidth} flex flex-col rounded-2xl bg-gray-50 shadow-2xl pointer-events-auto relative`}
              style={{
                maxHeight: typeof maxHeight === 'string' ? maxHeight : `${maxHeight}px`,
                transform: closing
                  ? 'scale(0.95) translateY(0)'
                  : centerEntered
                    ? 'scale(1) translateY(0)'
                    : 'scale(0.98) translateY(24px)',
                opacity: closing ? 0 : centerEntered ? 1 : 0,
                transition: `transform ${animationDuration}ms ease-out, opacity ${animationDuration}ms ease-out`,
              }}
              onClick={(e) => e.stopPropagation()}
            >
            {header}
            <div 
              ref={scrollRef} 
              className="overflow-y-auto"
              style={{ 
                maxHeight: typeof maxHeight === 'string' ? maxHeight : `${maxHeight}px`
              }}
            >
              {children}
            </div>
            {footer}
            </div>
          </div>
        </>
      ) : (
        // 底部弹出的全屏弹窗
        <>
          {mask?.visible && (
            <div
              style={{ 
                zIndex: maskZ,
                opacity: closing ? 0 : 1,
                transition: `opacity ${animationDuration}ms ease-out`,
                pointerEvents: closing ? 'none' : 'auto'
              }}
              className="fixed inset-0 bg-black/50"
              onClick={mask?.clickable ? handleClose : undefined}
            />
          )}
          <div 
            style={{ zIndex }}
            className="fixed inset-0 pointer-events-none"
          >
            {/* 与 AppHeader 实测高度缝合；兜底与 constants/appLayout 一致 */}
            <div
              className="absolute left-0 right-0 max-w-sm mx-auto w-full"
              style={{
                top: APP_HEADER_HEIGHT_CSS,
                height: FULL_PANEL_HEIGHT_MINUS_HEADER_CSS,
              }}
            >
              <div
                ref={panelRef}
                className="w-full max-w-sm mx-auto flex flex-col rounded-t-2xl bg-gray-50 pointer-events-auto h-full"
                style={{
                  paddingTop: '10px',
                  paddingBottom: 'env(safe-area-inset-bottom)',
                  transform: fsSlideIn ? 'translateY(0)' : 'translateY(100%)',
                  transition: `transform ${animationDuration}ms ease-out`,
                }}
              >
                <div
                  className="drag-handle w-full select-none py-4"
                  onTouchStart={onHandleStart}
                  onPointerDown={onHandleStart}
                >
                  <div className="mx-auto h-1.5 w-10 rounded-full bg-gray-300" />
                </div>
                {header}
                <div 
                  ref={scrollRef} 
                  className="flex-1 overflow-y-auto"
                  style={{ 
                    paddingTop: '4px',
                    touchAction: 'pan-y'
                  }}
                  onTouchStart={onHandleStart}
                  onPointerDown={onHandleStart}
                >
                  {children}
                </div>
                {footer}
              </div>
            </div>
          </div>
        </>
      )}
    </>
  )
}

import React, { useEffect, useRef, useState, useCallback } from 'react'

type DrawerScreenProps = {
  show: boolean
  onClose: () => void
  children: React.ReactNode
  showMask?: boolean
  maskClickable?: boolean
  showDragHandle?: boolean
}

export function DrawerScreen({ 
  show, 
  onClose, 
  children, 
  showMask = false,
  maskClickable = true,
  showDragHandle = true
}: DrawerScreenProps) {
  const [isVisible, setIsVisible] = useState(false)
  const [isDragging, setIsDragging] = useState(false)
  const [startX, setStartX] = useState(0)
  const [translateX, setTranslateX] = useState(0)
  const containerRef = useRef<HTMLDivElement>(null)
  const drawerRef = useRef<HTMLDivElement>(null)

  // Trigger slide-in animation when show becomes true
  useEffect(() => {
    if (show) {
      setTranslateX(0)
      // Use rAF to ensure first paint is off-screen, then animate in
      const timer = requestAnimationFrame(() => {
        setIsVisible(true)
      })
      return () => cancelAnimationFrame(timer)
    } else {
      setIsVisible(false)
      setTranslateX(0) // 🔥 修复：重置位置
    }
  }, [show])

  // Handle close with animation
  const handleClose = useCallback(() => {
    setIsVisible(false)
    setTimeout(() => {
      onClose()
      setTranslateX(0)
    }, 300)
  }, [onClose])

  // Handle drag start
  const handleDragStart = useCallback((clientX: number) => {
    setIsDragging(true)
    setStartX(clientX)
    if (drawerRef.current) {
      drawerRef.current.style.transition = 'none'
    }
  }, [])

  // Handle drag move
  const handleDragMove = useCallback((clientX: number) => {
    if (!isDragging) return

    const deltaX = clientX - startX
    // Only allow dragging to the right (positive deltaX)
    const newTranslateX = Math.max(0, deltaX)
    setTranslateX(newTranslateX)
  }, [isDragging, startX])

  // Handle drag end
  const handleDragEnd = useCallback(() => {
    if (!isDragging) return

    setIsDragging(false)

    if (drawerRef.current) {
      drawerRef.current.style.transition = 'transform 0.3s ease-out'
    }

    // If dragged more than 100px to the right, close the drawer
    if (translateX > 100) {
      handleClose()
    } else {
      setTranslateX(0)
    }
  }, [isDragging, translateX, handleClose])

  // Mouse events
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault()
    handleDragStart(e.clientX)
  }, [handleDragStart])

  const handleMouseMove = useCallback((e: MouseEvent) => {
    handleDragMove(e.clientX)
  }, [handleDragMove])

  const handleMouseUp = useCallback(() => {
    handleDragEnd()
  }, [handleDragEnd])

  // Touch events
  const handleTouchStart = useCallback((e: React.TouchEvent) => {
    handleDragStart(e.touches[0].clientX)
  }, [handleDragStart])

  const handleTouchMove = useCallback((e: TouchEvent) => {
    if (e.touches.length > 0) {
      handleDragMove(e.touches[0].clientX)
    }
  }, [handleDragMove])

  const handleTouchEnd = useCallback(() => {
    handleDragEnd()
  }, [handleDragEnd])

  // Add global event listeners for dragging
  useEffect(() => {
    if (isDragging) {
      document.addEventListener('mousemove', handleMouseMove)
      document.addEventListener('mouseup', handleMouseUp)
      document.addEventListener('touchmove', handleTouchMove, { passive: false })
      document.addEventListener('touchend', handleTouchEnd)

      return () => {
        document.removeEventListener('mousemove', handleMouseMove)
        document.removeEventListener('mouseup', handleMouseUp)
        document.removeEventListener('touchmove', handleTouchMove)
        document.removeEventListener('touchend', handleTouchEnd)
      }
    }
  }, [isDragging, handleMouseMove, handleMouseUp, handleTouchMove, handleTouchEnd])

  if (!show) {
    return null;
  }

  return (
    <div className="fixed inset-0 z-[80] pointer-events-none">
      {/* Drawer Container - 使用 app 默认容器宽度，居中显示 */}
      <div className="absolute inset-0 flex justify-center pointer-events-none">
        <div className="relative w-full max-w-sm h-full pointer-events-auto overflow-hidden">
          {/* Mask - 限制在 app 默认容器宽度内 */}
          {showMask && (
            <div 
              className={`absolute inset-0 bg-black/30 transition-opacity duration-300 pointer-events-auto ${
                isVisible ? 'opacity-100' : 'opacity-0'
              }`}
              onClick={maskClickable ? handleClose : undefined}
              style={{ pointerEvents: isVisible ? 'auto' : 'none' }}
            />
          )}
          {/* Drawer - 从容器右侧滑入 */}
          <div
            ref={drawerRef}
            className={`absolute inset-y-0 right-0 w-full bg-white flex flex-col transition-transform duration-300 ease-out shadow-2xl ${
              isVisible ? 'translate-x-0' : 'translate-x-full'
            }`}
            style={isDragging ? {
              transform: `translateX(${translateX}px)`,
              transitionProperty: 'none'
            } : {}}
          >
            {/* Drag Handle */}
            {showDragHandle && (
              <div 
                className="flex justify-center py-2 cursor-grab active:cursor-grabbing select-none"
                onMouseDown={handleMouseDown}
                onTouchStart={handleTouchStart}
              >
                <div className="w-10 h-1 bg-gray-300 rounded-full" />
              </div>
            )}

            {/* Content */}
            <div className="flex-1 overflow-hidden flex flex-col">
              {children}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

import React from 'react';
import { Sparkles } from 'lucide-react';

export type RecordSource = 'manual' | 'ai' | 'device' | 'onboarding' | 'guide';

interface RecordSourceTagProps {
  source: RecordSource;
  deviceName?: string;
  className?: string;
}

/**
 * 通用数据来源标签组件
 * 支持：手动记录、AI记录、设备记录、引导记录
 */
export const RecordSourceTag: React.FC<RecordSourceTagProps> = ({ 
  source, 
  deviceName,
  className = ''
}) => {
  const getTagConfig = () => {
    switch (source) {
      case 'manual':
        return {
          text: '手动记录',
          bg: 'bg-blue-100',
          textColor: 'text-blue-700',
          icon: null
        };
      case 'ai':
        return {
          text: 'AI记录',
          bg: 'bg-purple-100',
          textColor: 'text-purple-700',
          icon: null
        };
      case 'device':
        return {
          text: deviceName ? `${deviceName}记录` : '设备记录',
          bg: 'bg-green-100',
          textColor: 'text-green-700',
          icon: null
        };
      case 'onboarding':
      case 'guide':
        return {
          text: '引导记录',
          bg: 'bg-emerald-100',
          textColor: 'text-emerald-700',
          icon: <Sparkles className="w-3 h-3" />
        };
      default:
        return {
          text: '未知来源',
          bg: 'bg-gray-100',
          textColor: 'text-gray-700',
          icon: null
        };
    }
  };

  const config = getTagConfig();

  // 如果 className 中包含 'relative' 或 'inline'，则不使用绝对定位
  const isAbsolute = !className.includes('relative') && !className.includes('inline');
  const positionClass = isAbsolute ? 'absolute top-2 right-2' : '';

  return (
    <div className={`${positionClass} flex items-center space-x-1 ${config.bg} ${config.textColor} px-2 py-1 rounded-full text-xs font-medium ${className}`}>
      {config.icon}
      <span>{config.text}</span>
    </div>
  );
};

/**
 * 从记录的notes字段中提取数据来源
 * @param notes 记录的notes字段
 * @param defaultToManual 如果notes为空，是否默认返回'manual'（用于体重等手动录入的记录）
 * @returns RecordSource | null
 */
export function extractRecordSource(notes?: string, defaultToManual: boolean = false): RecordSource | null {
  // 如果notes为空且defaultToManual为true，默认返回'manual'
  if (!notes) {
    return defaultToManual ? 'manual' : null;
  }

  if (notes.includes('初始体重记录') || notes.includes('引导流程') || notes.includes('引导记录')) {
    return 'guide';
  }
  if (notes.includes('手动记录') || notes.includes('手动')) {
    return 'manual';
  }
  if (notes.includes('AI记录') || notes.includes('AI创建') || notes.includes('AI')) {
    return 'ai';
  }
  // 设备记录通常会有设备名称，如"Apple Watch记录"、"小米手环记录"等
  if (notes.includes('记录') && !notes.includes('手动') && !notes.includes('AI') && !notes.includes('引导')) {
    // 尝试提取设备名称
    const deviceMatch = notes.match(/(.+?)记录/);
    if (deviceMatch && deviceMatch[1]) {
      return 'device';
    }
  }

  // 如果notes不为空但没有匹配到任何来源，且defaultToManual为true，默认返回'manual'
  return defaultToManual ? 'manual' : null;
}

/**
 * 从记录的notes字段中提取设备名称
 * @param notes 记录的notes字段
 * @returns 设备名称或null
 */
export function extractDeviceName(notes?: string): string | null {
  if (!notes) return null;

  // 匹配"XX设备记录"或"XX记录"格式
  const deviceMatch = notes.match(/(.+?)(?:设备)?记录/);
  if (deviceMatch && deviceMatch[1] && 
      !deviceMatch[1].includes('手动') && 
      !deviceMatch[1].includes('AI') && 
      !deviceMatch[1].includes('引导')) {
    return deviceMatch[1].trim();
  }

  return null;
}

