/* eslint-disable @typescript-eslint/no-unused-vars, @typescript-eslint/no-explicit-any, no-case-declarations, react-refresh/only-export-components */
import React, { createContext, useContext, useReducer, ReactNode } from 'react';
import { QuickEntryData } from '../components/QuickEntryCard';
import { VoicePlaybackProvider } from './VoicePlaybackContext';
import { useChatLogic } from '../hooks/useChatLogic';
import { DEFAULT_AI_COMPANION_NAME } from '../services/aiSettingsService';
import { sortMessagesByTimestamp } from '../utils/chatHelpers';

/** 便签卡片类型：每条消息独立，2秒后展示 */
export type AbilityCardType = 'delivery' | 'meals' | 'supplements' | 'report';

export interface ChatMessage {
  id: string;
  /** 前端本地稳定键：用于避免 tempId -> dbId 替换时闪动重挂载 */
  clientId?: string;
  type: 'user' | 'ai' | 'quickEntry' | 'feedback';
  content: string;
  timestamp: string;
  createdAt?: string; // 数据库的 created_at，用于精确排序
  emotion?: string;
  emotionEmoji?: string;
  quickEntryData?: QuickEntryData;
  isQuickEntryConfirmed?: boolean;
  /** 便签卡片类型：有则表示为便签触发的消息 */
  abilityCardType?: AbilityCardType;
  /** 便签卡片是否已展示（点击后2秒变为 true） */
  abilityCardVisible?: boolean;
}

export interface ChatState {
  messages: ChatMessage[];
  inputText: string;
  showEmotionAnimation: boolean;
  animatingEmoji: string;
  isLoadingAnalysis: boolean;
  isSendingMessage: boolean;
  isLoadingHistory: boolean;
  hasMoreMessages: boolean;
  conversationId: string | undefined;
  userGender: string;
  aiName: string;
  ownerName: string;
  todayCardCount: number;
  showClearDialog: boolean;
  showAlert: boolean;
  alertMessage: string;
  alertType: 'success' | 'error' | 'warning' | 'info';
}

export type ChatAction =
  | { type: 'SET_MESSAGES'; payload: ChatMessage[] }
  | { type: 'ADD_MESSAGE'; payload: ChatMessage }
  | { type: 'UPDATE_MESSAGE'; payload: { id: string; message: Partial<ChatMessage> } }
  | { type: 'SET_INPUT_TEXT'; payload: string }
  | { type: 'SET_SHOW_EMOTION_ANIMATION'; payload: boolean }
  | { type: 'SET_ANIMATING_EMOJI'; payload: string }
  | { type: 'SET_IS_LOADING_ANALYSIS'; payload: boolean }
  | { type: 'SET_IS_SENDING_MESSAGE'; payload: boolean }
  | { type: 'SET_IS_LOADING_HISTORY'; payload: boolean }
  | { type: 'SET_HAS_MORE_MESSAGES'; payload: boolean }
  | { type: 'APPEND_MESSAGES'; payload: ChatMessage[] }
  | { type: 'SET_CONVERSATION_ID'; payload: string | undefined }
  | { type: 'SET_USER_GENDER'; payload: string }
  | { type: 'SET_AI_NAME'; payload: string }
  | { type: 'SET_OWNER_NAME'; payload: string }
  | { type: 'SET_TODAY_CARD_COUNT'; payload: number }
  | { type: 'SET_SHOW_CLEAR_DIALOG'; payload: boolean }
  | { type: 'SET_SHOW_ALERT'; payload: boolean }
  | { type: 'SET_ALERT_MESSAGE'; payload: string }
  | { type: 'SET_ALERT_TYPE'; payload: 'success' | 'error' | 'warning' | 'info' };

interface ChatContextType extends ChatState {
  setInputText: (text: string) => void;
  handleSendMessage: (overrideText?: string) => Promise<void>;
  /** 便签点击：先插入消息，2秒后展示卡片；每条消息独立 */
  addAbilityCardMessage: (label: string, cardType: AbilityCardType) => void;
  /** 便签卡片关闭：隐藏该消息下的卡片 */
  handleAbilityCardClose: (messageId: string) => void;
  handleQuickEntryConfirmFromMessage: (messageId: string, data: QuickEntryData) => Promise<void>;
  handleQuickEntryDeleteFromMessage: (messageId: string) => Promise<void>;
  handleQuickAction: (action: string) => Promise<void>;
  handleLoadMoreMessages: () => Promise<void>;
  handleOpenClearDialog: () => void;
  handleCloseClearDialog: () => void;
  handleClearToday: () => Promise<void>;
  handleClearAll: () => Promise<void>;
  handleCloseAlert: () => void;
  showChatAlert: (message: string, type: 'success' | 'error' | 'warning' | 'info') => void;
  addAIMessage: (content: string) => Promise<void>;
  /** 添加反馈通知消息（独立 UI，区别于普通对话） */
  addFeedbackMessage: (content: string) => Promise<void>;
  cancelAiGeneration: () => void;
}

const ChatContext = createContext<ChatContextType | undefined>(undefined);

const initialState: ChatState = {
  messages: [],
  inputText: '',
  showEmotionAnimation: false,
  animatingEmoji: '',
  isLoadingAnalysis: false,
  isSendingMessage: false,
  isLoadingHistory: false,
  hasMoreMessages: true,
  conversationId: undefined,
  userGender: '',
  aiName: DEFAULT_AI_COMPANION_NAME,
  ownerName: 'owner',
  todayCardCount: 0,
  showClearDialog: false,
  showAlert: false,
  alertMessage: '',
  alertType: 'warning'
};


function chatReducer(state: ChatState, action: ChatAction): ChatState {
  switch (action.type) {
    case 'SET_MESSAGES':
      return { ...state, messages: sortMessagesByTimestamp(action.payload) };
    case 'ADD_MESSAGE':
      // 🔥 修复：添加消息前先检查是否已存在（基于ID去重）
      const messageExists = state.messages.some(msg => msg.id === action.payload.id);
      if (messageExists) {
        console.warn(`⚠️ [ChatReducer] 消息已存在，跳过添加: ${action.payload.id}`);
        return state;
      }
      // 添加消息后按时间戳排序，确保顺序正确
      const newMessages = [...state.messages, action.payload];
      return { ...state, messages: sortMessagesByTimestamp(newMessages) };
    case 'APPEND_MESSAGES':
      // 🔥 修复：追加消息前先过滤掉已存在的消息（基于ID去重）
      const existingIds = new Set(state.messages.map(msg => msg.id));
      const newMessagesToAppend = action.payload.filter(msg => {
        if (existingIds.has(msg.id)) {
          console.warn(`⚠️ [ChatReducer] 消息已存在，跳过追加: ${msg.id}`);
          return false;
        }
        return true;
      });
      const appendedMessages = [...state.messages, ...newMessagesToAppend];
      return { ...state, messages: sortMessagesByTimestamp(appendedMessages) };
    case 'UPDATE_MESSAGE':
      // 更新消息后需要重新排序，因为createdAt可能已更新
      // 如果ID也更新了，需要先找到旧ID的消息，然后更新为新ID，并移除可能重复的新ID消息
      const newId = action.payload.message.id;
      const updatedMessages = state.messages
        .filter(msg => {
          // 如果新ID已经存在且不是当前要更新的消息，移除它（避免重复）
          if (newId && msg.id === newId && msg.id !== action.payload.id) {
            return false;
          }
          return true;
        })
        .map(msg => {
          // 如果消息的ID匹配，更新它
          if (msg.id === action.payload.id) {
            return { ...msg, ...action.payload.message };
          }
          return msg;
        });

      return {
        ...state,
        messages: sortMessagesByTimestamp(updatedMessages)
      };
    case 'SET_INPUT_TEXT':
      return { ...state, inputText: action.payload };
    case 'SET_SHOW_EMOTION_ANIMATION':
      return { ...state, showEmotionAnimation: action.payload };
    case 'SET_ANIMATING_EMOJI':
      return { ...state, animatingEmoji: action.payload };
    case 'SET_IS_LOADING_ANALYSIS':
      return { ...state, isLoadingAnalysis: action.payload };
    case 'SET_IS_SENDING_MESSAGE':
      return { ...state, isSendingMessage: action.payload };
    case 'SET_IS_LOADING_HISTORY':
      return { ...state, isLoadingHistory: action.payload };
    case 'SET_HAS_MORE_MESSAGES':
      return { ...state, hasMoreMessages: action.payload };
    case 'SET_CONVERSATION_ID':
      return { ...state, conversationId: action.payload };
    case 'SET_USER_GENDER':
      return { ...state, userGender: action.payload };
    case 'SET_AI_NAME':
      return { ...state, aiName: action.payload };
    case 'SET_OWNER_NAME':
      return { ...state, ownerName: action.payload };
    case 'SET_TODAY_CARD_COUNT':
      return { ...state, todayCardCount: action.payload };
    case 'SET_SHOW_CLEAR_DIALOG':
      return { ...state, showClearDialog: action.payload };
    case 'SET_SHOW_ALERT':
      return { ...state, showAlert: action.payload };
    case 'SET_ALERT_MESSAGE':
      return { ...state, alertMessage: action.payload };
    case 'SET_ALERT_TYPE':
      return { ...state, alertType: action.payload };
    default:
      return state;
  }
}


export const ChatProvider: React.FC<{
  children: ReactNode;
  chatSelectedDate?: Date | null;
}> = ({ children, chatSelectedDate = null }) => {
  const [state, dispatch] = useReducer(chatReducer, initialState);

  const handlers = useChatLogic({ state, dispatch, chatSelectedDate });

  const value: ChatContextType = {
    ...state,
    ...handlers
  };

  return (
    <ChatContext.Provider value={value}>
      <VoicePlaybackProvider>{children}</VoicePlaybackProvider>
    </ChatContext.Provider>
  );
};

export const useChatContext = () => {
  const context = useContext(ChatContext);
  if (context === undefined) {
    throw new Error('useChatContext must be used within a ChatProvider');
  }
  return context;
};

/** 可选版本：在 ChatProvider 外使用时返回 null，不抛错（用于 TopSummaryRow 等可能独立渲染的场景） */
export const useOptionalChatContext = () => useContext(ChatContext) ?? null;

import React, { createContext, useCallback, useContext, useMemo, useRef, useState } from "react";
import { pickPreferredChineseVoice } from "../utils/ttsVoice";

interface VoicePlaybackContextValue {
  speakingMessageId: string | null;
  isSpeakingPaused: boolean;
  speakMessage: (refKey: string, text: string) => void;
  stopPlayback: () => void;
}

const VoicePlaybackContext = createContext<VoicePlaybackContextValue | undefined>(undefined);

/** cancel() 触发的 error，用于区分「用户点暂停」与真错误 */
function isCancelLikeError(code: string): boolean {
  return code === "interrupted" || code === "canceled" || code === "cancelled";
}

/**
 * 浏览器对 `speechSynthesis.pause/resume` 支持很差，表现为一点击就 cancel 重播。
 * 策略：用户暂停时 `cancel()`，用 `onboundary` 记录已读到的字符位置，续播时对全文 `slice(offset)` 再 speak。
 */
export function VoicePlaybackProvider({ children }: { children: React.ReactNode }) {
  const [speakingMessageId, setSpeakingMessageId] = useState<string | null>(null);
  const [isSpeakingPaused, setIsSpeakingPaused] = useState(false);

  /** 单调递增，用于作废过期的 onend/onerror；一次「会话」内保持不变（含暂停/续播） */
  const speakGenRef = useRef(0);
  /** 当前 TTS 会话 id，与 speakGenRef 同步，0 表示无会话 */
  const currentSessionSidRef = useRef(0);
  const activeUtteranceKeyRef = useRef<string | null>(null);
  const hasQueuedUtteranceRef = useRef(false);
  const userPausedRef = useRef(false);
  const fullTextRef = useRef("");
  /** 下一段 utterance 从 fullText 的哪一字开始读 */
  const startOffsetRef = useRef(0);
  /** 最近一次 boundary 在全文中的绝对下标（用于暂停时截取） */
  const lastBoundaryAbsoluteRef = useRef(0);
  const intentionalSlicePauseRef = useRef(false);

  const resetSpeakingState = useCallback(() => {
    speakGenRef.current += 1;
    currentSessionSidRef.current = 0;
    activeUtteranceKeyRef.current = null;
    hasQueuedUtteranceRef.current = false;
    userPausedRef.current = false;
    intentionalSlicePauseRef.current = false;
    fullTextRef.current = "";
    startOffsetRef.current = 0;
    lastBoundaryAbsoluteRef.current = 0;
    setSpeakingMessageId(null);
    setIsSpeakingPaused(false);
  }, []);

  const stopPlayback = useCallback(() => {
    if (typeof window !== "undefined" && window.speechSynthesis) {
      intentionalSlicePauseRef.current = false;
      window.speechSynthesis.cancel();
    }
    resetSpeakingState();
  }, [resetSpeakingState]);

  const speakMessage = useCallback(
    (refKey: string, text: string) => {
      if (typeof window === "undefined" || !text.trim()) return;
      const synth = window.speechSynthesis;
      const trimmed = text.trim();

      const finishThisSession = () => {
        const sid = currentSessionSidRef.current;
        if (sid === 0 || speakGenRef.current !== sid) return;
        speakGenRef.current += 1;
        currentSessionSidRef.current = 0;
        hasQueuedUtteranceRef.current = false;
        userPausedRef.current = false;
        intentionalSlicePauseRef.current = false;
        activeUtteranceKeyRef.current = null;
        fullTextRef.current = "";
        startOffsetRef.current = 0;
        lastBoundaryAbsoluteRef.current = 0;
        setSpeakingMessageId(null);
        setIsSpeakingPaused(false);
      };

      const startSegment = (key: string) => {
        const sid = currentSessionSidRef.current;
        if (sid === 0 || speakGenRef.current !== sid) return;

        const from = startOffsetRef.current;
        const full = fullTextRef.current;
        if (from >= full.length) {
          finishThisSession();
          return;
        }
        const segment = full.slice(from);

        let started = false;
        let timeoutId: ReturnType<typeof setTimeout> | undefined;

        const run = () => {
          if (speakGenRef.current !== sid) return;
          if (started) return;
          started = true;
          synth.removeEventListener("voiceschanged", onVoices);
          if (timeoutId !== undefined) window.clearTimeout(timeoutId);
          if (speakGenRef.current !== sid) return;

          const u = new SpeechSynthesisUtterance(segment);
          u.lang = "zh-CN";
          const voice = pickPreferredChineseVoice();
          if (voice) u.voice = voice;
          u.rate = 0.9;
          u.pitch = 1.05;
          u.volume = 1;

          u.onboundary = (e) => {
            if (speakGenRef.current !== sid) return;
            lastBoundaryAbsoluteRef.current = from + e.charIndex;
          };

          u.onstart = () => {
            if (speakGenRef.current !== sid) return;
            setSpeakingMessageId(key);
            setIsSpeakingPaused(false);
          };

          const handleIntentionalPause = () => {
            intentionalSlicePauseRef.current = false;
            userPausedRef.current = true;
            setIsSpeakingPaused(true);
            startOffsetRef.current = Math.min(
              lastBoundaryAbsoluteRef.current,
              fullTextRef.current.length,
            );
          };

          u.onerror = (ev) => {
            if (speakGenRef.current !== sid) return;
            const code = (ev as SpeechSynthesisErrorEvent).error;
            if (intentionalSlicePauseRef.current && isCancelLikeError(code)) {
              handleIntentionalPause();
              return;
            }
            finishThisSession();
          };

          u.onend = () => {
            if (speakGenRef.current !== sid) return;
            if (intentionalSlicePauseRef.current) {
              handleIntentionalPause();
              return;
            }
            finishThisSession();
          };

          synth.speak(u);
        };

        const onVoices = () => run();

        if (synth.getVoices().length === 0) {
          synth.addEventListener("voiceschanged", onVoices);
          timeoutId = window.setTimeout(() => run(), 400);
        } else {
          run();
        }
      };

      // —— 同一条：暂停 / 续播 ——
      if (activeUtteranceKeyRef.current === refKey && hasQueuedUtteranceRef.current) {
        if (userPausedRef.current) {
          userPausedRef.current = false;
          setIsSpeakingPaused(false);
          startSegment(refKey);
          return;
        }

        intentionalSlicePauseRef.current = true;
        synth.cancel();
        return;
      }

      // —— 新会话（换条或重新点播放）——
      synth.cancel();
      speakGenRef.current += 1;
      const sid = speakGenRef.current;
      currentSessionSidRef.current = sid;

      activeUtteranceKeyRef.current = refKey;
      hasQueuedUtteranceRef.current = true;
      userPausedRef.current = false;
      intentionalSlicePauseRef.current = false;
      fullTextRef.current = trimmed;
      startOffsetRef.current = 0;
      lastBoundaryAbsoluteRef.current = 0;
      setSpeakingMessageId(refKey);
      setIsSpeakingPaused(false);

      startSegment(refKey);
    },
    [],
  );

  const value = useMemo(
    () => ({ speakingMessageId, isSpeakingPaused, speakMessage, stopPlayback }),
    [speakingMessageId, isSpeakingPaused, speakMessage, stopPlayback],
  );

  return <VoicePlaybackContext.Provider value={value}>{children}</VoicePlaybackContext.Provider>;
}

export function useVoicePlayback() {
  const ctx = useContext(VoicePlaybackContext);
  if (!ctx) {
    throw new Error("useVoicePlayback must be used within VoicePlaybackProvider");
  }
  return ctx;
}

/**
 * useAddressManagement - 地址管理逻辑Hook
 * 从AddDeliveryAddressPage.tsx中提取的地址管理逻辑
 * 符合架构规范：单一职责，减少组件复杂度
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { addressService, DeliveryAddress as DBDeliveryAddress } from '../services/addressService';
import { auth } from '../config/supabase';
import { getUserStorageItem, setUserStorageItem } from '../utils/userStorage';
import { DeliveryAddress } from '../components/delivery/AddressForm';

const ALL_MEALS = ['breakfast', 'lunch', 'dinner'];

function applyMealTypesExclusivity(
  addresses: DBDeliveryAddress[],
  currentAddressId: string,
  mealTypesToClaim: string[]
): DBDeliveryAddress[] {
  const toRemove = mealTypesToClaim.includes('all') ? ALL_MEALS : mealTypesToClaim;
  return addresses.map(addr => {
    if (addr.id === currentAddressId) return addr;
    const current = addr.default_meal_types;
    if (!current || !Array.isArray(current) || current.length === 0) return addr;
    const expanded = current.includes('all') ? [...ALL_MEALS] : [...current];
    const remaining = expanded.filter(t => !toRemove.includes(t));
    const newDefaultMealTypes: string[] | null = remaining.length > 0
      ? (remaining.length === 3 ? ['all'] : remaining)
      : null;
    return {
      ...addr,
      default_meal_types: newDefaultMealTypes,
      is_default: newDefaultMealTypes !== null && newDefaultMealTypes.length > 0
    };
  });
}

interface UseAddressManagementOptions {
  initialDeliveryAddressId?: string;
  onAlert?: (state: { show: boolean; type: 'success' | 'error' | 'warning' | 'info'; title: string; message: string }) => void;
}

export function useAddressManagement({
  initialDeliveryAddressId,
  onAlert,
}: UseAddressManagementOptions) {
  const queryClient = useQueryClient();
  const [savedAddresses, setSavedAddresses] = useState<DBDeliveryAddress[]>([]);
  const [selectedAddressId, setSelectedAddressId] = useState<string | null>(initialDeliveryAddressId || null);
  const [loading, setLoading] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [customTags, setCustomTags] = useState<string[]>([]);
  const isSavingRef = useRef<boolean>(false); // 🔥 修复：添加防重复提交的 ref

  const loadUserAndAddresses = useCallback(async () => {
    try {
      setLoading(true);
      const { user } = await auth.getCurrentUser();
      const effectiveUserId = user?.id || null;
      setUserId(effectiveUserId);

      const addresses = await addressService.fetchUserAddresses(effectiveUserId);
      setSavedAddresses(addresses);

      // Extract custom tags from existing addresses
      const existingCustomTags = addresses
        .map(addr => addr.tag || addr.label)
        .filter(tag => tag && !['家', '公司'].includes(tag));
      const uniqueCustomTags = Array.from(new Set(existingCustomTags));
      setCustomTags(uniqueCustomTags);

      // Load custom tags from localStorage
      try {
        const saved = await getUserStorageItem<string[]>('addressCustomTags');
        if (saved) {
          const mergedTags = Array.from(new Set([...uniqueCustomTags, ...saved]));
          setCustomTags(mergedTags);
        }
      } catch (error) {
        console.error('Failed to load custom tags:', error);
      }

      // Only set default address if no initial address was provided（优先 default_meal_types，兼容 is_default）
      if (!initialDeliveryAddressId) {
        const defaultAddress = addresses.find(addr =>
          addr.is_default || (addr.default_meal_types && addr.default_meal_types.length > 0)
        );
        if (defaultAddress) {
          setSelectedAddressId(defaultAddress.id);
        }
      }
    } catch (error) {
      console.error('Error loading addresses:', error);
      onAlert?.({
        show: true,
        type: 'error',
        title: '加载失败',
        message: '加载地址失败，请重试'
      });
    } finally {
      setLoading(false);
    }
  }, [initialDeliveryAddressId, onAlert]);

  const saveAddress = async (
    formData: DeliveryAddress,
    isDefaultAddress: boolean,
    defaultMealTypes: 'all' | string[],
    editingAddress: DBDeliveryAddress | null
  ): Promise<DBDeliveryAddress | null> => {
    // 🔥 修复：防止重复提交
    if (isSavingRef.current) {
      console.warn('⚠️ [useAddressManagement] Save already in progress, ignoring duplicate request');
      return null;
    }

    try {
      isSavingRef.current = true; // 🔥 修复：设置保存状态

      if (!userId) {
        onAlert?.({
          show: true,
          type: 'error',
          title: '保存失败',
          message: '用户未登录'
        });
        return null;
      }

      const defaultMealTypesValue = !isDefaultAddress ? null
        : defaultMealTypes === 'all' ? ['all'] : defaultMealTypes;

      if (editingAddress) {
        // Update existing address（按餐次排他：只更新当前地址，从其他地址清除重叠餐次）
        const updatedAddress = await addressService.updateAddress({
          id: editingAddress.id,
          expected_updated_at: editingAddress.updated_at,
          label: formData.tag,
          address: formData.address,
          door_number: formData.doorNumber,
          contact_name: formData.name,
          phone: formData.phone,
          gender: formData.gender,
          tag: formData.tag,
          default_meal_types: defaultMealTypesValue,
          is_default: !!defaultMealTypesValue,
          longitude: formData.longitude ?? null,
          latitude: formData.latitude ?? null,
        });

        if (updatedAddress) {
          let updatedAddresses = savedAddresses.map(addr =>
            addr.id === editingAddress.id ? updatedAddress : addr
          );

          if (isDefaultAddress && defaultMealTypesValue) {
            const toClaim = defaultMealTypesValue.includes('all') ? ['breakfast', 'lunch', 'dinner'] : defaultMealTypesValue;
            await addressService.clearMealTypesFromOtherAddresses(userId, updatedAddress.id, toClaim);
            updatedAddresses = applyMealTypesExclusivity(updatedAddresses, updatedAddress.id, toClaim);
          }

          setSavedAddresses(updatedAddresses);
          queryClient.invalidateQueries({ queryKey: ['delivery-addresses', userId] });
          queryClient.invalidateQueries({ queryKey: ['delivery-plan-card'] });
          queryClient.invalidateQueries({ queryKey: ['delivery-plan'] });

          const syncMeta = (updatedAddress as any).__syncMeta;
          if (syncMeta) {
            onAlert?.({
              show: true,
              type: 'success',
              title: '地址更新成功',
              message: `已同步 ${syncMeta.updatedCount} 个可修改餐次，跳过 ${syncMeta.skippedLockedCount} 个锁定餐次`
            });
          }
          return updatedAddress;
        }
      } else {
        // Create new address
        // 🔥 修复：createAddress 需要两个参数：userId 和 addressData
        const newAddress = await addressService.createAddress(userId, {
          label: formData.tag,
          address: formData.address,
          door_number: formData.doorNumber,
          contact_name: formData.name,
          phone: formData.phone,
          gender: formData.gender,
          tag: formData.tag,
          is_default: isDefaultAddress,
          default_meal_types: defaultMealTypesValue,
          longitude: formData.longitude ?? null,
          latitude: formData.latitude ?? null,
        });

        if (newAddress) {
          let updatedAddresses = [...savedAddresses, newAddress];

          if (isDefaultAddress && defaultMealTypesValue) {
            const toClaim = defaultMealTypesValue.includes('all') ? ['breakfast', 'lunch', 'dinner'] : defaultMealTypesValue;
            await addressService.clearMealTypesFromOtherAddresses(userId, newAddress.id, toClaim);
            updatedAddresses = applyMealTypesExclusivity(updatedAddresses, newAddress.id, toClaim);
          }

          setSavedAddresses(updatedAddresses);
          setSelectedAddressId(newAddress.id);
          queryClient.invalidateQueries({ queryKey: ['delivery-addresses', userId] });
          queryClient.invalidateQueries({ queryKey: ['delivery-plan-card'] });
          queryClient.invalidateQueries({ queryKey: ['delivery-plan'] });

          // Save custom tag if it's new
          const normalizedTag = String(formData.tag || '').trim();
          if (normalizedTag && !['家', '公司'].includes(normalizedTag)) {
            const updatedCustomTags = Array.from(new Set([...customTags.map(t => t.trim()), normalizedTag]));
            setCustomTags(updatedCustomTags);
            await setUserStorageItem('addressCustomTags', updatedCustomTags);
          }

          return newAddress;
        }
      }

      return null;
    } catch (error) {
      console.error('Error saving address:', error);
      const errorCode = error instanceof Error ? error.message : String(error);
      if (errorCode === 'ADDRESS_UPDATE_CONFLICT') {
        onAlert?.({
          show: true,
          type: 'warning',
          title: '地址已更新',
          message: '该地址刚被其他操作修改，请刷新后重试'
        });
        return null;
      }
      if (errorCode === 'ADDRESS_ALREADY_DELETED') {
        onAlert?.({
          show: true,
          type: 'warning',
          title: '地址不可用',
          message: '该地址已被删除，请刷新列表后重试'
        });
        return null;
      }
      onAlert?.({
        show: true,
        type: 'error',
        title: '保存失败',
        message: '保存地址失败，请重试'
      });
      return null;
    } finally {
      isSavingRef.current = false; // 🔥 修复：重置保存状态
    }
  };

  const deleteAddress = async (addressId: string): Promise<boolean> => {
    try {
      // Check if address is in use
      const { inUse, upcomingDeliveries } = await addressService.checkAddressInUse(addressId);

      if (inUse) {
        onAlert?.({
          show: true,
          type: 'warning',
          title: '无法删除',
          message: '该地址正在使用中，无法删除。'
        });
        return false;
      }

      const success = await addressService.deleteAddress(addressId);
      if (success) {
        setSavedAddresses(savedAddresses.filter(addr => addr.id !== addressId));
        if (selectedAddressId === addressId) {
          setSelectedAddressId(null);
        }
        queryClient.invalidateQueries({ queryKey: ['delivery-addresses', userId] });
        queryClient.invalidateQueries({ queryKey: ['delivery-plan-card'] });
        queryClient.invalidateQueries({ queryKey: ['delivery-plan'] });
        return true;
      }
      return false;
    } catch (error) {
      console.error('Error deleting address:', error);
      onAlert?.({
        show: true,
        type: 'error',
        title: '删除失败',
        message: '删除地址失败，请重试'
      });
      return false;
    }
  };

  useEffect(() => {
    loadUserAndAddresses();
  }, [loadUserAndAddresses]);

  return {
    savedAddresses,
    selectedAddressId,
    setSelectedAddressId,
    loading,
    userId,
    customTags,
    setCustomTags,
    saveAddress,
    deleteAddress,
    refreshAddresses: loadUserAndAddresses,
  };
}

/**
 * useAddressesQuery - 使用 React Query 的地址管理 Hook
 * 符合架构规范：组件 → Hook → Supabase (3层)
 */

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuth } from '../contexts/AuthContext';
import { addressService, DeliveryAddress, CreateAddressData, UpdateAddressData } from '../services/addressService';

export function useAddressesQuery() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  // 查询：使用 React Query
  const query = useQuery({
    queryKey: ['delivery-addresses', user?.id],
    queryFn: () => {
      if (!user?.id) return [];
      return addressService.fetchUserAddresses(user.id);
    },
    enabled: !!user?.id,
    staleTime: 5 * 60 * 1000, // 5分钟缓存
  });

  // 创建地址：使用 React Query Mutation
  const createMutation = useMutation({
    mutationFn: (addressData: CreateAddressData) => {
      if (!user?.id) throw new Error('User not authenticated');
      return addressService.createAddress(user.id, addressData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['delivery-addresses', user?.id] });
    },
  });

  // 更新地址：使用 React Query Mutation
  const updateMutation = useMutation({
    mutationFn: (addressData: UpdateAddressData) => addressService.updateAddress(addressData),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['delivery-addresses', user?.id] });
    },
  });

  // 删除地址：使用 React Query Mutation
  const deleteMutation = useMutation({
    mutationFn: (id: string) => addressService.deleteAddress(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['delivery-addresses', user?.id] });
    },
  });

  // 设置默认地址：使用 React Query Mutation
  const setDefaultMutation = useMutation({
    mutationFn: (addressId: string) => {
      if (!user?.id) throw new Error('User not authenticated');
      return addressService.setDefaultAddress(user.id, addressId);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['delivery-addresses', user?.id] });
    },
  });

  return {
    addresses: query.data || [],
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
    createAddress: createMutation.mutateAsync,
    updateAddress: updateMutation.mutateAsync,
    deleteAddress: deleteMutation.mutateAsync,
    setDefaultAddress: setDefaultMutation.mutateAsync,
    isCreating: createMutation.isPending,
    isUpdating: updateMutation.isPending,
    isDeleting: deleteMutation.isPending,
    isSettingDefault: setDefaultMutation.isPending,
    refresh: () => query.refetch(),
  };
}

/**
 * useAppPreferences - 用户偏好状态管理Hook
 * 从App.tsx中提取的用户偏好相关状态管理逻辑
 * 符合架构规范：提取状态管理逻辑，减少App.tsx复杂度
 */

import React, { useState, useEffect, useRef } from 'react';
import { getUserPreferences, saveUserPreferences } from '../services/userPreferencesService';
import { getUserStorageItem, setUserStorageItem } from '../utils/userStorage';

export interface AppPreferencesState {
  dashboardCardOrder: string[];
  hiddenDashboardCards: string[];
}

export interface AppPreferencesActions {
  setDashboardCardOrder: (order: string[]) => void;
  setHiddenDashboardCards: (cards: string[]) => void;
  updateCardOrder: (order: string[]) => void;
  updateHiddenCards: (cards: string[]) => void;
}

export function useAppPreferences(userId: string | null, isAuthenticated: boolean, authLoading: boolean) {
  // ✅ 初始值使用默认值，加载完成后会被实际值覆盖
  const [dashboardCardOrder, setDashboardCardOrder] = useState<string[]>(['calories', 'weight']);
  const [hiddenDashboardCards, setHiddenDashboardCards] = useState<string[]>([
    'nutrition', 'water', 'steps', 'exercise', 'measurements', 'emotion', 'sleep', 'bloodGlucose'
  ]);
  const [isLoading, setIsLoading] = useState(true); // 添加加载状态

  const hasLoadedPreferencesRef = useRef(false);
  const lastUserIdRef = useRef<string | null>(null);
  const isInitialMountRef = useRef(true);
  const lastSavedCardOrderRef = useRef<string>('');
  const lastSavedHiddenCardsRef = useRef<string>('');

  // 加载用户偏好配置（优先从数据库，备用localStorage）
  useEffect(() => {
    const loadUserPreferences = async () => {
      // 如果未认证或正在加载认证状态，使用默认值
      if (!isAuthenticated || authLoading) {
        if (!isAuthenticated && !authLoading) {
          // 未登录用户，尝试从 localStorage 加载
          try {
            const [cardOrder, hiddenCards] = await Promise.all([
              getUserStorageItem<string[]>('dashboardCardOrder'),
              getUserStorageItem<string[]>('hiddenDashboardCards')
            ]);

            let unauthenticatedCardOrder: string[];
            let unauthenticatedHiddenCards: string[];

            if (cardOrder && cardOrder.length > 0) {
              unauthenticatedCardOrder = Array.from(new Set(cardOrder));
              setDashboardCardOrder(unauthenticatedCardOrder);
            } else {
              // 未登录且没有保存的数据，使用默认值
              unauthenticatedCardOrder = ['calories', 'weight'];
              setDashboardCardOrder(unauthenticatedCardOrder);
            }

            if (hiddenCards && Array.isArray(hiddenCards)) {
              unauthenticatedHiddenCards = hiddenCards;
              setHiddenDashboardCards(unauthenticatedHiddenCards);
            } else {
              // 未登录且没有保存的数据，使用默认值
              unauthenticatedHiddenCards = ['nutrition', 'water', 'steps', 'exercise', 'measurements', 'emotion', 'sleep', 'bloodGlucose'];
              setHiddenDashboardCards(unauthenticatedHiddenCards);
            }

            // ✅ 立即更新 ref，防止自动保存覆盖刚加载的数据
            lastSavedCardOrderRef.current = JSON.stringify(unauthenticatedCardOrder);
            lastSavedHiddenCardsRef.current = JSON.stringify(unauthenticatedHiddenCards);

            setIsLoading(false);
          } catch (error) {
            console.error('[useAppPreferences] Error loading from localStorage for unauthenticated user:', error);
            // 出错时使用默认值
            const defaultCardOrder = ['calories', 'weight'];
            const defaultHiddenCards = ['nutrition', 'water', 'steps', 'exercise', 'measurements', 'emotion', 'sleep', 'bloodGlucose'];
            setDashboardCardOrder(defaultCardOrder);
            setHiddenDashboardCards(defaultHiddenCards);

            // ✅ 立即更新 ref
            lastSavedCardOrderRef.current = JSON.stringify(defaultCardOrder);
            lastSavedHiddenCardsRef.current = JSON.stringify(defaultHiddenCards);

            setIsLoading(false);
          }
        }
        return;
      }

      if (!userId) {
        setIsLoading(false);
        return;
      }

      // 如果用户切换了，重置加载标记
      if (lastUserIdRef.current !== userId) {
        hasLoadedPreferencesRef.current = false;
        lastUserIdRef.current = userId;
        setIsLoading(true);
      }

      // 防止重复加载
      if (hasLoadedPreferencesRef.current) {
        setIsLoading(false);
        return;
      }

      try {
        console.log('[useAppPreferences] 🔄 Loading dashboard preferences from database...', { userId });

        // 优先从数据库加载
        const dbPreferences = await getUserPreferences(userId);

        if (dbPreferences) {
          // 从数据库加载成功
          const uniqueCardOrder = Array.from(new Set(dbPreferences.dashboard_card_order || []));
          const hiddenCards = dbPreferences.hidden_dashboard_cards || [];

          // ✅ 确保至少有两个默认卡片（calories 和 weight）
          if (uniqueCardOrder.length === 0) {
            uniqueCardOrder.push('calories', 'weight');
          } else if (!uniqueCardOrder.includes('calories')) {
            uniqueCardOrder.unshift('calories');
          } else if (!uniqueCardOrder.includes('weight')) {
            const caloriesIndex = uniqueCardOrder.indexOf('calories');
            uniqueCardOrder.splice(caloriesIndex + 1, 0, 'weight');
          }

          setDashboardCardOrder(uniqueCardOrder);
          setHiddenDashboardCards(hiddenCards);

          // ✅ 立即更新 ref，防止自动保存覆盖刚加载的数据
          lastSavedCardOrderRef.current = JSON.stringify(uniqueCardOrder);
          lastSavedHiddenCardsRef.current = JSON.stringify(hiddenCards);

          // 同步到localStorage作为缓存
          await Promise.all([
            setUserStorageItem('dashboardCardOrder', uniqueCardOrder),
            setUserStorageItem('hiddenDashboardCards', hiddenCards)
          ]);

          console.log('[useAppPreferences] ✅ Loaded preferences from database:', {
            cardOrder: uniqueCardOrder,
            hiddenCards: hiddenCards,
            cardOrderLength: uniqueCardOrder.length,
            hiddenCardsLength: hiddenCards.length
          });

          hasLoadedPreferencesRef.current = true;
          setIsLoading(false);
          return;
        }

        // 数据库没有，尝试从localStorage加载
        console.log('[useAppPreferences] ⚠️ No database preferences, loading from localStorage...');
        const [cardOrder, hiddenCards] = await Promise.all([
          getUserStorageItem<string[]>('dashboardCardOrder'),
          getUserStorageItem<string[]>('hiddenDashboardCards')
        ]);

        let finalCardOrder: string[];
        let finalHiddenCards: string[];

        if (cardOrder && cardOrder.length > 0) {
          finalCardOrder = Array.from(new Set(cardOrder));
          setDashboardCardOrder(finalCardOrder);
          console.log('[useAppPreferences] ✅ Loaded dashboardCardOrder from localStorage:', finalCardOrder);
        } else {
          // 没有保存的数据，使用默认值
          finalCardOrder = ['calories', 'weight'];
          console.log('[useAppPreferences] ⚠️ No saved dashboardCardOrder found, using defaults');
          setDashboardCardOrder(finalCardOrder);
        }

        if (hiddenCards && Array.isArray(hiddenCards)) {
          finalHiddenCards = hiddenCards;
          setHiddenDashboardCards(finalHiddenCards);
          console.log('[useAppPreferences] ✅ Loaded hiddenDashboardCards from localStorage:', finalHiddenCards);
        } else {
          // 没有保存的数据，使用默认值
          finalHiddenCards = ['nutrition', 'water', 'steps', 'exercise', 'measurements', 'emotion', 'sleep', 'bloodGlucose'];
          console.log('[useAppPreferences] ⚠️ No saved hiddenDashboardCards found, using defaults');
          setHiddenDashboardCards(finalHiddenCards);
        }

        // ✅ 立即更新 ref，防止自动保存覆盖刚加载的数据
        lastSavedCardOrderRef.current = JSON.stringify(finalCardOrder);
        lastSavedHiddenCardsRef.current = JSON.stringify(finalHiddenCards);

        hasLoadedPreferencesRef.current = true;
        setIsLoading(false);
      } catch (error) {
        console.error('[useAppPreferences] ❌ Error loading user preferences:', error);
        // 出错时尝试从localStorage加载
        try {
          const [cardOrder, hiddenCards] = await Promise.all([
            getUserStorageItem<string[]>('dashboardCardOrder'),
            getUserStorageItem<string[]>('hiddenDashboardCards')
          ]);

          let fallbackCardOrder: string[];
          let fallbackHiddenCards: string[];

          if (cardOrder && cardOrder.length > 0) {
            fallbackCardOrder = Array.from(new Set(cardOrder));
            setDashboardCardOrder(fallbackCardOrder);
          } else {
            fallbackCardOrder = ['calories', 'weight'];
            setDashboardCardOrder(fallbackCardOrder);
          }

          if (hiddenCards && Array.isArray(hiddenCards)) {
            fallbackHiddenCards = hiddenCards;
            setHiddenDashboardCards(fallbackHiddenCards);
          } else {
            fallbackHiddenCards = ['nutrition', 'water', 'steps', 'exercise', 'measurements', 'emotion', 'sleep', 'bloodGlucose'];
            setHiddenDashboardCards(fallbackHiddenCards);
          }

          // ✅ 立即更新 ref，防止自动保存覆盖刚加载的数据
          lastSavedCardOrderRef.current = JSON.stringify(fallbackCardOrder);
          lastSavedHiddenCardsRef.current = JSON.stringify(fallbackHiddenCards);

          setIsLoading(false);
        } catch (localError) {
          console.error('[useAppPreferences] ❌ Error loading from localStorage fallback:', localError);
          // 最后的后备：使用默认值
          const defaultCardOrder = ['calories', 'weight'];
          const defaultHiddenCards = ['nutrition', 'water', 'steps', 'exercise', 'measurements', 'emotion', 'sleep', 'bloodGlucose'];
          setDashboardCardOrder(defaultCardOrder);
          setHiddenDashboardCards(defaultHiddenCards);

          // ✅ 立即更新 ref
          lastSavedCardOrderRef.current = JSON.stringify(defaultCardOrder);
          lastSavedHiddenCardsRef.current = JSON.stringify(defaultHiddenCards);

          setIsLoading(false);
        }
      }
    };

    loadUserPreferences();
  }, [isAuthenticated, authLoading, userId]);

  // 自动保存用户偏好（监听状态变化）
  useEffect(() => {
    // 跳过初始挂载时的保存（避免覆盖刚加载的数据）
    if (isInitialMountRef.current) {
      isInitialMountRef.current = false;
      lastSavedCardOrderRef.current = JSON.stringify(dashboardCardOrder);
      lastSavedHiddenCardsRef.current = JSON.stringify(hiddenDashboardCards);
      return;
    }

    // 如果没有用户ID，只保存到localStorage
    if (!userId || !isAuthenticated) {
      const uniqueCardOrder = Array.from(new Set(dashboardCardOrder));
      const cardOrderString = JSON.stringify(uniqueCardOrder);

      if (cardOrderString !== lastSavedCardOrderRef.current) {
        setUserStorageItem('dashboardCardOrder', uniqueCardOrder).catch(error => {
          console.error('[useAppPreferences] Error saving dashboardCardOrder to localStorage:', error);
        });
        lastSavedCardOrderRef.current = cardOrderString;
      }
      return;
    }

    // 去重：确保保存时清理重复的卡片ID
    const uniqueCardOrder = Array.from(new Set(dashboardCardOrder));
    const cardOrderString = JSON.stringify(uniqueCardOrder);
    const hiddenCardsString = JSON.stringify(hiddenDashboardCards);

    // 如果和上次保存的值相同，跳过保存
    if (cardOrderString === lastSavedCardOrderRef.current && 
        hiddenCardsString === lastSavedHiddenCardsRef.current) {
      return;
    }

    const savePreferences = async () => {
      try {
        // 同时保存到数据库和localStorage
        const [dbSuccess] = await Promise.allSettled([
          saveUserPreferences(userId, {
            dashboard_card_order: uniqueCardOrder,
            hidden_dashboard_cards: hiddenDashboardCards,
          }),
          setUserStorageItem('dashboardCardOrder', uniqueCardOrder),
          setUserStorageItem('hiddenDashboardCards', hiddenDashboardCards),
        ]);

        lastSavedCardOrderRef.current = cardOrderString;
        lastSavedHiddenCardsRef.current = hiddenCardsString;

        // 如果去重后数组长度发生变化，更新state
        if (uniqueCardOrder.length !== dashboardCardOrder.length) {
          setDashboardCardOrder(uniqueCardOrder);
        }
      } catch (error) {
        console.error('[useAppPreferences] Error saving preferences:', error);
        // 即使数据库保存失败，也尝试保存到localStorage
        try {
          await Promise.all([
            setUserStorageItem('dashboardCardOrder', uniqueCardOrder),
            setUserStorageItem('hiddenDashboardCards', hiddenDashboardCards),
          ]);
        } catch (localError) {
          console.error('[useAppPreferences] Error saving to localStorage fallback:', localError);
        }
      }
    };

    savePreferences();
  }, [dashboardCardOrder, hiddenDashboardCards, userId, isAuthenticated]);

  // ✅ 使用 ref 保存最新的值，避免竞态条件
  const currentCardOrderRef = useRef<string[]>(dashboardCardOrder);
  const currentHiddenCardsRef = useRef<string[]>(hiddenDashboardCards);

  // 同步 ref 和 state
  React.useEffect(() => {
    currentCardOrderRef.current = dashboardCardOrder;
  }, [dashboardCardOrder]);

  React.useEffect(() => {
    currentHiddenCardsRef.current = hiddenDashboardCards;
  }, [hiddenDashboardCards]);

  // 更新卡片顺序（自动保存到数据库）
  const updateCardOrder = async (order: string[]) => {
    const uniqueOrder = Array.from(new Set(order));

    // ✅ 关键修复：先更新 ref，防止自动保存的 useEffect 使用过时的值
    const orderString = JSON.stringify(uniqueOrder);
    lastSavedCardOrderRef.current = orderString;

    // 然后更新 state（这会触发自动保存的 useEffect，但由于 ref 已更新，会被跳过）
    setDashboardCardOrder(uniqueOrder);
    currentCardOrderRef.current = uniqueOrder;

    if (userId) {
      try {
        // ✅ 使用 ref 获取最新的 hiddenDashboardCards 值，避免使用过时的 state
        const currentHiddenCards = currentHiddenCardsRef.current;
        const success = await saveUserPreferences(userId, {
          dashboard_card_order: uniqueOrder,
          hidden_dashboard_cards: currentHiddenCards,
        });

        if (success) {
          await setUserStorageItem('dashboardCardOrder', uniqueOrder);
        } else {
          await setUserStorageItem('dashboardCardOrder', uniqueOrder);
        }
      } catch (error) {
        console.error('[useAppPreferences] ❌ Error saving card order:', error);
        // 即使数据库保存失败，也保存到 localStorage
        try {
          await setUserStorageItem('dashboardCardOrder', uniqueOrder);
        } catch (localError) {
          console.error('[useAppPreferences] ❌ Error saving to localStorage:', localError);
        }
      }
    } else {
      // 未登录用户，只保存到 localStorage
      try {
        await setUserStorageItem('dashboardCardOrder', uniqueOrder);
      } catch (error) {
        console.error('[useAppPreferences] Error saving card order to localStorage:', error);
      }
    }
  };

  // 更新隐藏卡片（自动保存到数据库）
  const updateHiddenCards = async (cards: string[]) => {
    // ✅ 关键修复：先更新 ref，防止自动保存的 useEffect 使用过时的值
    const cardsString = JSON.stringify(cards);
    lastSavedHiddenCardsRef.current = cardsString;

    // 然后更新 state（这会触发自动保存的 useEffect，但由于 ref 已更新，会被跳过）
    setHiddenDashboardCards(cards);
    currentHiddenCardsRef.current = cards;

    if (userId) {
      try {
        // ✅ 使用 ref 获取最新的 dashboardCardOrder 值，避免使用过时的 state
        const currentCardOrder = currentCardOrderRef.current;
        const success = await saveUserPreferences(userId, {
          dashboard_card_order: currentCardOrder,
          hidden_dashboard_cards: cards,
        });

        if (success) {
          await setUserStorageItem('hiddenDashboardCards', cards);
        } else {
          await setUserStorageItem('hiddenDashboardCards', cards);
        }
      } catch (error) {
        console.error('[useAppPreferences] ❌ Error saving hidden cards:', error);
        // 即使数据库保存失败，也保存到 localStorage
        try {
          await setUserStorageItem('hiddenDashboardCards', cards);
        } catch (localError) {
          console.error('[useAppPreferences] ❌ Error saving to localStorage:', localError);
        }
      }
    } else {
      // 未登录用户，只保存到 localStorage
      try {
        await setUserStorageItem('hiddenDashboardCards', cards);
      } catch (error) {
        console.error('[useAppPreferences] Error saving hidden cards to localStorage:', error);
      }
    }
  };

  return {
    // State
    dashboardCardOrder, // 加载中时显示默认值，加载完成后显示实际值
    hiddenDashboardCards,
    isLoadingPreferences: isLoading, // 导出加载状态（可选，用于显示加载指示器）

    // Actions
    setDashboardCardOrder,
    setHiddenDashboardCards,
    updateCardOrder,
    updateHiddenCards,
  };
}

/**
 * useBloodGlucoseRecordsQuery - 使用 React Query 的血糖记录 Hook
 * 符合架构规范：组件 → Hook → Supabase (3层)
 */

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useRef } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { bloodGlucoseService } from '../services/bloodGlucoseService';
import { toLocalDateString } from '../utils/dateUtils';

export function useBloodGlucoseRecordsQuery(startDate?: Date, endDate?: Date) {
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const addInFlightRef = useRef(false);

  const query = useQuery({
    queryKey: ['blood-glucose-records', user?.id, startDate?.toISOString(), endDate?.toISOString()],
    queryFn: () => {
      if (!user?.id) return [];
      return bloodGlucoseService.getRecords(user.id, startDate, endDate);
    },
    enabled: !!user?.id,
    staleTime: 5 * 60 * 1000,
  });

  const addMutation = useMutation({
    mutationFn: async ({
      value,
      date,
      notes,
      extraData,
    }: {
      value: number;
      date: Date;
      notes?: string;
      extraData?: any;
    }) => {
      if (!user?.id) throw new Error('User not authenticated');
      if (addInFlightRef.current) {
        throw new Error('正在保存血糖记录，请稍候');
      }
      addInFlightRef.current = true;
      try {
        return await bloodGlucoseService.addRecord(user.id, value, date, notes, extraData);
      } finally {
        addInFlightRef.current = false;
      }
    },
    onSuccess: (_, variables) => {
      const dateKey = toLocalDateString(variables.date);
      queryClient.invalidateQueries({ queryKey: ['blood-glucose-records', user?.id] });
      // 自动刷新 Dashboard 数据
      queryClient.invalidateQueries({ queryKey: ['dashboard-data', user?.id, dateKey] });
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({
      id,
      value,
      date,
      notes,
      extraData,
    }: {
      id: string;
      value: number;
      date: Date;
      notes?: string;
      extraData?: any;
    }) => bloodGlucoseService.updateRecord(id, value, date, notes, extraData),
    onSuccess: (_, variables) => {
      const dateKey = toLocalDateString(variables.date);
      queryClient.invalidateQueries({ queryKey: ['blood-glucose-records', user?.id] });
      queryClient.invalidateQueries({ queryKey: ['dashboard-data', user?.id, dateKey] });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => bloodGlucoseService.deleteRecord(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['blood-glucose-records', user?.id] });
      // 刷新所有 Dashboard 数据
      queryClient.invalidateQueries({ queryKey: ['dashboard-data', user?.id] });
    },
  });

  return {
    records: query.data || [],
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
    addRecord: addMutation.mutateAsync,
    updateRecord: updateMutation.mutateAsync,
    deleteRecord: deleteMutation.mutateAsync,
    isAdding: addMutation.isPending,
    isUpdating: updateMutation.isPending,
    isDeleting: deleteMutation.isPending,
    refresh: () => query.refetch(),
  };
}

/**
 * useCalendarLogic - 日历相关逻辑Hook
 * 从App.tsx中提取的日历相关函数
 */

import { useMemo } from 'react';

export function useCalendarLogic(selectedDate: Date) {
  const formatDate = (date: Date) => {
    const targetDate = new Date(date);
    return `${targetDate.getMonth() + 1}/${targetDate.getDate()}`;
  };

  const generateCalendarDays = () => {
    const year = selectedDate.getFullYear();
    const month = selectedDate.getMonth();

    // First day of the month
    const firstDay = new Date(year, month, 1);
    // Last day of the month
    const lastDay = new Date(year, month + 1, 0);

    // Day of week for first day (0 = Sunday, 6 = Saturday)
    const startDay = firstDay.getDay();

    // Days in the month
    const daysInMonth = lastDay.getDate();

    const days: Date[] = [];

    // Add days from previous month to fill the first week
    const prevMonth = new Date(year, month - 1, 0);
    const daysInPrevMonth = prevMonth.getDate();
    for (let i = startDay - 1; i >= 0; i--) {
      days.push(new Date(year, month - 1, daysInPrevMonth - i));
    }

    // Add days of current month
    for (let i = 1; i <= daysInMonth; i++) {
      days.push(new Date(year, month, i));
    }

    // Add days from next month to fill the last week (to make 6 weeks total)
    const remainingDays = 42 - days.length; // 6 weeks * 7 days = 42
    for (let i = 1; i <= remainingDays; i++) {
      days.push(new Date(year, month + 1, i));
    }

    return days;
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
           date.getMonth() === today.getMonth() &&
           date.getFullYear() === today.getFullYear();
  };

  const isSameMonth = (date: Date, referenceDate: Date = selectedDate) => {
    return date.getMonth() === referenceDate.getMonth() &&
           date.getFullYear() === referenceDate.getFullYear();
  };

  return {
    formatDate,
    generateCalendarDays,
    isToday,
    isSameMonth,
  };
}

