import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { executionTaskService } from '../services/executionTaskService';
import { deliveryScheduleService } from '../services/deliveryScheduleService';
import { useAuth } from '../contexts/AuthContext';
import { useBeijingDateKey } from './useBeijingDateKey';

/**
 * 每日任务Hook
 * 管理今日任务流
 */
export function useDailyTasks(programId: string | null) {
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const today = useBeijingDateKey();

  // 查询今日任务
  const {
    data: tasks = [],
    isLoading,
    error,
    refetch,
  } = useQuery({
    queryKey: ['daily-tasks', programId, today],
    queryFn: async () => {
      if (!programId) return [];
      return executionTaskService.getTasksByDate(programId, today);
    },
    enabled: !!programId,
    staleTime: 2 * 60 * 1000, // 2分钟缓存
  });

  // 查询下一个任务
  const {
    data: nextTask,
    isLoading: isLoadingNextTask,
  } = useQuery({
    queryKey: ['next-task', programId, today],
    queryFn: async () => {
      if (!programId) return null;
      return executionTaskService.getNextTask(programId, today);
    },
    enabled: !!programId,
    staleTime: 1 * 60 * 1000, // 1分钟缓存
  });

  // 完成任务mutation
  const completeTaskMutation = useMutation({
    mutationFn: async ({ taskId, completionData }: { taskId: string; completionData?: Record<string, any> }) => {
      return executionTaskService.markTaskComplete(taskId, completionData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['daily-tasks', programId, today] });
      queryClient.invalidateQueries({ queryKey: ['next-task', programId, today] });
    },
  });

  // 跳过任务mutation
  const skipTaskMutation = useMutation({
    mutationFn: async (taskId: string) => {
      return executionTaskService.skipTask(taskId);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['daily-tasks', programId, today] });
      queryClient.invalidateQueries({ queryKey: ['next-task', programId, today] });
    },
  });

  // 生成任务mutation
  const generateTasksMutation = useMutation({
    mutationFn: async ({ taskDate, mealDeliverySchedules }: { 
      taskDate: string; 
      mealDeliverySchedules?: Array<{
        id?: string;
        delivery_date: string;
        meal_type: string;
        delivery_time_start?: string;
      }>;
    }) => {
      if (!programId) throw new Error('No program ID');

      console.log('🔄 [useDailyTasks] Generating tasks for date:', taskDate);

      // 如果没有提供配送计划，自动获取
      let schedules = mealDeliverySchedules;
      if (!schedules && user?.id) {
        const date = new Date(taskDate);
        schedules = await deliveryScheduleService.getDeliverySchedulesByDate(user.id, date);
        console.log('📦 [useDailyTasks] Fetched delivery schedules:', schedules?.length || 0);
      }

      const result = await executionTaskService.generateDailyTasks(programId, taskDate, schedules);
      console.log('✅ [useDailyTasks] Generated tasks:', result.length);
      return result;
    },
    onSuccess: async (_data, variables) => {
      console.log('🔄 [useDailyTasks] Invalidating queries after task generation');
      // 刷新所有相关的查询，包括带日期的和不带日期的
      await queryClient.invalidateQueries({ queryKey: ['daily-tasks', programId] });
      await queryClient.invalidateQueries({ queryKey: ['daily-tasks', programId, variables.taskDate] });
      await queryClient.invalidateQueries({ queryKey: ['next-task', programId] });
      // 强制拉取一次当天任务，避免“点击后无变化”的缓存/时序问题
      await queryClient.refetchQueries({ queryKey: ['daily-tasks', programId, variables.taskDate], exact: true });
    },
  });

  return {
    tasks,
    nextTask: nextTask || null,
    isLoading,
    isLoadingNextTask,
    error,
    refresh: refetch,
    completeTask: completeTaskMutation.mutateAsync,
    skipTask: skipTaskMutation.mutateAsync,
    generateTasks: generateTasksMutation.mutateAsync,
  };
}

/**
 * useDashboardData - Dashboard数据获取和管理Hook（基于React Query）
 * 符合架构规范：组件 → Hook → Supabase (3层)
 * 
 * 重构说明：
 * - 使用 React Query 管理数据获取和缓存
 * - 自动响应相关数据变更（通过 invalidateQueries）
 * - 保留 userDayDataOverrides 功能用于本地覆盖
 */

import { useMemo, useCallback } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { DayData } from '../utils/mockData';
import { generateMockData } from '../utils/mockData';
import { dashboardDataService } from '../services/dashboardDataService';
import { UserProfile } from '../utils/bmrCalculations';
import { useState } from 'react';
import { toLocalDateString } from '../utils/dateUtils';

interface UseDashboardDataOptions {
  userId: string | null;
  selectedDate: Date;
  profile: UserProfile | null;
  showOnboarding?: boolean;
}

/**
 * 格式化日期为 YYYY-MM-DD 格式的 key
 */
function formatDateKey(date: Date): string {
  return toLocalDateString(date);
}

export function useDashboardData({
  userId,
  selectedDate,
  profile,
  showOnboarding = false,
}: UseDashboardDataOptions) {
  const queryClient = useQueryClient();

  // 保留 userDayDataOverrides 用于本地覆盖（如快速编辑、临时修改等）
  const [userDayDataOverrides, setUserDayDataOverrides] = useState<Record<string, Partial<DayData>>>({});

  // 格式化日期 key
  const dateKey = formatDateKey(selectedDate);

  // 使用 React Query 管理 Dashboard 数据
  const dashboardQuery = useQuery({
    queryKey: ['dashboard-data', userId, dateKey, showOnboarding, profile?.target_weight],
    queryFn: async () => {
      if (!userId) {
        // 无用户ID时使用mock数据
        return generateMockData(selectedDate);
      }

      const targetWeight = profile?.target_weight || 60;
      try {
        const data = await dashboardDataService.getDayData(selectedDate, {
          showTutorialData: showOnboarding,
          targetWeight: targetWeight,
          userProfile: profile,
        });
        return data;
      } catch (error) {
        console.error('[useDashboardData] Error loading day data:', error);
        // 降级到mock数据
        return generateMockData(selectedDate);
      }
    },
    enabled: true, // 总是启用，即使没有 userId 也返回 mock 数据
    staleTime: 5 * 60 * 1000, // 5分钟缓存
    gcTime: 10 * 60 * 1000, // 10分钟垃圾回收时间
  });

  // 获取当前日期的数据（应用本地覆盖）
  const getCurrentDateData = useCallback((): DayData => {
    const queryData = dashboardQuery.data;
    const userOverrides = userDayDataOverrides[dateKey];

    // 优先使用查询数据
    if (queryData) {
      if (userOverrides) {
        // 应用本地覆盖；mealIntakeStatus 取并集（今日餐与餐食方案两处完成摄入需全站同步）
        const mergedMealIntakeStatus = {
          ...queryData.mealIntakeStatus,
          ...userOverrides.mealIntakeStatus,
        };
        return {
          ...queryData,
          ...userOverrides,
          mealIntakeStatus: Object.keys(mergedMealIntakeStatus).length > 0 ? mergedMealIntakeStatus : undefined,
          weight: userOverrides.weight ? { ...queryData.weight, ...userOverrides.weight } : queryData.weight,
          water: userOverrides.water ? { ...queryData.water, ...userOverrides.water } : queryData.water,
        };
      }
      return queryData;
    }

    // 降级到mock数据
    const mockData = generateMockData(selectedDate);
    if (userOverrides) {
      const finalData = { ...mockData, ...userOverrides };

      // 合并weight和water对象
      if (userOverrides.weight) {
        finalData.weight = { ...mockData.weight, ...userOverrides.weight };
      }
      if (userOverrides.water) {
        finalData.water = { ...mockData.water, ...userOverrides.water };
      }

      // 计算营养数据
      if (userOverrides.records) {
        const foodRecords = userOverrides.records.filter(record => record.type === 'food');
        const totalCalories = foodRecords.reduce((sum, record) => sum + (record.calories || 0), 0);
        const totalProtein = foodRecords.reduce((sum, record) => sum + (record.nutrition_data?.protein || 0), 0);
        const totalCarbs = foodRecords.reduce((sum, record) => sum + (record.nutrition_data?.carbs || 0), 0);
        const totalFat = foodRecords.reduce((sum, record) => sum + (record.nutrition_data?.fat || 0), 0);

        finalData.calories = {
          ...finalData.calories,
          foodIntake: totalCalories,
          remaining: finalData.calories.total - totalCalories + finalData.calories.exerciseBurned
        };

        finalData.nutrition = {
          carbs: { current: Math.round(totalCarbs), target: finalData.nutrition.carbs.target },
          protein: { current: Math.round(totalProtein), target: finalData.nutrition.protein.target },
          fat: { current: Math.round(totalFat), target: finalData.nutrition.fat.target }
        };
      }

      return finalData;
    }

    return mockData;
  }, [dashboardQuery.data, selectedDate, userDayDataOverrides, dateKey]);

  // 更新本地覆盖数据
  const updateDayData = useCallback((date: Date, updates: Partial<DayData>) => {
    const updateDateKey = formatDateKey(date);
    setUserDayDataOverrides(prev => ({
      ...prev,
      [updateDateKey]: {
        ...prev[updateDateKey],
        ...updates,
      }
    }));

    // 如果更新的是当前日期，同时失效查询以触发重新获取
    if (updateDateKey === dateKey) {
      queryClient.invalidateQueries({ queryKey: ['dashboard-data', userId, updateDateKey] });
    }
  }, [dateKey, userId, queryClient]);

  // 手动刷新数据（保留接口以保持向后兼容）
  const loadDayData = useCallback((date: Date) => {
    const refreshDateKey = formatDateKey(date);
    queryClient.invalidateQueries({ queryKey: ['dashboard-data', userId, refreshDateKey] });
  }, [userId, queryClient]);

  // 使用 useMemo 缓存当前日期数据
  const currentDateData = useMemo(() => {
    return getCurrentDateData();
  }, [getCurrentDateData]);

  return {
    realTimeData: dashboardQuery.data || null,
    loadingDayData: dashboardQuery.isLoading,
    userDayDataOverrides,
    setUserDayDataOverrides,
    loadDayData,
    updateDayData,
    getCurrentDateData,
    formatDateKey,
    // 新增：提供 React Query 的原始数据访问
    refetch: dashboardQuery.refetch,
    isError: dashboardQuery.isError,
    error: dashboardQuery.error,
  };
}

/**
 * useDateSelection - 日期选择和管理Hook
 * 从App.tsx中提取的日期相关逻辑
 */

import { useState, useCallback } from 'react';
import { toLocalDateString } from '../utils/dateUtils';

export function useDateSelection(initialDate?: Date) {
  const [selectedDate, setSelectedDate] = useState<Date>(initialDate || new Date());
  const [displayedWeekStart, setDisplayedWeekStart] = useState<Date>(() => {
    const today = initialDate || new Date();
    const weekStart = new Date(today);
    weekStart.setDate(today.getDate() - today.getDay());
    return weekStart;
  });
  const [showCalendar, setShowCalendar] = useState(false);

  const handleDateChange = useCallback((date: Date) => {
    setSelectedDate(date);
    // 更新周视图起始日期
    const weekStart = new Date(date);
    weekStart.setDate(date.getDate() - date.getDay());
    setDisplayedWeekStart(weekStart);
  }, []);

  const handleWeekStartChange = useCallback((date: Date) => {
    setDisplayedWeekStart(date);
  }, []);

  const formatDateKey = useCallback((date: Date) => {
    return toLocalDateString(date);
  }, []);

  const formatDate = useCallback((date: Date) => {
    const today = new Date();
    if (date.toDateString() === today.toDateString()) {
      return '今日';
    }
    return '回今天';
  }, []);

  const isToday = useCallback((date: Date) => {
    const today = new Date();
    return date.toDateString() === today.toDateString();
  }, []);

  const isSameMonth = useCallback((date: Date, compareDate: Date) => {
    return date.getMonth() === compareDate.getMonth() && 
           date.getFullYear() === compareDate.getFullYear();
  }, []);

  const generateCalendarDays = useCallback((date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startDate = new Date(firstDay);
    startDate.setDate(startDate.getDate() - firstDay.getDay());

    const days = [];
    for (let i = 0; i < 42; i++) {
      const day = new Date(startDate);
      day.setDate(startDate.getDate() + i);
      days.push(day);
    }
    return days;
  }, []);

  const goToToday = useCallback(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    handleDateChange(today);
  }, [handleDateChange]);

  return {
    selectedDate,
    displayedWeekStart,
    showCalendar,
    setSelectedDate: handleDateChange,
    setDisplayedWeekStart: handleWeekStartChange,
    setShowCalendar,
    formatDateKey,
    formatDate,
    isToday,
    isSameMonth,
    generateCalendarDays,
    goToToday,
  };
}

/**
 * useDeliveryPlanLock - 配送计划锁定逻辑Hook
 * 从DeliveryPlanPage.tsx中提取的锁定逻辑
 * 符合架构规范：单一职责，减少组件复杂度
 */

import { getDeliveryMealTimeRange } from '../constants/deliveryMealTimes';

interface UseDeliveryPlanLockOptions {
  lockedMeals: Set<string>;
  manuallyModifiedMeals: Set<string>;
  getMealKey: (date: Date, mealType: string) => string;
}

export function useDeliveryPlanLock({
  lockedMeals,
  manuallyModifiedMeals,
  getMealKey,
}: UseDeliveryPlanLockOptions) {
  // 检查是否自动锁定（基于配送时间）
  const isAutoLocked = (date: Date, mealType: string): boolean => {
    const now = new Date();
    const deliveryDate = new Date(date);

    const startTime = getDeliveryMealTimeRange(mealType).start;
    const [hours, minutes] = startTime.split(':').map(Number);
    if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return false;
    deliveryDate.setHours(hours, minutes, 0, 0);

    // Calculate 1 hour before delivery
    const lockTime = new Date(deliveryDate.getTime() - 60 * 60 * 1000);

    return now >= lockTime;
  };

  // 检查是否手动锁定
  const isManuallyLocked = (date: Date, mealType: string): boolean => {
    const mealKey = getMealKey(date, mealType);
    return lockedMeals.has(mealKey);
  };

  // 检查是否锁定（手动或自动）
  const isMealLocked = (date: Date, mealType: string): boolean => {
    return isManuallyLocked(date, mealType) || isAutoLocked(date, mealType);
  };

  // 获取日期锁定状态
  const getDayLockStatus = (date: Date, dateConfigs: Array<{ mealType: string }>): 'full' | 'partial' | 'none' => {
    if (dateConfigs.length === 0) return 'none';

    const lockedCount = dateConfigs.filter(config => 
      isMealLocked(date, config.mealType)
    ).length;

    if (lockedCount === 0) return 'none';
    if (lockedCount === dateConfigs.length) return 'full';
    return 'partial';
  };

  return {
    isAutoLocked,
    isManuallyLocked,
    isMealLocked,
    getDayLockStatus,
  };
}

import { useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { executionProgramService, ExecutionProgram } from '../services/executionProgramService';
import { useAuth } from '../contexts/AuthContext';

/**
 * 执行计划Hook
 * 管理执行计划状态，自动从订单同步
 */
export function useExecutionProgram() {
  const { user } = useAuth();
  const userId = user?.id || null;
  const queryClient = useQueryClient();

  // 查询执行计划
  const {
    data: program,
    isLoading,
    error,
    refetch,
  } = useQuery({
    queryKey: ['execution-program', userId],
    queryFn: async () => {
      if (!userId) {
        console.log('⚠️ [useExecutionProgram] No userId, returning null');
        return null;
      }

      try {
        console.log('🔄 [useExecutionProgram] Starting sync and fetch for userId:', userId);
        // 先同步，再获取
        const syncedProgram = await executionProgramService.syncProgramFromOrder(userId);
        console.log('🔄 [useExecutionProgram] Sync result:', syncedProgram ? { 
          id: syncedProgram.id,
          currentDay: syncedProgram.current_day,
          status: syncedProgram.status 
        } : null);

        const activeProgram = await executionProgramService.getActiveProgram(userId);
        console.log('🔄 [useExecutionProgram] Active program result:', activeProgram ? { 
          id: activeProgram.id, 
          currentDay: activeProgram.current_day,
          status: activeProgram.status 
        } : null);

        if (!activeProgram && syncedProgram) {
          console.warn('⚠️ [useExecutionProgram] syncProgram returned data but getActiveProgram returned null. This might be a status mismatch.');
        }

        return activeProgram || syncedProgram; // 如果 getActiveProgram 返回 null，尝试使用 syncedProgram
      } catch (error) {
        console.error('❌ [useExecutionProgram] Error in queryFn:', error);
        throw error;
      }
    },
    enabled: !!userId,
    staleTime: 0, // 🔥 临时禁用缓存，确保每次都重新查询
    cacheTime: 0, // 🔥 临时禁用缓存
    retry: 1, // 只重试1次
  });

  // 检查用户是否有订单
  const {
    data: hasOrder,
    isLoading: isLoadingOrder,
    error: orderError,
  } = useQuery({
    queryKey: ['user-has-order', userId],
    queryFn: async () => {
      if (!userId) {
        console.log('⚠️ [useExecutionProgram] No userId, returning false');
        return false;
      }
      const result = await executionProgramService.checkUserHasOrder(userId);
      console.log('🔍 [useExecutionProgram] checkUserHasOrder result:', result, 'for userId:', userId);
      return result;
    },
    enabled: !!userId,
    staleTime: 10 * 60 * 1000, // 10分钟缓存
  });

  // 🔥 添加调试日志
  useEffect(() => {
    if (userId) {
      console.log('🔍 [useExecutionProgram] State Update:', {
        userId,
        hasOrder,
        isLoadingOrder,
        orderError: orderError?.message,
        program: program ? { 
          id: program.id, 
          status: program.status,
          currentDay: program.current_day,
          totalDays: program.total_days 
        } : null,
        isLoading,
      });
    }
  }, [userId, hasOrder, isLoadingOrder, orderError, program, isLoading]);

  // 同步执行计划mutation
  const syncMutation = useMutation({
    mutationFn: async () => {
      if (!userId) throw new Error('User not authenticated');
      return executionProgramService.syncProgramFromOrder(userId);
    },
    onSuccess: () => {
      queryClient.invalidateQueries(['execution-program', userId]);
    },
  });

  // 更新当前天数mutation
  const updateCurrentDayMutation = useMutation({
    mutationFn: async (currentDay: number) => {
      if (!program?.id) throw new Error('No active program');
      return executionProgramService.updateCurrentDay(program.id, currentDay);
    },
    onSuccess: () => {
      queryClient.invalidateQueries(['execution-program', userId]);
    },
  });

  return {
    program: program || null,
    isLoading,
    error,
    hasOrder: hasOrder || false,
    isLoadingOrder,
    currentDay: program?.current_day || 0,
    totalDays: program?.total_days || 0,
    refresh: refetch,
    syncProgram: syncMutation.mutateAsync,
    updateCurrentDay: updateCurrentDayMutation.mutateAsync,
  };
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { executionReportService, ExecutionReport } from '../services/executionReportService';
import { toLocalDateString } from '../utils/dateUtils';

/**
 * 执行报告Hook
 * 管理报告生成
 */
export function useExecutionReport(programId: string | null) {
  const queryClient = useQueryClient();
  const today = toLocalDateString(new Date());

  // 查询今日报告
  const {
    data: dailyReport,
    isLoading: isLoadingDaily,
    error: dailyError,
  } = useQuery({
    queryKey: ['execution-report', programId, 'daily', today],
    queryFn: async () => {
      if (!programId) return null;
      return executionReportService.getReport(programId, 'daily', today);
    },
    enabled: !!programId,
    staleTime: 10 * 60 * 1000, // 10分钟缓存
  });

  // 查询周报（本周开始日期）
  const weekStartDate = (() => {
    const date = new Date();
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); // 周一
    const monday = new Date(date.setDate(diff));
    return toLocalDateString(monday);
  })();

  const {
    data: weeklyReport,
    isLoading: isLoadingWeekly,
    error: weeklyError,
  } = useQuery({
    queryKey: ['execution-report', programId, 'weekly', weekStartDate],
    queryFn: async () => {
      if (!programId) return null;
      return executionReportService.getReport(programId, 'weekly', weekStartDate);
    },
    enabled: !!programId,
    staleTime: 30 * 60 * 1000, // 30分钟缓存
  });

  // 生成每日报告mutation
  const generateDailyReportMutation = useMutation({
    mutationFn: async (reportDate?: string) => {
      if (!programId) throw new Error('No program ID');
      const date = reportDate || today;
      console.log('🔄 [useExecutionReport] Generating daily report for date:', date);
      const result = await executionReportService.generateDailyReport(programId, date);
      console.log('✅ [useExecutionReport] Daily report generated:', result ? 'success' : 'failed');
      return { result, date };
    },
    onSuccess: (data, reportDate) => {
      const date = reportDate || today;
      console.log('🔄 [useExecutionReport] Updating cache for date:', date);

      // 🔥 关键修复：直接将生成的结果设置到查询缓存
      // 这样即使数据库更新失败（RLS问题），UI也能显示新生成的内容
      if (data.result) {
        // 🔥 验证报告内容是否正确
        console.log('📊 [useExecutionReport] Setting report to cache:', {
          reportId: data.result.id,
          progress: data.result.report_content?.progress,
          summary: data.result.report_content?.summary?.substring(0, 50) + '...',
        });

        // 🔥 直接设置缓存，不invalidate，避免重新查询数据库（可能还是旧数据）
        queryClient.setQueryData(['execution-report', programId, 'daily', date], data.result);
        console.log('✅ [useExecutionReport] Report data set to cache');

        // 🔥 验证缓存是否设置成功
        const cachedData = queryClient.getQueryData(['execution-report', programId, 'daily', date]);
        if (cachedData) {
          const cached = cachedData as any;
          console.log('✅ [useExecutionReport] Cache verified:', {
            hasData: !!cached,
            progress: cached.report_content?.progress,
            completionRate: cached.report_content?.progress?.completion_rate,
          });
        } else {
          console.error('❌ [useExecutionReport] Cache not set!');
        }
      }

      // ⚠️ 不立即invalidate，避免清除缓存后重新查询数据库（可能还是旧数据）
      // 如果用户需要刷新，可以手动点击刷新按钮
      // queryClient.invalidateQueries(['execution-report', programId, 'daily', date]);
    },
  });

  // 生成周报mutation
  const generateWeeklyReportMutation = useMutation({
    mutationFn: async (weekStart?: string) => {
      if (!programId) throw new Error('No program ID');
      const date = weekStart || weekStartDate;
      const result = await executionReportService.generateWeeklyReport(programId, date);
      return { result, date };
    },
    onSuccess: (data, weekStart) => {
      const date = weekStart || weekStartDate;
      console.log('🔄 [useExecutionReport] Updating weekly report cache for date:', date);

      // 🔥 关键修复：直接将生成的结果设置到查询缓存
      if (data.result) {
        queryClient.setQueryData(['execution-report', programId, 'weekly', date], data.result);
        console.log('✅ [useExecutionReport] Weekly report data set to cache');
      }

      // 也invalidate查询，确保下次从数据库获取最新数据
      queryClient.invalidateQueries(['execution-report', programId, 'weekly', date]);
      queryClient.invalidateQueries(['execution-report', programId]);
    },
  });

  // 生成里程碑报告mutation
  const generateMilestoneReportMutation = useMutation({
    mutationFn: async (milestoneDay: number) => {
      if (!programId) throw new Error('No program ID');
      return executionReportService.generateMilestoneReport(programId, milestoneDay);
    },
    onSuccess: () => {
      queryClient.invalidateQueries(['execution-report', programId]);
    },
  });

  return {
    dailyReport: dailyReport || null,
    weeklyReport: weeklyReport || null,
    isLoadingDaily,
    isLoadingWeekly,
    dailyError,
    weeklyError,
    generateDailyReport: generateDailyReportMutation.mutateAsync,
    generateWeeklyReport: generateWeeklyReportMutation.mutateAsync,
    generateMilestoneReport: generateMilestoneReportMutation.mutateAsync,
  };
}

/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * useExerciseChartData - 运动图表数据计算Hook
 * 从ExerciseStatsDetailScreen.tsx中提取的图表数据计算逻辑
 * 符合架构规范：单一职责，减少组件复杂度
 */

import { useMemo } from 'react';
import { toLocalDateString } from '../utils/dateUtils';

interface ChartDataPoint {
  label: string;
  calories: number;
  value: number;
}

interface UseExerciseChartDataOptions {
  timePeriod: 'day' | 'week' | 'month' | 'year';
  currentWeekStart: Date;
  userDayDataOverrides: Record<string, any>;
  exerciseRecordsFromDB: any[];
}

export function useExerciseChartData({
  timePeriod,
  currentWeekStart,
  userDayDataOverrides,
  exerciseRecordsFromDB,
}: UseExerciseChartDataOptions) {
  const formatDateKey = (date: Date) => {
    return toLocalDateString(date);
  };

  // 获取指定日期的运动卡路里
  const getExerciseCaloriesForDate = (date: Date): number => {
    const dateKey = formatDateKey(date);
    const dayData = userDayDataOverrides[dateKey];
    const localRecords = dayData?.records?.filter((r: any) => r.type === 'exercise') || [];

    const targetDateStr = toLocalDateString(date);
    // 注意：exerciseRecordsFromDB 已经是 ExerciseRecord 格式
    // 包含：id, exercise_name, duration, calories_burned, icon, originalId, recorded_at 等字段
    const dbRecords = exerciseRecordsFromDB
      .filter((record: any) => {
        const recordDateStr = toLocalDateString(new Date(record.recorded_at));
        return recordDateStr === targetDateStr;
      })
      .map((record: any) => ({
        id: record.id,
        type: 'exercise' as const,
        name: record.exercise_name || '',
        time: new Date(record.recorded_at).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }),
        exercise_data: {
          name: record.exercise_name || '',
          calories: record.calories_burned || 0,
          duration: record.duration || 0,
        }
      }));

    const all = [...dbRecords, ...localRecords];
    const unique = Array.from(new Map(all.map(r => [r.id || `${r.exercise_data?.name}-${r.time}-${r.exercise_data?.duration || 0}`, r])).values());
    const totalCalories = unique.reduce((sum, r: any) => sum + (r.exercise_data?.calories || 0), 0);

    return totalCalories;
  };

  // 获取指定时间段内的运动卡路里
  const getExerciseCaloriesForTimePeriod = (date: Date, startHour: number, endHour: number): number => {
    const dateKey = formatDateKey(date);
    const dayData = userDayDataOverrides[dateKey];
    const localRecords = dayData?.records?.filter((r: any) => r.type === 'exercise') || [];

    const targetDateStr = toLocalDateString(date);
    // 注意：exerciseRecordsFromDB 已经是 ExerciseRecord 格式
    const dbRecords = exerciseRecordsFromDB
      .filter((record: any) => {
        const recordDateStr = toLocalDateString(new Date(record.recorded_at));
        if (recordDateStr !== targetDateStr) return false;
        const recordHour = new Date(record.recorded_at).getHours();
        return recordHour >= startHour && recordHour < endHour;
      })
      .map((record: any) => ({
        id: record.id,
        type: 'exercise' as const,
        name: record.exercise_name || '',
        time: new Date(record.recorded_at).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }),
        exercise_data: {
          name: record.exercise_name || '',
          calories: record.calories_burned || 0,
          duration: record.duration || 0,
        }
      }));

    const filteredLocalRecords = localRecords.filter((r: any) => {
      if (!r.time) return false;
      const timeMatch = r.time.match(/(\d{2}):(\d{2})/);
      if (!timeMatch) return false;
      const hour = parseInt(timeMatch[1]);
      return hour >= startHour && hour < endHour;
    });

    const all = [...dbRecords, ...filteredLocalRecords];
    const unique = Array.from(new Map(all.map(r => [r.id || `${r.exercise_data?.name}-${r.time}-${r.exercise_data?.duration || 0}`, r])).values());
    const totalCalories = unique.reduce((sum, r: any) => sum + (r.exercise_data?.calories || 0), 0);

    return totalCalories;
  };
  // 计算图表数据
  const chartData = useMemo(() => {
    const data: ChartDataPoint[] = [];

    if (timePeriod === 'day') {
      // Use time periods: 00:00-06:00, 06:00-12:00, 12:00-18:00, 18:00-24:00
      const timePeriods = [
        { label: '00:00', start: 0, end: 6 },
        { label: '06:00', start: 6, end: 12 },
        { label: '12:00', start: 12, end: 18 },
        { label: '18:00', start: 18, end: 24 }
      ];

      timePeriods.forEach(period => {
        const calories = getExerciseCaloriesForTimePeriod(currentWeekStart, period.start, period.end);
        data.push({
          label: period.label,
          calories: calories,
          value: calories
        });
      });
    } else if (timePeriod === 'week') {
      for (let i = 0; i < 7; i++) {
        const date = new Date(currentWeekStart);
        date.setDate(currentWeekStart.getDate() + i);
        const calories = getExerciseCaloriesForDate(date);
        data.push({
          label: `${String(date.getMonth() + 1).padStart(2, '0')}/${String(date.getDate()).padStart(2, '0')}`,
          calories: calories,
          value: calories
        });
      }
    } else if (timePeriod === 'month') {
      const year = currentWeekStart.getFullYear();
      const month = currentWeekStart.getMonth();
      const daysInMonth = new Date(year, month + 1, 0).getDate();

      for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(year, month, day);
        const calories = getExerciseCaloriesForDate(date);
        data.push({
          label: String(day),
          calories: calories,
          value: calories
        });
      }
    } else if (timePeriod === 'year') {
      const year = currentWeekStart.getFullYear();

      for (let month = 0; month < 12; month++) {
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        let monthTotal = 0;

        for (let day = 1; day <= daysInMonth; day++) {
          const date = new Date(year, month, day);
          monthTotal += getExerciseCaloriesForDate(date);
        }

        data.push({
          label: `${month + 1}`,
          calories: monthTotal,
          value: monthTotal
        });
      }
    }

    return data;
  }, [timePeriod, currentWeekStart, userDayDataOverrides, exerciseRecordsFromDB]);

  // 获取上一周期的数据用于对比
  const previousPeriodData = useMemo(() => {
    if (timePeriod !== 'month' && timePeriod !== 'year') {
      return [];
    }

    const prevDate = new Date(currentWeekStart);
    if (timePeriod === 'month') {
      prevDate.setMonth(prevDate.getMonth() - 1);
    } else {
      prevDate.setFullYear(prevDate.getFullYear() - 1);
    }

    const data: ChartDataPoint[] = [];
    if (timePeriod === 'month') {
      const year = prevDate.getFullYear();
      const month = prevDate.getMonth();
      const daysInMonth = new Date(year, month + 1, 0).getDate();

      for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(year, month, day);
        const calories = getExerciseCaloriesForDate(date);
        data.push({
          label: String(day),
          calories: calories,
          value: calories
        });
      }
    } else if (timePeriod === 'year') {
      const year = prevDate.getFullYear();

      for (let month = 0; month < 12; month++) {
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        let monthTotal = 0;

        for (let day = 1; day <= daysInMonth; day++) {
          const date = new Date(year, month, day);
          monthTotal += getExerciseCaloriesForDate(date);
        }

        data.push({
          label: `${month + 1}`,
          calories: monthTotal,
          value: monthTotal
        });
      }
    }

    return data;
  }, [timePeriod, currentWeekStart, userDayDataOverrides, exerciseRecordsFromDB]);

  // 计算Y轴最大值和最小值
  const yAxisMax = useMemo(() => {
    const maxCalories = Math.max(...chartData.map(d => d.calories), 100);
    return Math.ceil(maxCalories / 100) * 100;
  }, [chartData]);

  const yAxisMin = 0;

  return {
    chartData,
    previousPeriodData,
    yAxisMax,
    yAxisMin,
  };
}

/**
 * useHealthAssessmentQuery - 使用 React Query 的健康评估 Hook
 * 符合架构规范：组件 → Hook → Supabase (3层)
 */

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuth } from '../contexts/AuthContext';
import { healthAssessmentService, HealthAssessmentData } from '../services/healthAssessmentService';

export function useHealthAssessmentQuery() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  // 查询：使用 React Query
  const query = useQuery({
    queryKey: ['health-assessment', user?.id],
    queryFn: async () => {
      if (!user?.id) return null;
      const result = await healthAssessmentService.getLatestAssessment();
      if (result.error) throw result.error;
      return result.data;
    },
    enabled: !!user?.id,
    staleTime: 5 * 60 * 1000, // 5分钟缓存
  });

  // 创建评估：使用 React Query Mutation
  const createMutation = useMutation({
    mutationFn: ({ data, isReassessment }: { data: any; isReassessment?: boolean }) => {
      if (!user?.id) throw new Error('User not authenticated');
      return healthAssessmentService.createAssessment(data, isReassessment);
    },
    onSuccess: (result) => {
      if (result.data) {
        // 使相关查询失效，触发刷新
        queryClient.invalidateQueries({ queryKey: ['health-assessment', user?.id] });
        // 同时使user profile相关查询失效，因为评估可能影响profile显示
        queryClient.invalidateQueries({ queryKey: ['user-profile', user?.id] });
      }
    },
  });

  return {
    assessment: query.data || null,
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
    createAssessment: createMutation.mutateAsync,
    isCreating: createMutation.isPending,
    refresh: () => query.refetch(),
  };
}

/**
 * useAllHealthAssessmentsQuery - 获取所有健康评估列表
 */
export function useAllHealthAssessmentsQuery() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  // 查询：使用 React Query
  const query = useQuery({
    queryKey: ['health-assessments-all', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const result = await healthAssessmentService.getAllAssessments();
      if (result.error) throw result.error;
      return result.data || [];
    },
    enabled: !!user?.id,
    staleTime: 5 * 60 * 1000, // 5分钟缓存
  });

  // 删除评估：使用 React Query Mutation
  const deleteMutation = useMutation({
    mutationFn: (id: string) => healthAssessmentService.deleteAssessment(id),
    onSuccess: () => {
      // 使相关查询失效，触发刷新
      queryClient.invalidateQueries({ queryKey: ['health-assessments-all', user?.id] });
      queryClient.invalidateQueries({ queryKey: ['health-assessment', user?.id] });
    },
  });

  return {
    assessments: query.data || [],
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
    deleteAssessment: deleteMutation.mutateAsync,
    isDeleting: deleteMutation.isPending,
    refresh: () => query.refetch(),
  };
}

/**
 * useHealthScores - 健康评分计算Hook
 * 从HealthReportPage.tsx中提取的评分计算逻辑
 */

import { useMemo } from 'react';
import { calculateHealthScores, getImprovementGoal } from '../utils/healthAssessmentScoring';

interface SavedAssessmentData {
  diet_score: number;
  fitness_score: number;
  rest_score: number;
  psychology_score: number;
  exercise_score: number;
  overall_score: number;
  primary_improvement_area: string;
}

interface UseHealthScoresOptions {
  questionnaireData: any;
  savedAssessment: SavedAssessmentData | null;
  isReassessment: boolean;
  isViewingMode: boolean;
}

export function useHealthScores({
  questionnaireData,
  savedAssessment,
  isReassessment,
  isViewingMode,
}: UseHealthScoresOptions) {
  // OPTIMIZATION: Memoize scores calculation to prevent unnecessary recalculations
  // CRITICAL: In reassessment mode, ALWAYS calculate fresh scores from new data
  const scores = useMemo(() => {
    // In reassessment mode, ignore savedAssessment and always calculate fresh
    if (isReassessment) {
      return calculateHealthScores(questionnaireData);
    }

    // In viewing mode with saved assessment, use saved scores
    if (savedAssessment && isViewingMode) {
      return {
        diet: savedAssessment.diet_score,
        fitness: savedAssessment.fitness_score,
        rest: savedAssessment.rest_score,
        psychology: savedAssessment.psychology_score,
        exercise: savedAssessment.exercise_score,
        overall: savedAssessment.overall_score,
        primaryImprovementArea: savedAssessment.primary_improvement_area,
      };
    }

    // First-time onboarding or no saved data - calculate fresh
    return calculateHealthScores(questionnaireData);
  }, [savedAssessment, questionnaireData, isReassessment, isViewingMode]);

  // OPTIMIZATION: Memoize radar data to prevent unnecessary recalculations and re-renders
  const radarData = useMemo(() => [
    { dimension: '饮食', score: scores.diet, fullMark: 100 },
    { dimension: '作息', score: scores.rest, fullMark: 100 },
    { dimension: '体质', score: scores.fitness, fullMark: 100 },
    { dimension: '心理', score: scores.psychology, fullMark: 100 },
    { dimension: '运动', score: scores.exercise, fullMark: 100 },
  ], [scores]);

  const improvementGoal = getImprovementGoal(scores.primaryImprovementArea);

  return {
    scores,
    radarData,
    improvementGoal,
  };
}

/**
 * useOnboardingFlow - Onboarding流程管理Hook
 * 从App.tsx中提取的Onboarding相关逻辑
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { supabase } from '../config/supabase';
import { getCurrentUserId, removeUserStorageItem } from '../utils/userStorage';

export function useOnboardingFlow() {
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [isReassessment, setIsReassessment] = useState(false);
  const [checkingOnboarding, setCheckingOnboarding] = useState(true);
  const [checkingOnboardingAfterLogin, setCheckingOnboardingAfterLogin] = useState(false);
  const [onboardingJustCompleted, setOnboardingJustCompleted] = useState(false);
  const [initialAppReady, setInitialAppReady] = useState(false);
  const [showOnboardingNutritionSolution, setShowOnboardingNutritionSolution] = useState(false);
  
  const onboardingCheckLockRef = useRef(false);
  const previousUserIdRef = useRef<string | null>(null);

  const clearOnboardingState = useCallback(async () => {
    console.log('🧹 [useOnboardingFlow] Clearing all onboarding state from localStorage');
    
    await Promise.all([
      removeUserStorageItem('onboarding_step'),
      removeUserStorageItem('onboarding_data'),
      removeUserStorageItem('onboarding_completed'),
      removeUserStorageItem('onboarding_skipped'),
      removeUserStorageItem('health_report_saved'),
      removeUserStorageItem('step14_profile_saved')
    ]);
    
    console.log('✅ [useOnboardingFlow] Onboarding state cleared');
  }, []);

  const checkOnboardingStatus = useCallback(async (userId: string | null) => {
    if (onboardingCheckLockRef.current) {
      console.log('⏸️ [useOnboardingFlow] Onboarding check already in progress, skipping');
      return;
    }

    if (onboardingJustCompleted) {
      console.log('⏸️ [useOnboardingFlow] Onboarding just completed, skipping check');
      setCheckingOnboarding(false);
      return;
    }

    try {
      onboardingCheckLockRef.current = true;

      if (!userId) {
        await clearOnboardingState();
        setShowOnboarding(false);
        setCheckingOnboarding(false);
        return;
      }

      const { data: profileData } = await supabase
        .from('user_profiles')
        .select('has_seen_onboarding')
        .eq('user_id', userId)
        .maybeSingle();

      // 清理过时的localStorage标志
      await Promise.all([
        removeUserStorageItem('onboarding_completed'),
        removeUserStorageItem('onboarding_skipped')
      ]);

      if (profileData?.has_seen_onboarding) {
        await Promise.all([
          removeUserStorageItem('onboarding_step'),
          removeUserStorageItem('onboarding_data'),
          removeUserStorageItem('health_report_saved')
        ]);
      }

      const needsOnboarding = !profileData || !profileData.has_seen_onboarding;
      setShowOnboarding(needsOnboarding);
    } catch (error) {
      console.error('❌ [useOnboardingFlow] Error checking onboarding status:', error);
    } finally {
      setCheckingOnboarding(false);
      onboardingCheckLockRef.current = false;
    }
  }, [onboardingJustCompleted, clearOnboardingState]);

  const handleOnboardingComplete = useCallback(() => {
    setOnboardingJustCompleted(true);
    setShowOnboarding(false);
    setInitialAppReady(true);
  }, []);

  const handleStartReassessment = useCallback(() => {
    setIsReassessment(true);
    setShowOnboarding(true);
  }, []);

  // 当用户切换时重置状态
  useEffect(() => {
    const currentUserId = previousUserIdRef.current;
    if (currentUserId) {
      setShowOnboarding(false);
      setOnboardingJustCompleted(false);
      setIsReassessment(false);
    }
    previousUserIdRef.current = null;
  }, []);

  return {
    showOnboarding,
    setShowOnboarding,
    isReassessment,
    setIsReassessment,
    checkingOnboarding,
    checkingOnboardingAfterLogin,
    setCheckingOnboardingAfterLogin,
    onboardingJustCompleted,
    setOnboardingJustCompleted,
    initialAppReady,
    setInitialAppReady,
    showOnboardingNutritionSolution,
    setShowOnboardingNutritionSolution,
    checkOnboardingStatus,
    handleOnboardingComplete,
    handleStartReassessment,
    clearOnboardingState,
  };
}

import { useMemo } from 'react';
import { isSameDay, isSameWeek, formatDateChinese, getWeekRange } from '../utils/dateUtils';

/**
 * 通用记录过滤hook
 * 根据selectedPeriod过滤记录：
 * - 天：只显示当天的记录
 * - 周：只显示当周的记录
 * - 月/年：返回空对象（不显示记录）
 * 
 * @param records 记录数组，必须包含recorded_at字段
 * @param selectedPeriod 选中的时间段
 * @param selectedDate 选中的日期
 * @param getRecordsByDate 可选：用于获取特定日期的记录的函数（如果记录需要额外处理）
 * @returns 按日期分组的记录对象 { [date: string]: T[] }
 */
export function useRecordFilter<T extends { recorded_at: string }>(
  records: T[],
  selectedPeriod: '天' | '周' | '月' | '年',
  selectedDate: Date,
  getRecordsByDate?: (date: Date) => T[]
): { [key: string]: T[] } {
  return useMemo(() => {
    console.log('🔍 [useRecordFilter] Starting filter:', {
      recordsCount: records.length,
      selectedPeriod,
      selectedDate: selectedDate.toISOString(),
      selectedDateLocal: selectedDate.toLocaleString('zh-CN')
    });

    // 月/年不显示记录
    if (selectedPeriod === '月' || selectedPeriod === '年') {
      console.log('⚠️ [useRecordFilter] Period is 月 or 年, returning empty');
      return {};
    }

    const groups: { [key: string]: T[] } = {};

    if (selectedPeriod === '天') {
      // 只显示当天的记录 - 统一使用isSameDay确保时区一致性
      const dayRecords = records.filter(record => {
        const isSame = isSameDay(record.recorded_at, selectedDate);
        if (records.length <= 5) {
          console.log('🔍 [useRecordFilter] Day check:', {
            recordDate: record.recorded_at,
            recordDateLocal: new Date(record.recorded_at).toLocaleString('zh-CN'),
            selectedDate: selectedDate.toISOString(),
            isSameDay: isSame
          });
        }
        return isSame;
      });

      console.log('📊 [useRecordFilter] Day records filtered:', dayRecords.length, 'out of', records.length);

      if (dayRecords.length > 0) {
        const dateStr = formatDateChinese(selectedDate);
        groups[dateStr] = dayRecords;
      }
    } else if (selectedPeriod === '周') {
      // 只显示当周的记录 - 统一使用isSameWeek确保时区一致性
      console.log('🔍 [useRecordFilter] Filtering week records...');
      const weekRecords = records.filter((record, index) => {
        const isSame = isSameWeek(record.recorded_at, selectedDate);
        // 输出前3条记录的详细匹配信息，帮助调试
        if (index < 3) {
          console.log('🔍 [useRecordFilter] Week check:', {
            index,
            recordDate: record.recorded_at,
            recordDateLocal: new Date(record.recorded_at).toLocaleString('zh-CN'),
            selectedDate: selectedDate.toISOString(),
            selectedDateLocal: selectedDate.toLocaleString('zh-CN'),
            isSameWeek: isSame
          });
        }
        return isSame;
      });

      console.log('📊 [useRecordFilter] Week records filtered:', weekRecords.length, 'out of', records.length);

      // 按日期分组
      weekRecords.forEach(record => {
        const dateStr = formatDateChinese(record.recorded_at);
        if (!groups[dateStr]) {
          groups[dateStr] = [];
        }
        groups[dateStr].push(record);
      });
    }

    console.log('✅ [useRecordFilter] Final groups:', {
      groupCount: Object.keys(groups).length,
      groups: Object.keys(groups),
      totalRecords: Object.values(groups).flat().length
    });

    // 按日期倒序排列
    return Object.fromEntries(
      Object.entries(groups).sort((a, b) => {
        const dateA = new Date(a[0].replace(/\//g, '-'));
        const dateB = new Date(b[0].replace(/\//g, '-'));
        return dateB.getTime() - dateA.getTime();
      })
    );
  }, [records, selectedPeriod, selectedDate, getRecordsByDate]);
}

/**
 * useSleepChartData - 睡眠图表数据计算Hook
 * 从SleepDetailScreen.tsx中提取的图表数据计算逻辑
 * 符合架构规范：单一职责，减少组件复杂度
 */

import { useMemo } from 'react';
import { formatTimeChinese, getBeijingTime } from '../utils/dateUtils';

interface SleepRecord {
  id: string;
  value: number;
  recorded_at: string;
  notes?: string;
}

interface ChartDataPoint {
  label?: string;
  time?: string;
  value: number;
  date?: string;
  recorded_at?: string;
}

interface UseSleepChartDataOptions {
  records: SleepRecord[];
  selectedPeriod: '天' | '周' | '月' | '年';
  currentDate: Date;
  getRecordsByDate: (date: Date) => SleepRecord[];
  formatDate: (date: Date) => string;
}

export function useSleepChartData({
  records,
  selectedPeriod,
  currentDate,
  getRecordsByDate,
  formatDate,
}: UseSleepChartDataOptions) {
  // 计算图表数据
  const chartData = useMemo(() => {
    const data: ChartDataPoint[] = [];
    
    if (selectedPeriod === '天') {
      // 天视图：只取最新的一条记录
      const dayRecords = getRecordsByDate(currentDate);
      const latestRecord = dayRecords.length > 0 
        ? dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0]
        : null;
      if (latestRecord) {
        data.push({ 
          time: formatTimeChinese(latestRecord.recorded_at),
          value: latestRecord.value,
          date: formatDate(currentDate),
          recorded_at: latestRecord.recorded_at
        });
      }
    } else if (selectedPeriod === '周') {
      // 周视图：每天只取最新的一条记录
      const weekStart = new Date(currentDate);
      const dayOfWeek = weekStart.getDay();
      const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
      weekStart.setDate(weekStart.getDate() + diff);
      weekStart.setHours(0, 0, 0, 0);
      
      for (let i = 0; i < 7; i++) {
        const date = new Date(weekStart);
        date.setDate(weekStart.getDate() + i);
        const beijingDate = getBeijingTime(date);
        const dayRecords = getRecordsByDate(date);
        const latestRecord = dayRecords.length > 0 
          ? dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0]
          : null;
        data.push({ 
          label: `${String(beijingDate.getMonth() + 1).padStart(2, '0')}/${String(beijingDate.getDate()).padStart(2, '0')}`, 
          value: latestRecord ? latestRecord.value : 0,
          date: `${String(beijingDate.getMonth() + 1).padStart(2, '0')}/${String(beijingDate.getDate()).padStart(2, '0')}`,
          recorded_at: latestRecord?.recorded_at
        });
      }
    } else if (selectedPeriod === '月') {
      // 月视图：每天只取最新的一条记录
      const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
      for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
        const dayRecords = getRecordsByDate(date);
        const latestRecord = dayRecords.length > 0 
          ? dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0]
          : null;
        data.push({ 
          label: String(day), 
          value: latestRecord ? latestRecord.value : 0,
          date: String(day),
          recorded_at: latestRecord?.recorded_at
        });
      }
    } else {
      // 年视图：每月取平均值
      const year = currentDate.getFullYear();
      for (let month = 0; month < 12; month++) {
        const startDate = new Date(year, month, 1);
        const endDate = new Date(year, month + 1, 0);
        const monthRecords: SleepRecord[] = [];
        
        for (let day = 1; day <= endDate.getDate(); day++) {
          const date = new Date(year, month, day);
          const dayRecords = getRecordsByDate(date);
          if (dayRecords.length > 0) {
            // 每天只取最新的一条记录
            const latestRecord = dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0];
            monthRecords.push(latestRecord);
          }
        }
        
        const monthAvg = monthRecords.length > 0 
          ? monthRecords.reduce((sum, r) => sum + r.value, 0) / monthRecords.length 
          : 0;
        data.push({ 
          label: `${month + 1}月`, 
          value: parseFloat(monthAvg.toFixed(1)),
          date: `${month + 1}月`
        });
      }
    }
    return data;
  }, [selectedPeriod, currentDate, records, getRecordsByDate, formatDate]);

  return {
    chartData,
  };
}

/**
 * useStepsChartData - 步数图表数据计算Hook
 * 从StepsDetailScreen.tsx中提取的图表数据计算逻辑
 * 符合架构规范：单一职责，减少组件复杂度
 */

import { useMemo } from 'react';
import { formatTimeChinese, getBeijingTime, formatWeekLabel } from '../utils/dateUtils';

interface StepsRecord {
  id: string;
  value: number;
  recorded_at: string;
  notes?: string;
}

interface ChartDataPoint {
  label: string;
  value: number;
  date?: string;
  time?: string;
  recorded_at?: string;
}

interface UseStepsChartDataOptions {
  records: StepsRecord[];
  timePeriod: 'day' | 'week' | 'month' | 'year';
  currentWeekStart: Date;
  getRecordsByDate: (date: Date) => StepsRecord[];
  formatDate: (date: Date) => string;
}

export function useStepsChartData({
  records,
  timePeriod,
  currentWeekStart,
  getRecordsByDate,
  formatDate,
}: UseStepsChartDataOptions) {
  // 计算图表数据
  const chartData = useMemo(() => {
    const data: ChartDataPoint[] = [];

    if (timePeriod === 'day') {
      // 天视图：按时间段分组（00:00-06:00, 06:00-12:00, 12:00-18:00, 18:00-24:00）
      const dayRecords = getRecordsByDate(currentWeekStart);
      const timePeriods = [
        { label: '00:00', start: 0, end: 6 },
        { label: '06:00', start: 6, end: 12 },
        { label: '12:00', start: 12, end: 18 },
        { label: '18:00', start: 18, end: 24 }
      ];

      return timePeriods.map(period => {
        const periodRecords = dayRecords.filter(record => {
          const recordDate = new Date(record.recorded_at);
          const hour = recordDate.getHours();
          return hour >= period.start && hour < period.end;
        });
        const total = periodRecords.reduce((sum, r) => sum + (r.value || 0), 0);
        return {
          label: period.label,
          value: total,
          date: period.label,
          time: period.label
        };
      });
    } else if (timePeriod === 'week') {
      // 周视图：计算周一到周日，每天累加
      const weekStart = new Date(currentWeekStart);
      const dayOfWeek = weekStart.getDay();
      const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
      weekStart.setDate(weekStart.getDate() + diff);
      weekStart.setHours(0, 0, 0, 0);

      for (let i = 0; i < 7; i++) {
        const date = new Date(weekStart);
        date.setDate(weekStart.getDate() + i);
        const beijingDate = getBeijingTime(date);
        const dayRecords = getRecordsByDate(date);
        const totalSteps = dayRecords.reduce((sum: number, record: StepsRecord) => sum + (record.value || 0), 0);
        const latestRecord = dayRecords.length > 0 
          ? dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0]
          : null;
        data.push({
          label: `${String(beijingDate.getMonth() + 1).padStart(2, '0')}/${String(beijingDate.getDate()).padStart(2, '0')}`,
          value: totalSteps,
          date: `${String(beijingDate.getMonth() + 1).padStart(2, '0')}/${String(beijingDate.getDate()).padStart(2, '0')}`,
          time: latestRecord ? formatTimeChinese(latestRecord.recorded_at) : '',
          recorded_at: latestRecord?.recorded_at
        });
      }
    } else if (timePeriod === 'month') {
      // 月视图：每天累加
      const year = currentWeekStart.getFullYear();
      const month = currentWeekStart.getMonth();
      const daysInMonth = new Date(year, month + 1, 0).getDate();

      for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(year, month, day);
        const dayRecords = getRecordsByDate(date);
        const totalSteps = dayRecords.reduce((sum: number, record: StepsRecord) => sum + (record.value || 0), 0);
        const latestRecord = dayRecords.length > 0 
          ? dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0]
          : null;
        data.push({
          label: String(day),
          value: totalSteps,
          date: String(day),
          time: latestRecord ? formatTimeChinese(latestRecord.recorded_at) : '',
          recorded_at: latestRecord?.recorded_at
        });
      }
    } else if (timePeriod === 'year') {
      // 年视图：每月累加
      const year = currentWeekStart.getFullYear();

      for (let month = 0; month < 12; month++) {
        const endDate = new Date(year, month + 1, 0);
        let monthTotal = 0;
        let latestRecord: StepsRecord | null = null;

        for (let day = 1; day <= endDate.getDate(); day++) {
          const date = new Date(year, month, day);
          const dayRecords = getRecordsByDate(date);
          monthTotal += dayRecords.reduce((sum: number, record: StepsRecord) => sum + (record.value || 0), 0);
          if (dayRecords.length > 0) {
            const dayLatest = dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0];
            if (!latestRecord || new Date(dayLatest.recorded_at) > new Date(latestRecord.recorded_at)) {
              latestRecord = dayLatest;
            }
          }
        }

        data.push({
          label: `${month + 1}`,
          value: monthTotal,
          date: `${month + 1}月`,
          time: latestRecord ? formatTimeChinese(latestRecord.recorded_at) : '',
          recorded_at: latestRecord?.recorded_at
        });
      }
    }

    return data;
  }, [timePeriod, currentWeekStart, records, getRecordsByDate, formatDate]);

  return {
    chartData,
  };
}

/**
 * useUserProfileQuery - 用户档案查询Hook
 * 使用React Query管理用户档案数据
 */

import React from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuth } from '../contexts/AuthContext';
import { userProfileService } from '../services/userProfileService';
import type { UserProfile } from '../utils/bmrCalculations';

export function useUserProfileQuery() {
  const queryClient = useQueryClient();
  const { user, isAuthenticated } = useAuth();

  // 查询用户档案
  const query = useQuery({
    queryKey: ['user-profile', user?.id],
    queryFn: async () => {
      if (!user?.id) {
        throw new Error('User not authenticated');
      }
      console.log('🔍 [useUserProfileQuery] Fetching profile for user:', user.id);

      // ✅ 添加超时控制，避免长时间等待
      const timeoutPromise = new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error('Profile query timeout after 5 seconds')), 5000);
      });

      return Promise.race([
        userProfileService.getProfile(user.id),
        timeoutPromise
      ]);
    },
    enabled: !!user?.id && isAuthenticated, // 确保用户已认证且user.id存在
    staleTime: 10 * 60 * 1000, // 10分钟缓存（用户配置变化频率低）
    retry: 1, // ✅ 减少重试次数从2到1，避免长时间等待
    retryDelay: 1000, // 重试延迟1秒
    refetchOnWindowFocus: false, // ✅ 登录后不要因为窗口聚焦就重新获取
    refetchOnReconnect: true, // 网络重连时自动刷新
  });

  // 更新用户档案
  const updateMutation = useMutation({
    mutationFn: (updates: Partial<UserProfile>) => {
      if (!user?.id) {
        throw new Error('User not authenticated');
      }
      return userProfileService.updateProfile(user.id, updates);
    },
    onSuccess: (updatedProfile) => {
      // 更新查询缓存
      queryClient.setQueryData(['user-profile', user?.id], updatedProfile);
      // 失效相关查询
      queryClient.invalidateQueries({ queryKey: ['user-profile', user?.id] });
    },
  });

  // 添加调试日志
  React.useEffect(() => {
    if (user?.id) {
      console.log('👤 [useUserProfileQuery] State:', {
        userId: user.id,
        isAuthenticated,
        enabled: !!user?.id && isAuthenticated,
        isLoading: query.isLoading,
        hasData: !!query.data,
        profileData: query.data,
        isError: query.isError,
        error: query.error?.message,
        errorDetails: query.error,
      });
    } else {
      console.log('⚠️ [useUserProfileQuery] No user ID or not authenticated:', {
        hasUser: !!user,
        userId: user?.id,
        isAuthenticated,
      });
    }
  }, [user?.id, isAuthenticated, query.isLoading, query.data, query.isError, query.error]);

  return {
    profile: query.data || null,
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
    updateProfile: updateMutation.mutateAsync,
    isUpdating: updateMutation.isPending,
    refresh: () => {
      console.log('🔄 [useUserProfileQuery] Manual refresh triggered');
      return query.refetch();
    },
  };
}

/**
 * useWaterChartData - 饮水图表数据计算Hook
 * 从WaterDetailScreen.tsx中提取的图表数据计算逻辑
 * 符合架构规范：单一职责，减少组件复杂度
 */

import { useMemo } from 'react';
import { formatTimeChinese, getBeijingTime } from '../utils/dateUtils';

interface WaterRecord {
  id: string;
  value: number;
  recorded_at: string;
  notes?: string;
}

interface ChartDataPoint {
  date: string;
  value: number;
  recorded_at?: string;
  time?: string;
}

interface UseWaterChartDataOptions {
  records: WaterRecord[];
  selectedPeriod: '天' | '周' | '月' | '年';
  selectedDate: Date;
  getRecordsByDate: (date: Date) => WaterRecord[];
}

export function useWaterChartData({
  records,
  selectedPeriod,
  selectedDate,
  getRecordsByDate,
}: UseWaterChartDataOptions) {
  // 计算图表数据
  const chartData = useMemo(() => {
    const data: ChartDataPoint[] = [];
    const today = getBeijingTime(selectedDate);

    if (selectedPeriod === '天') {
      // 天视图：按时间段分组（00:00-06:00, 06:00-12:00, 12:00-18:00, 18:00-24:00）
      const dayRecords = getRecordsByDate(today);
      const timePeriods = [
        { label: '00:00', start: 0, end: 6 },
        { label: '06:00', start: 6, end: 12 },
        { label: '12:00', start: 12, end: 18 },
        { label: '18:00', start: 18, end: 24 }
      ];

      return timePeriods.map(period => {
        const periodRecords = dayRecords.filter(record => {
          const recordDate = new Date(record.recorded_at);
          const hour = recordDate.getHours();
          return hour >= period.start && hour < period.end;
        });
        const total = periodRecords.reduce((sum, r) => sum + (r.value || 0), 0);
        return {
          date: period.label,
          value: total,
          time: period.label
        };
      });
    } else if (selectedPeriod === '周') {
      // 计算周的开始日期（周一）
      const weekStart = new Date(today);
      const dayOfWeek = weekStart.getDay();
      const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek; // 如果是周日，回到上周一
      weekStart.setDate(weekStart.getDate() + diff);

      // 显示周一到周日的7天数据 - 每天累加所有记录
      for (let i = 0; i < 7; i++) {
        const date = new Date(weekStart);
        date.setDate(weekStart.getDate() + i);
        const beijingDate = getBeijingTime(date);
        const dayRecords = getRecordsByDate(date);
        const totalAmount = dayRecords.reduce((sum, record) => sum + (record.value || 0), 0);
        const latestRecord = dayRecords.length > 0 
          ? dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0]
          : null;
        const dateStr = `${String(beijingDate.getMonth() + 1).padStart(2, '0')}/${String(beijingDate.getDate()).padStart(2, '0')}`;
        const recordTime = latestRecord ? formatTimeChinese(latestRecord.recorded_at) : '';
        data.push({ date: dateStr, value: totalAmount, recorded_at: latestRecord?.recorded_at, time: recordTime });
      }
    } else if (selectedPeriod === '月') {
      // 显示当前月份每天的数据 - 每天累加所有记录
      const year = today.getFullYear();
      const month = today.getMonth();
      const daysInMonth = new Date(year, month + 1, 0).getDate();

      for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(year, month, day);
        const dayRecords = getRecordsByDate(date);
        const totalAmount = dayRecords.reduce((sum, record) => sum + (record.value || 0), 0);
        const latestRecord = dayRecords.length > 0 
          ? dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0]
          : null;
        const dateStr = String(day);
        const recordTime = latestRecord ? formatTimeChinese(latestRecord.recorded_at) : '';
        data.push({ date: dateStr, value: totalAmount, recorded_at: latestRecord?.recorded_at, time: recordTime });
      }
    } else if (selectedPeriod === '年') {
      // 显示12个月的数据 - 每月累加所有记录
      const year = today.getFullYear();

      for (let month = 0; month < 12; month++) {
        const endDate = new Date(year, month + 1, 0);
        let monthTotal = 0;
        let latestRecord: WaterRecord | null = null;

        for (let day = 1; day <= endDate.getDate(); day++) {
          const date = new Date(year, month, day);
          const dayRecords = getRecordsByDate(date);
          monthTotal += dayRecords.reduce((sum, record) => sum + (record.value || 0), 0);
          if (dayRecords.length > 0) {
            const dayLatest = dayRecords.sort((a, b) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())[0];
            if (!latestRecord || new Date(dayLatest.recorded_at) > new Date(latestRecord.recorded_at)) {
              latestRecord = dayLatest;
            }
          }
        }

        const dateStr = `${month + 1}月`;
        const recordTime = latestRecord ? formatTimeChinese(latestRecord.recorded_at) : '';
        data.push({ date: dateStr, value: monthTotal, recorded_at: latestRecord?.recorded_at, time: recordTime });
      }
    }

    return data;
  }, [selectedPeriod, selectedDate, records, getRecordsByDate]);

  // 获取上一周期的数据用于对比
  const previousPeriodData = useMemo(() => {
    if (selectedPeriod !== '月' && selectedPeriod !== '年') {
      return [];
    }

    const prevDate = new Date(selectedDate);
    if (selectedPeriod === '月') {
      prevDate.setMonth(prevDate.getMonth() - 1);
    } else {
      prevDate.setFullYear(prevDate.getFullYear() - 1);
    }

    const data: ChartDataPoint[] = [];

    if (selectedPeriod === '月') {
      const year = prevDate.getFullYear();
      const month = prevDate.getMonth();
      const daysInMonth = new Date(year, month + 1, 0).getDate();

      for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(year, month, day);
        const dayRecords = getRecordsByDate(date);
        const total = dayRecords.reduce((sum, record) => sum + record.value, 0);
        const dateStr = String(day);
        data.push({ date: dateStr, value: total });
      }
    } else if (selectedPeriod === '年') {
      const year = prevDate.getFullYear();

      for (let month = 0; month < 12; month++) {
        const endDate = new Date(year, month + 1, 0);
        let monthTotal = 0;

        for (let day = 1; day <= endDate.getDate(); day++) {
          const date = new Date(year, month, day);
          const dayRecords = getRecordsByDate(date);
          monthTotal += dayRecords.reduce((sum, record) => sum + record.value, 0);
        }

        data.push({ date: `${month + 1}月`, value: monthTotal });
      }
    }

    return data;
  }, [selectedPeriod, selectedDate, getRecordsByDate]);

  return {
    chartData,
    previousPeriodData,
  };
}

/**
 * useWaterRecordsQuery - 使用 React Query 的饮水记录 Hook
 * 符合架构规范：组件 → Hook → Supabase (3层)
 */

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useRef } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { waterService, WaterRecord } from '../services/waterService';
import { getBeijingTime, isSameDay, toLocalDateString } from '../utils/dateUtils';

export function useWaterRecordsQuery(startDate?: Date, endDate?: Date) {
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const addInFlightRef = useRef(false);

  // 查询：使用 React Query
  const query = useQuery({
    queryKey: ['water-records', user?.id, startDate?.toISOString(), endDate?.toISOString()],
    queryFn: () => {
      if (!user?.id) return [];
      return waterService.getRecords(user.id, startDate, endDate);
    },
    enabled: !!user?.id,
    staleTime: 5 * 60 * 1000, // 5分钟缓存
  });

  // 添加：使用 React Query Mutation
  const addMutation = useMutation({
    mutationFn: async ({ amount, date, notes }: { amount: number; date: Date; notes?: string }) => {
      if (!user?.id) throw new Error('User not authenticated');
      if (addInFlightRef.current) {
        throw new Error('正在保存饮水记录，请稍候');
      }
      addInFlightRef.current = true;
      try {
        return await waterService.addRecord(user.id, amount, date, notes);
      } finally {
        addInFlightRef.current = false;
      }
    },
    onSuccess: (_, variables) => {
      const dateKey = toLocalDateString(variables.date);
      queryClient.invalidateQueries({ queryKey: ['water-records', user?.id] });
      // 自动刷新 Dashboard 数据
      queryClient.invalidateQueries({ queryKey: ['dashboard-data', user?.id, dateKey] });
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({
      id,
      amount,
      date,
      notes,
    }: {
      id: string;
      amount: number;
      date: Date;
      notes?: string;
    }) => waterService.updateRecord(id, amount, date, notes),
    onSuccess: (_, variables) => {
      const dateKey = toLocalDateString(variables.date);
      queryClient.invalidateQueries({ queryKey: ['water-records', user?.id] });
      queryClient.invalidateQueries({ queryKey: ['dashboard-data', user?.id, dateKey] });
    },
  });

  // 删除
  const deleteMutation = useMutation({
    mutationFn: (id: string) => waterService.deleteRecord(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['water-records', user?.id] });
      // 刷新所有 Dashboard 数据
      queryClient.invalidateQueries({ queryKey: ['dashboard-data', user?.id] });
    },
  });

  // 辅助函数
  const getRecordsByDate = (date: Date): WaterRecord[] => {
    const records = query.data || [];
    const beijingDate = getBeijingTime(date);
    return records.filter((record: any) => {
      const recordDate = getBeijingTime(new Date(record.recorded_at));
      return isSameDay(beijingDate, recordDate);
    });
  };

  const getTotalByDate = (date: Date): number => {
    const dayRecords = getRecordsByDate(date);
    return dayRecords.reduce((sum, record) => sum + record.value, 0);
  };

  return {
    records: query.data || [],
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
    addRecord: addMutation.mutateAsync,
    updateRecord: updateMutation.mutateAsync,
    deleteRecord: deleteMutation.mutateAsync,
    isAdding: addMutation.isPending,
    isUpdating: updateMutation.isPending,
    isDeleting: deleteMutation.isPending,
    getRecordsByDate,
    getTotalByDate,
    refresh: () => query.refetch(),
  };
}

