  describe('feetInchesToCm', () => {
    it('should convert feet and inches to cm correctly', () => {
      // 5 feet 9 inches = 175.26cm ≈ 175.3cm
      const cm = feetInchesToCm(5, 9);
      expect(cm).toBe(175.3);
    });
